\section{Optimization with only global minima and convergence analysis}
\label[appsec]{sec: Appendix A}
In this section, we present proofs for \cref{thm: F} and \cref{eq: convergence thm}. First, we prove \cref{thm: F}.
\begin{proof}
    Let $(\bm r_c,\bm\theta_c)$ be a non-zero stationary point, that is $\bm r_c\neq 0$. Denote $K_c=K(\bm r_c,\bm\theta_c)$. By \eqref{opt2} and \eqref{stograd}, it follows at the stationary point,
        \begin{equation}\label{eq: real1}
        \begin{split}
        0&=\frac{\partial F}{\partial r_j}\\
        &=\frac{\partial f}{\partial r_j}+2\sum_{P\in G_2}\phi_P(\bm r_c,\bm\theta_c)\frac{\phi_P(\bm r_c,\bm\theta_c)}{\partial r_j}\\
        &= \frac{\partial f}{\partial r_j}+4\sum_{P\in G_2}\phi_P(\bm r_c,\bm\theta_c)c_{j,P}r_{j_P}\exp(i(\theta_j-\theta_{j_P})).
        \end{split}
    \end{equation}Similar to the proof of \cref{thm: f}, by multiplying $r_j$ to \eqref{eq: real1} and summing over $j$'s, we arrive at
    \begin{equation}\label{eq: F=0}
    \begin{split}
        0&= 4f(\bm r_c,\bm \theta_c)+ 4\sum_jr_j\left(\sum_{P\in G_2}\phi_P(\bm r_c,\bm\theta_c)c_{j,P}r_{j_P}\exp(i(\theta_j-\theta_{j_P}))\right)\\
        &=4f(\bm r_c,\bm \theta_c)+ 4\sum_{P\in G_2}\phi_P(\bm r_c,\bm\theta_c)\left(\sum_jc_{j,P}r_jr_{j_P}\exp(i(\theta_j-\theta_{j_P}))\right)\\
        &=4f(\bm r_c,\bm\theta_c)+4\sum_{P\in G_2}\phi_P(\bm r_c,\bm\theta_c)^2=4F(\bm r_c,\bm \theta_c),
    \end{split}
    \end{equation}by definition of $\phi_P$ in \cref{lem: constraint}. Since $F(\bm r_c,\bm \theta_c)=0$, $(\bm r_c,\bm \theta_c)$ is a global minimum of the cost function in \eqref{opt2}.

    Now we prove that $K$ is unitary up to scaling. Noting that $\sum_{P\in G_2}\phi_P(\bm r_c,\bm\theta_c)^2=0$ from \eqref{eq: F=0}, we know from \cref{lem: constraint} that
    \begin{equation}
        K(\bm r_c,\bm\theta_c)^\dagger K(\bm r_c,\bm\theta_c) = \norm{\bm r_c}^2I.
    \end{equation}Additionally, since $f(\bm r_c,\bm\theta_c)=0$, it immediately follows that $K(\bm r_c,\bm\theta_c)^\dagger H K(\bm r_c,\bm\theta_c)$ is a diagonal matrix, which results that
    \begin{equation}
        H = \frac{1}{\norm{\bm r}^4}K(\bm r_c,\bm\theta_c)h(\bm r_c,\bm\theta_c)K(\bm r_c,\bm\theta_c)^\dagger,
    \end{equation}where $h(\bm r_c,\bm\theta_c):=K(\bm r_c,\bm\theta_c)^\dagger HK(\bm r_c,\bm\theta_c)$. This completes the proof.


\end{proof}
This proof shows that the optimization problem we consider has only global minima as stationary points, and especially any non-zero stationary point yields a diagonalization unitary $K$. Moreover, the following proof guarantees that \cref{alg: algorithm1} converges to a non-zero stationary point.
\begin{proof}
Since the function in \eqref{opt2} is a polynomial of degree $4$ with respect to $\bm r$ and $\bm \theta$ appear there as the phase factors that do not affect the magnitude of the function,  we can find a constant $L>0$ such that
\begin{equation}\label{eq: constants GL}
     \max_{\norm{\bm r(\bm x)}\leq 2}\norm{\nabla^2 F(\bm x)}\leq L,
\end{equation}in the neighborhood of radius $2$   defined in the $\bm r$ direction. To proceed, we derive a recursive inequality for \cref{alg: algorithm1}. Suppose that $\norm{\bm r(\bm x_t)}=1$, as \cref{alg: algorithm1} calls for normalization about $\bm r$ at each iteration. 

From the definition of $\bm y_t$ in \cref{alg: algorithm1} and the condition on $\bm x_t$, we notice that
\begin{equation}\label{eq: norm y}
\begin{split}
\norm{\bm r(\bm y_t)}^2 &= \sum_j((\bm r(\bm x_t))_j-a\frac{\partial F}{\partial r_j}(\bm x_t))^2=\norm{\bm r(\bm x_t)}^2-2a\bm r(\bm x_t)\cdot\nabla_r F(\bm x_t) + a^2\norm{\nabla_rF(\bm x_t)}^2\\
& = 1-8aF(\bm x_t) + a^2\norm{\nabla_rF(\bm x_t)}^2
\end{split}
\end{equation}where $\nabla_rF:=(\frac{\partial F}{\partial r_1},...,\frac{\partial F}{\partial r_N})^T$. The last equality follows from \cref{prop: grad-cost}. We derive a lower bound for $\norm{\bm r(\bm y_t)}$. By applying the Cauchy-Schwarz inequality to \cref{prop: grad-cost} in \eqref{eq: norm y}, we have
\begin{equation}\label{eq: norm y lb}
    \norm{\bm r(\bm y_t)}^2\geq 1-8aF(\bm x_t) + 16a^2F(\bm x_t)^2\geq 1-8aF(\bm x_t).
\end{equation}Then for any $a\leq \frac{2}{L}$, we achieve that
\begin{equation}\label{eq: y-x}
\begin{split}
    F(\bm y_{t})&\leq F(\bm x_t) - a\norm{\nabla F(\bm x_t)}^2+\frac{La^2}{2}\norm{\nabla F(\bm x_t)}^2 \\
    &\leq F(\bm x_t) - \frac{a}{2}\norm{\nabla F(\bm x_t)}^2\\
    &\leq (1- 2\mu aF(\bm x_t)^{\alpha-1})F(\bm x_t).
\end{split}
\end{equation}The last inequality holds by the assumption \eqref{eq: kl condition}. By \eqref{eq: norm y lb} and \eqref{eq: y-x}, we observe that 
\begin{equation}\label{eq: reineq}
\begin{split}
    F(\bm x_{t+1})=\frac{1}{\norm{\bm r(\bm y_t)}^4}F(\bm y_t)&\leq \frac{1-2\mu aF(\bm x_t)^{\alpha-1}}{\left(1-8aF(\bm x_t)\right)^2}F(\bm x_t)\\
    &\leq \frac{1-2\mu aF(\bm x_t)^{\alpha-1}}{1-16aF(\bm x_t)}F(\bm x_t)\\
    &\leq \left(1-(2\mu-16F(\bm x_t)^{2-\alpha})aF(\bm x_t)^{\alpha-1}\right)F(\bm x_t)\\
    &\leq \left(1-\mu aF(\bm x_t)^{\alpha-1}\right)F(\bm x_t),
\end{split}
\end{equation}when $F(\bm x_t)\leq \left(\frac{\mu}{16}\right)^{\frac{1}{2-\alpha}}$. To find the number of iterations $T$ to achieve $\epsilon$ precision, we solve the following inequality,
\begin{equation}
    \epsilon\leq \left(1-\mu a\epsilon^{\alpha-1}\right)^TF(\bm x_0).
\end{equation}
Therefore, for a reasonable initial guess $\bm x_0$, \cref{alg: algorithm1} requires the number of iterations scaling as 
\begin{equation}
    T=\mathcal{O}\left(\frac{L}{\mu  \epsilon^{\alpha-1}}\log\frac{F(\bm x_0)}{\epsilon}\right).
\end{equation}


\end{proof}




\section{Sensitivity analysis for numerical solutions}
\label[appsec]{sec: Appendix B}
In this section, we prove \cref{lem: perturb} and  \cref{thm: perturb}. First, we prove \cref{lem: perturb}.
\begin{proof}
For ease of notation in analysis, we omit the parameters $\bm r, \bm \theta$ unless stated otherwise. Recalling the set $G_1$ in \eqref{opt} and denoting $G_3=\{\otimes_{i=1}^n\sigma^{(i)} :\sigma^{(i)}\in\{I,X,Y,Z\} \text{ and }\forall i\in[n],\;  \sigma^{(i)}\in\{I,Z\}\}$, we define 
\begin{equation}\label{eq: h0 Delta}
h_0= \frac{1}{2^n}\sum_{P\in G_3} \tr(K^\dagger H KP)P,\quad \Delta = \frac{1}{2^n}\sum_{P\in G_1} \tr(K^\dagger H KP)P,
\end{equation}which sum to the $K^\dagger HK$, thus verifying \cref{h0Delta}. 
By definition \eqref{opt}, we observe that
\begin{equation}
    \norm{\Delta}_F^2=\frac{1}{2^n}\sum_{P\in G_1} \tr(K^\dagger H KP)^2=\frac{f}{2^n}\leq \frac{F}{2^n},
\end{equation}since $f\leq F$ by \eqref{opt2}. This proves the first statement of \cref{lem: perturb}. For the second statement, by our assumptions, we have from the proof of \cref{lem: constraint} that,
\begin{equation}\label{eq: KK close to I}
    \norm{K^\dagger K-I}_F^2 =\norm{\sum_{P\in G_2}\phi_P(\bm r,\bm \theta)P}_F^2=2^n\sum_{P\in G_2}\phi_P(\bm r,\bm \theta)^2\leq \epsilon\leq \frac{1}{4}.
\end{equation}Note that the inverse of $K$ exists, and 
    \begin{equation}
        \norm{K^{-1}}_2^2=\norm{(K^\dagger K)^{-1}}_2=\norm{(K^\dagger K-I+I)^{-1}}_2\leq \frac{1}{1-\sqrt{\epsilon}}\leq 2.
    \end{equation}From this, we have the error in the spectral norm, 
\begin{equation}
    \begin{split}
        \norm{H-\widetilde{H}}_2&=\norm{(K^\dagger)^{-1}K^\dagger\left(H-\widetilde{H}\right)KK^{-1}}_2\\
        &=\norm{(K^\dagger)^{-1}\left(h_0+\Delta-K^\dagger \widetilde{H}K\right)K^{-1}}_2\\
        &=\norm{(K^\dagger)^{-1}\left(h_0+\Delta-K^\dagger Kh_0K^\dagger K\right)K^{-1}}_2\\
        & \leq 2\norm{h_0+\Delta-K^\dagger Kh_0K^\dagger K}_2.
    \end{split}
    \end{equation} The term in the last line is bounded above as
    \begin{equation}
        \begin{split}
            &\norm{h_0+\Delta -K^\dagger Kh_0K^\dagger K}_F\\
            &=\norm{h_0+\Delta -(K^\dagger K-I+I)h_0(K^\dagger K-I+I)}_F\\
            &=\norm{\Delta -(K^\dagger K-I)h_0(K^\dagger K-I)-(K^\dagger K-I)h_0-h_0(K^\dagger K-I)}_F\\
            &\leq \frac{F}{2^n}+3\norm{h_0}_F\sqrt{\epsilon}.
        \end{split}
    \end{equation}

    Finally, noting that
    \begin{equation}
\norm{h_0}_F^2=\frac{1}{2^n}\sum_{p\in\mathfrak{h}}\tr(K^\dagger HKp)^2\leq \frac{1}{2^n}\norm{K^\dagger HK}_F^2\leq \frac{1}{2^n}\norm{K^\dagger K}_F^2\norm{H}_F^2\leq (1+\sqrt{F})^2\norm{H}_F^2,
    \end{equation}with the above results, we obtain 
    \begin{equation}
        \norm{H-\widetilde{H}}_2\leq \frac{F}{2^{n-1}}+6(1+\sqrt{F})\norm{H}_F\sqrt{\epsilon},
    \end{equation}which proves the second statement of \cref{lem: perturb}.

\end{proof}
This completes the proof of \cref{lem: perturb}. Using the result, we prove \cref{thm: perturb} that gives an approximation error bound of diagonalization of Hamiltonian for a numerical solution obtained from our algorithm. 
\begin{proof}From \cref{lem: perturb},  we notice that
$\norm{H-\widetilde{H}}_2\leq \epsilon'$. Next, we refer to the proof of \cite[Lemma 5]{ko2024quantum} from which we can deduce that 
 \begin{equation}
     \bra{\widetilde{\psi}_j}P_{\lambda_k(H)}\ket{\widetilde{\psi}_j}\geq 1-(C+1)\epsilon',
 \end{equation}where $\widetilde{\psi}_j$ denotes any eigenvector of $P_{k,\widetilde{H}}$ and the constant $C$ depends on the eigenvalues of $H$ by considering a fixed polynomial approximation in the Stone-Weierstrass theorem to the indicator function in \cite[eq (38)]{ko2024quantum}.  By summing this inequality over $j$'s, we have
 \begin{equation}
     \text{tr}\left(P_{k,\widetilde{H}}P_{\lambda_k(H)}\right)\geq \text{rank}(P_{\lambda_k(H)})\left(1-(C+1)\epsilon'\right),
 \end{equation}since $\text{rank}(P_{k,\widetilde{H}}) =\text{rank}(P_{\lambda_k(H)})$, and therefore
 \begin{equation}
 \begin{split}
     &\norm{P_{k,\widetilde{H}}-P_{\lambda_k(H)}}_F^2\leq 2\text{rank}(P_{\lambda_k(H)})-2\text{tr}\left(P_{k,\widetilde{H}}P_{\lambda_k(H)}\right)\\
     &\leq 2\text{rank}(P_{\lambda_k(H)})(C+1)\epsilon'\leq 2\max_k\text{rank}(P_{\lambda_k(H)})(C+1)\epsilon'.
 \end{split}
 \end{equation}Therefore,  the statement is proven.
\end{proof}


\section{Quantum diagonalizable Hamiltonians whose Lie algebras are exponentially large}
\label[appsec]{sec: Appendix C}
In this section, we prove that the Lie algebras of Hamiltonians in \cref{ex: Hams} are exponentially sized.
\begin{proof}
We consider the trivial case where $\prod_{m=1}^{\lfloor \log n\rfloor}U_m=I$. If $\mathfrak{g}(H)=\text{su}(2^n)$ in this case, then any Hamiltonian in \cref{ex: Hams} would satisfy the same property.

To proceed, we make use of the result in \cite{smith2024optimally}, which states that the set,
\begin{equation}\label{eq: su-generator}
    \{Z_1, Z_2, X_1, X_2, Z_1Z_2\}\cup\{X_2Y_3...Z_j, Z_2Y_3...X_j|3\leq j\leq n\}, 
\end{equation}generates all Pauli strings in the sense of dynamical Lie algebra. Noticing that the second factor of $U$ consists of mutually-anticommuting Pauli strings, we see that the constraint that $\sum_{j=0}^nc_j^2=1$ and $c_j$'s are real suffices to ensure that $U$ is a unitary, a property of the anticommuting Pauli strings \cite{izmaylov2019unitary,ryabinkin2023efficient}. Now we prove the statement by showing that all Pauli strings in the set \eqref{eq: su-generator} are contained in the Hamiltonian $H$ and its dynamical Lie algebra.

First, we observe that $U$ contains the identity $I$ as its component, since $i\sin\theta Z_2\times c_2Z_2 = ic_2\sin\theta I$ and $c_2,\theta\neq 0$. This implies that $H$ contains the set $\{X_2Y_3..Z_j|3\leq j \leq n\}$, since the elements of Pauli string are chosen from $U\times I\times ic_2\sin\theta I$ in the multiplication $UDU^\dagger$. Similarly, we can find that $Z_1Y_2\times Y_2\times I=Z_1$, $X_1Y_2\times Y_2\times I=X_1$, $Z_2\times I\times I=Z_2$, $Z_2\times Y_2\times I=X_2$, and $Z_1X_2\times Y_2\times I=Z_1Z_2$. Notice that  $Z_1X_2$ is in $U$ due to the multiplication, $i\sin\theta Z_2\times c_1Z_1Y_2$. Lastly, we are left to show that the Pauli strings in $\{Z_2Y_3...X_j|3\leq j\leq n\}$ are contained in $\mathfrak{g}(H)$. We observe that since $I\times Y_j\times I=Y_j$, $Y_j$'s are in $H$. Since  $H$ contains the set $\{X_2Y_3..Z_j|3\leq j \leq n\}$ as shown above, and  $[[X_2Y_3...Z_j,Y_2],Y_j]$ equals $Z_2Y_3...X_j$ up to a scaling factor, it happens that $\mathfrak{g}(H)$ also contains the set $\{Z_2Y_3...X_j|3\leq j\leq n\}$. Therefore, $\mathfrak{g}(H)$ contains the generating set \eqref{eq: su-generator} and all $n$-qubit Pauli strings.

\end{proof}

