\title{Distributed Affine Formation Control of Linear Multi-agent Systems with Adaptive Event-triggering}
\author{Chenjun Liu, Jason J. R. Liu,~\IEEEmembership{Member,~IEEE,} Zhan Shu,~\IEEEmembership{Senior~Member,~IEEE,} and James Lam,~\IEEEmembership{Fellow,~IEEE}
