\subsection{Some known results}

Let us now review some known results relevant to us.
First, the low complexity assumption $P_c(D) \leq |D|$ implies the existence of non-trivial periodizers and annihilators:

\begin{lemma}[\cite{icalp}]
  \label{th:low_complexity}
  Let $c \in \A^{\Z^d}$ be a configuration that has low complexity with respect to shape $D = \{\bd_1,\ldots,\bd_m\} \Subset \Z^d$, that is, $P_c(D) \leq |D|$.
  % $D = \{ \bd_1, \ldots , \bd_m$.
  Then $c$ has a non-trivial annihilator. 
  More precisely, $c$ has a periodizer of the form 
  $$
  a_1 X^{-\bd_1} + \ldots + a_m X^{-\bd_m}
  $$
   for some non-zero $(a_1,\ldots,a_m) \in \C^m$.
\end{lemma}

\noindent
If a configuration has a non-trivial periodizer, then it has an annihilator which is a product of difference polynomials:

%Consequently, a configuration with a non-trivial annihilator is a sum of periodic functions.
%More precisely, we have the following theorems. 

\begin{theorem}[\cite{icalp}, \cite{fullproofs}] \label{special annihilator configurations}
  Let $c \in \A^{\Z^d}$ be an integral configuration with a non-trivial integral annihilator $f$.
  Then for all $\bu \in \supp(f)$ the configuration $c$ has an annihilator of the form
  $$
  (X^{\vec{v}_1} - 1) \cdots (X^{\vec{v}_m} - 1)
  $$
  where the vectors $\vec{v}_1, \ldots , \vec{v}_m$ are pairwise linearly independent and each $\bv_i$ is parallel to $\bu_i - \bu$ for some $\bu_i \in \supp(f) \setminus \{\bu\}$.
  % Moreover, $c$ is a sum of (not necessarily finitary) functions $c_1, \ldots , c_m \in \Z^{\Z^d}$ such that each $c_i$ is $\vec{v}_i$-periodic.
\end{theorem}

\noindent
The multiplication of $c$ by a difference polynomial can be seen as a ``discrete derivation'' of $c$.
The above theorem says then that if an integral configuration $c\in \A^{\Z^d}$ has a non-trivial periodizer, then there is a sequence of derivations which annihilates $c$.
So, by using an an ``integration'' argument step by step we have the following periodic decomposition theorem.

\begin{theorem}[Periodic decomposition theorem \cite{fullproofs}]\label{thm: regular decomposition theorem}
  Let $c \in \A^{\Z^d}$ be an integral configuration with a non-trivial integral annihilator $f$.
  Then $c=c_1+\ldots+c_m$ where $c_1,\ldots,c_m \in \Z^{\Z^d}$ are periodic in pairwise linearly independent directions.
\end{theorem}


% \noindent
% The proof of the above theorem is based on Hilbert's Nullstellensatz.

% In \cite{icalp,kari-szabados-multidimensional_words} it was given an example of a configuration (the \emph{snowflake configuration}) with non-trivial annihilators which is not a sum of finitely many periodic configurations.
A \emph{dilation} of a polynomial $f(X)$ is a polynomial of the form $f(X^k)$ for some integer $k$.
The following lemma is crucial in the proof of Theorem \ref{special annihilator configurations} and in our forthcoming considerations.




\begin{lemma}[The dilation lemma \cite{fullproofs}]
  Let $c \in \A^{\Z^d}$ be an integral configuration, and let $f$ be a non-trivial 
  integral annihilator of $c$. 
  There exists a positive integer $r$ such that for every positive integer $k$ with $\gcd(k,r)=1$ also $f(X^k)$ annihilates $c$.
\end{lemma}

\noindent
Let us call a number $r$ that has the property of the above lemma a \emph{dilation constant} of $c$ with respect to $f$.
From the proof of the dilation lemma we adapt the following result.
For completeness, we provide a short description of the proof.

\begin{lemma}[Adapted from \cite{fullproofs}] \label{lemma2}
  Let $\mathcal{I}$ be an arbitrary index set, and let $\left ( c^{(i)} \right ) _{i \in \mathcal{I}}$ be a collection of integral configurations over the same alphabet $\A \Subset \Z$.
  If $f$ is a non-trivial integral annihilator of $c^{(i)}$ for every $i \in \mathcal{I}$, then the configurations in the collection have a common dilation constant with respect to $f$.
\end{lemma}

\begin{proof}
Let $c_{\text{max}}$ be the maximum absolute value of the coefficients of the configurations $c^{(i)}$.
Since the configurations $c^{(i)}$ are over the same alphabet, such number exists.
Let $f = \sum_{\bv \in \supp(f)} f_{\bv}X^{\bv}$ and define $s= c_{\text{max}} \sum_{\bv \in \supp(f)} |f_{\bv}|$.
In the proof of the dilation lemma in \cite{fullproofs}, it was shown that $r=s!$ is a dilation constant of any $c^{(i)}$.
The claim follows.
\end{proof}


