It is known that sufficiently small patch-complexity of a Delone set implies its strong periodicity as the following theorem shows.
% Asymptotically, the theorem implies that if $N_S(T) = o(T)$, then $S$ is strongly periodic.

\begin{theorem}[\cite{lagarias_pleasants_2}] \label{thm:forced periodicity Lagarias}
  Let $S$ be a Delone set with covering radius $R$.
  If 
  $$
  N_S(T) < \frac{T}{2R}
  $$
  for some $T>0$, then $S$ is strongly periodic, that is, it has $d$ linearly independent periods.
\end{theorem}

