\section{Meyer sets with slow patch-complexity growth} \label{sec: meyer sets}


In this section we consider Meyer sets with slow patch-complexity growth.
In particular, we show that if a Meyer set $S$ satisfies $\liminf_{T \to \infty} \frac{N_S(T)}{T^d} = 0$, then it has low complexity with respect to some $\R^d$-shape.
Consequently, it has a non-trivial annihilator as we will see in Section \ref{sec: delone configurations with annihilators}.

Consider the set $U = (S+S-S) \cap B_R$ for a Meyer set S with covering radius $R$.
The following lemma shows that this set is finite.

% So, assume that $S \subseteq \R^d$ is a Meyer set with covering radius $R$.
% Define a set $U = (S+S-S) \cap B_R$.
% This set is finite: % since $S$ is a Meyer set:

\begin{lemma}\label{lemma:the set U  is finite for Meyer}
  Let $S \subseteq \R^d$ be a Meyer set. 
  % with covering radius $R$.
  % and $U = (S+S-S) \cap B_R$.
  The set $S+S-S$ is locally finite.
  % and hence
  % the set $U = (S+S-S) \cap B_R$ is finite.
\end{lemma}

% \bigskip
% \noindent
% \textbf{Claim 1.} 
% The set $S+S-S$ is locally finite and hence
% the set $U$ is finite.

\begin{proof}
  Without loss of generality we may assume that $S$ is translated such that $\vec{0} \in S$.
  Since $S$ is a Meyer set, there exists a finite set $F$ such that $S-S \subseteq S+F$.
  Using this twice and the fact that $\vec{0} \in S$ we get

  \begin{align*}
  S+S-S &\subseteq S+S-S-S = S-S - (S-S) \\
  &\subseteq S + F - (S + F) = S-S + F - F \\
  &\subseteq S + F + F - F.
  \end{align*}

  \noindent
  Lemma \ref{closed under addition with a finite set} says that the sum of a Delone set of finite local complexity and a non-empty finite set is also a Delone set of finite local complexity.
  In particular, $S + F + F - F$ is uniformly discrete since $F+F-F$ is a non-empty finite set.
  This implies that $S+S-S$ is also uniformly discrete as a subset of a uniformly discrete set.
  The claim follows since uniformly discrete sets are locally finite.
\end{proof}

% \noindent
% If in the above theorem the Delone set $S$ was not a Meyer set, then the set $S+S-S$ would not be a locally finite set.
% Indeed, assume that $S$ is a Delone set but not a Meyer set. Then the set $S-S$ is not uniformly discrete.
% It follows that $(S+S-S) \cap B_R$ is not finite.

\noindent
Define for every $T \geq 0$ a set
$H_T = U \cup (S \cap B_T)$.
This is a finite set since $U$ is a finite set as seen above and since $S$ is a Delone set (and hence $S \cap B_T$ is a finite set).
% We show that $S$ has low complexity with respect to $H_T$ for all sufficiently large $T$ if N_S(T) = O(T^{d-1}).
We start by the observation that any non-empty $H_T$-pattern of $S$ contains an element of $S$ already in its $U$-part.

\begin{lemma} \label{lemma:Meyer H_T contains a point in its U-part}
  Let $S \subseteq \R^d$ be a Meyer set with covering radius $R$, and let $U = (S+S-S) \cap B_R$.
  Define for every $T \geq 0$ a set
  $H_T = U \cup (S \cap B_T)$.
  If $S \cap (H_T + \vec{t}) \neq \emptyset$, then also $S \cap (U + \vec{t}) \neq \emptyset$.
\end{lemma}

% \bigskip
% \noindent
% \textbf{Claim 2.}
% If $S \cap (H_T + \vec{t}) \neq \emptyset$, then also $S \cap (U + \vec{t}) \neq \emptyset$.

\begin{proof}
  Assume that $\vec{u} \in S \cap (H_T + \vec{t})$.
  If $\vec{u} \in U + \vec{t}$, then the claim is valid and we are done.
  So, assume that $\vec{u} \in (H_T \setminus U) + \vec{t}$.
  Since $H_T \setminus U \subseteq S$, we have $\vec{u} - \vec{t} \in S$.
  By the definition of $R$ we have $S \cap B_R(\vec{t}) \neq \emptyset$.
  So, let $\vec{w} \in S \cap B_R(\vec{t})$.
  We claim that $\vec{w} \in U + \vec{t}$, {\it i.e.}, $\vec{w} - \vec{t} \in U$.
  This follows from the observation that
  $$
  \vec{w}-\vec{t} = \vec{w} - \vec{u} + \vec{u} -\vec{t} = \vec{w} + (\vec{u} - \vec{t}) - \vec{u} \in S+S-S
  $$
  and from the fact that $\vec{w} - \vec{t} \in B_R$.
\end{proof}

\noindent
We have the following upper bound for $P_S(H_T)$.

\begin{lemma} \label{lemma:Meyer bound for the complexity of H_T}
  Let $S \subseteq \R^d$ be a Meyer set with covering radius $R$, and let $U = (S+S-S) \cap B_R$.
  Define for every $T \geq 0$ a set
  $H_T = U \cup (S \cap B_T)$.
  Then
  $$
  P_S(H_T) \leq 1 + |U| N_S(T + R).
  $$
\end{lemma}

% \bigskip
% \noindent
% \textbf{Claim 3.}
% $$
% P_S(H_T) \leq 1 + |U| N_S(T + R).
% $$

\begin{proof}
  Let $P$ be a non-empty $H_T$-pattern of $S$, that is, $P = S \cap (H_T + \bt) \neq \emptyset$ for some $\bt \in \R^d$.
  Then by Lemma \ref{lemma:Meyer H_T contains a point in its U-part} it contains a point already in its $U$-part, that is, $\bu + \bt \in P$ for some $\bu \in U$.
  Clearly, $P$ is contained in the $(T+R)$-patch of $S$ centered at $\bu + \bt$.
    So, the $(T+R)$-patch centered at $\bu+\bt$ together with $\bu$ uniquely determines the $H_T$-pattern centered at $\bt$.
  Hence, the number of non-empty $H_T$-patterns up to translation is at most $|U| N_S(T + R)$.
  % Hence, the number of non-empty $H_T$-patterns up to translation is at most the number of $(T+R)$-patches of $S$ centered at points of $U$, that is, at most $|U| N_S(T + R)$.
  Thus,
  $$
  P_S(H_T) \leq 1 + |U| N_S(T + R)
  $$
  since the empty set is always in $\Patt{H_T}{S}$.
\end{proof}


Let us now analyze the size of $H_T$. 
It contains the set $S \cap B_T$.
Since $R$ is the covering radius of $S$, any ball of radius $R$ must contain at least one point of $S$.
Hence, the number of points of $S \cap B_T$ is at least the number of separate balls of radius $R$ contained in $B_T$.
We give a rough lower bound for $|S \cap B_T|$ which is also a lower bound for $|H_T|$.
Consider the hypercube
$$
C = \left \{ (u_1,\ldots,u_d) \mid |u_i| \leq \frac{T}{\sqrt{d}} \right \}
$$
contained in $B_T$ with sides of length $\frac{2T}{\sqrt{d}} $.
It is contained in $B_T$.
Write
$$
