\begin{lemma} \label{lemma: non-trivial annihilator}
  Let $c \in \C^{\R^d}$ be an $\R^d$-configuration and let $D = \{ \bd_1, \ldots , \bd_m \} \Subset \R^d$ be an $\R^d$-shape.
  If $c$ has low complexity with respect to $D$, that is, if
  $P_c(D) \leq m$, then $c$ has a periodizer of the form 
  $$a_1 X^{-\bd_1} + \ldots + a_m X^{-\bd_m}$$
for some non-zero $(a_1,\ldots,a_m) \in \C^m$.
\end{lemma}

\begin{proof} 
  Consider the set
  $$
  V = \left \{ (1, c_{\vec{d}_1+\vec{v}}, \ldots, c_{\vec{d}_m+\vec{v}}) \mid \vec{v} \in \R^d \right \}.
  $$
  The subspace $L(V) \subseteq \C^{m+1}$ generated by $V$ has dimension at most $m$ since $|V| = P_c(D) \leq  m$.
  Thus, $L(V)^{\bot}$ is non-trivial. Let $ (\overline{a}_0, \ldots, \overline{a}_m) \in L(V)^{\bot} \setminus \{ \vec{0} \}$. Then
  $$
  a_0 \cdot 1 + a_1 \cdot c_{\vec{d}_1 + \vec{v}} + \ldots + a_m \cdot c_{\vec{d}_m+\vec{v}} = 0
  $$
  for all $\vec{v} \in \R^d$. 
  Thus, $a_1 X^{- \vec{d}_1} + \ldots + a_n X^{- \vec{d}_m}$ is a non-trivial periodizer of $c$.
\end{proof}

