The following theorem is a generalization of Theorem \ref{special annihilator configurations}.

\begin{theorem} \label{main result 1}
  Let $c$ be an integral $\R^d$-configuration and assume that it has a non-trivial integral annihilator $f$. 
  Then for every $\bu \in \supp(f)$ it has an annihilator of the form
  $$
  (X^{\vec{v}_1} - 1) \cdots (X^{\vec{v}_m} - 1)
  $$
  where each $\bv_i$ is parallel to $\bu_i - \bu$ over $\Q$ for some $\bu_i \in \supp(f) \setminus \{ \bu  \}$.
  Moreover, the vectors $\bv_i$ can be chosen to be pairwise linearly independent over $\Q$.
\end{theorem}

\begin{proof}
  Assume that $f = \sum_{i=1}^n f_i X^{\bu_i}$ for some non-zero $f_i \in \Z$ where $\supp(f) = \{ \vec{u}_1, \ldots , \vec{u}_n \}$. 
  Define for any $\vec{u} \in \R^d$ a $\Z^n$-configuration 
  $c^{(\vec{u})} \in \A^{\Z^n}$
  over the same finite alphabet $\A$ as $c$ such that 
  $$
  c^{(\vec{u})}(i_1, \ldots, i_n) = c(\vec{u} + i_1 \vec{u}_1 + \ldots + i_n \vec{u}_n)
  $$
  for all 
  $(i_1,\ldots,i_n) \in \Z^n$. 

  The polynomial $g = 
  g(T) = g(t_1, \ldots, t_n) = \sum_{i=1}^n f_i t_i = \sum_{i=1}^n f_i T^{\be_i}$ is a non-trivial annihilator of $c^{(\vec{u})}$ for any $\vec{u} \in \R^d$ since 
  \begin{align*}
  (g c^{(\bu)})(i_1,\ldots,i_n) 
  &= f_1 c^{(\bu)}(i_1-1,i_2,\ldots,i_n) + \ldots + f_n c^{(\bu)}(i_1,\ldots,i_{n-1},i_n-1) \\
  &= f_1 c(\bu + (i_1-1) \bu_1 + i_2 \bu_2 + \ldots + i_n \bu_n) + \ldots \\
  & \ \ \ + f_n c(\bu + i_1 \bu_1 + \ldots + i_{n-1}\bu_{n-1} + (i_n - 1) \bu_n) \\
  &
  = (fc)(\bu + i_1 \bu_1 + \ldots + i_n \bu_n) \\
  &= 0
  \end{align*}
  for all $(i_1,\ldots,i_n) \in \Z^n$.

  By Lemma \ref{lemma2} the $\Z^n$-configurations $c^{(\bu)}$ have a common dilation constant with respect to $g$. 
  Moreover, by Theorem \ref{thm: special annihilator precise formulation} they have for all $\vec{e} \in \supp(g) = \{ \vec{e}_1, \ldots , \vec{e}_n \}$ a common annihilator of the form
  $$
  (T^{\vec{w}_1}-1) \cdots (T^{\vec{w}_m}-1)
  $$
  where each $\vec{w}_i$ is parallel to $\vec{e}_j - \vec{e}$ for some $\vec{e}_j \in \supp(g) \setminus \{\vec{e}\}$, that is, $\vec{w}_i = k \vec{e}_j - k \vec{e}$ for some non-zero integer $k$.
  % Thus, we have $\bw_i = k(\be_j - \be)$ and hence
  % the generalized polynomial
  % is an annihilator of $e^{(\vec{u})}$ for all $\vec{u} \in \R^d$.

  Let us denote $\vec{w}_i = (w_{i,1}, \ldots , w_{i,n})$ for $i \in \{ 1, \ldots , m \}$ and let $i_0 \in \{1,\ldots,n\}$ be such that $\be = \be_{i_0}$. 
  Note that each $\bw_i$ has exactly two non-zero entries, and they are equal to $k$ and $-k$.
  % Note that all except one of the entries of $\bw_i$ are zero.
  It follows that the $\R^d$-polynomial
  $$
  (X^{w_{1,1} \vec{u}_1 + \ldots + w_{1,n} \vec{u}_n} - 1) \cdots (X^{w_{m,1} \vec{u}_1 + \ldots + w_{m,n} \vec{u}_n} - 1)
  $$
  is an annihilator of $c$ such that each $w_{i,1} \vec{u}_1 + \ldots + w_{i,n} \vec{u}_n$ is parallel to $\bu_j - \bu_{i_0}$.
  This holds for all $i_0 \in \{1,\ldots,n\}$ and hence we have proved the first part of the claim.


  For the ``moreover'' part, assume 
  that
  $$
  g = (X^{\vec{v}_1} - 1) \cdots (X^{\vec{v}_m} - 1)
  $$ annihilates $c$,
  and assume that for some distinct $i,j \in \{1,\ldots,m\}$ the vectors $\bv_i$ and $\bv_j$ are parallel over $\Q$, that is, $q\bv_i= p \bv_j$ for some $p,q \in \Z\setminus\{0\}$.
  % Hence, $q \bv_i = p \bv_j$.
  We may replace $X^{\bv_i}-1$ in $g$ by $X^{p \bv_j}-1 = X^{q \bv_i}-1$.
  Since 
  $$
  X^{p \bv_j}-1 = (X^{\bv_j}-1)(X^{(p-1)\bv_j} + \ldots + X^{\bv_j} + 1),
  $$
   we may replace $(X^{p\bv_j}-1)(X^{\bv_j}-1)$ by $(X^{p\bv_j}-1)^2$.
  Iterating this argument we conclude that $c$ has an annihilator
  $$
  (X^{\bw_1}-1)^{e_1} \cdots (X^{\bw_k}-1)^{e_k}
  $$
  where the vectors $\bw_1,\ldots,\bw_k$ are pairwise linearly independent over $\Q$ and $e_1,\ldots,e_k$ are positive integers.
  Consequently, the $\R^d$-configuration 
  $$(X^{\bw_2}-1)^{e_2} \cdots (X^{\bw_k}-1)^{e_k}c$$ 
  is annihilated by $(X^{\bw_1}-1)^{e_1}$.
  By Lemma \ref{lemma:difference polynomial power annihilator} it is periodic in direction $\bw_1$.
  Repeating this argument 
  % for $j \in \{2,\ldots,k\}$ 
  we conclude that $c$ is annihilated by
  $$
  (X^{r_1 \bw_1}-1) \cdots (X^{r_k \bw_k}-1)
  $$
  for some non-zero $r_1,\ldots,r_k\in \Z$ and hence we have proved the claim.
\end{proof}

