    There exists a function $c \in \Z^{\R^d}$ such that $(X^{\bv_1}-1)c=c'$ and $(X^{\bv_2}-1)c = 0$.
    % If $c'\in \Z^{\R^d}$, then we may choose also $c \in \Z^{\R^d}$.
\end{lemma}

