\begin{lemma}\label{lemma:forced2}
Let $(\bv_n')_{n\geq 1}$ be a converging sequence of vectors $\bv_1',\bv_2',\ldots \in \mathbf{S}^1$, and let $\bv$ be the limit of this sequence.
Let $T_0 \in \R_+$ and $\bu\in \R^d$ be such that
$$
\bu \in B_{T_0}^{\circ}(-T_0 \bv).
$$
There exists $N_0 \in \Z_+$ such that
$$
\bu \in B_{T}^{\circ}(-T \bv'_{n})
$$
for all $T \geq T_0$ whenever $n \geq N_0$.
