  % $$
  % F \setminus \{\vec{0}\} \subseteq B_{R}^{\circ}(-R \bv'_{R})
  % $$
  % for all $R \geq R_0$.
\end{lemma}

\begin{proof}
Let $\varepsilon= 1- \frac{d(-T_0 \bv, \bu)}{T_0}$.
This is a positive real number by the assumption $\bu \in B_{T_0}^{\circ}(-T_0 \bv)$.
Since $\bv = \lim_{n \to \infty} \bv_n'$, there exists $N_0$ such that
  $d(\bv_n',\bv) < \varepsilon$ for all $n \geq N_0$.  
By the triangle inequality we have
$$
  d(-T_0 \bv_{n}', \bu) \leq
  d(-T_0 \bv_{n}', -T_0 \bv) + d(-T_0 \bv, \bu)
  <
  T_0 \cdot \varepsilon + d(-T_0 \bv, \bu)
  = T_0
$$  
for all $n \geq N_0$.
Thus, $\bu \in B_{T_0}^{\circ}(-T_0 \bv_{n}')$ and hence
$\bu \in B_T^{\circ}(-T\bv_n')$ for all $T \geq T_0$ and $n \geq N_0$ since $B_{T_0}^{\circ}(-T_0 \bv_{n}') \subseteq B_{T}^{\circ}(-T \bv_{n}')$ for all $ T \geq T_0$.
\end{proof}


