To $\s$-top-reduce $(f,a\sigma)$ by $G$ in Line \ref{line_sGB_stopred} of Algorithm \ref{alg_sGB}, we use Algorithm \ref{alg_sigtopred}. It is a modification of the tropical division algorithm (privided in the paper of \cite{ADH2023}). In this algorithm, we only allow $\s$-top-reducers in $G$ with respect to $a\sigma$ and reducers from the previous computed operators $q_{j'}$'s, $j'<j$ as a reducer of $q_j$ (see Line \ref{line_sigtopred_reducers}). The termination reason of Algorithm \ref{alg_sigtopred} is the same reason of termination of tropical division algorithm, that is, by the fact that the number of supports $\supp(q_j)$'s for operators $q_j$'s with a fixed degree is finite (see the paper of \cite{ADH2023}). In addition, if there is no a reducer found for $q_j$, then the algorithm is immediately terminated (see Line \ref{line_sigtopred_noreducer}).
The proof that the outputs satisfy (i) and (ii) follows the proof in the tropical division algorithm. Moreover, due to the hypothesis on $G$ --- a Gr\"{o}bner basis up to signature $a\sigma$, the output $r$ is an $\s$-top-irreducible operator with respect to $a\sigma$ (Clause (iii) of the algorithm output).


\begin{algorithm}[H]
\caption{$\s$-Top-Reduction}\label{alg_sigtopred}
\BlankLine
\KwInput{$f\in I$ homogeneous, $a\in K^*$, \ $\sigma\in \mathbb{M}_{\xi}$ such that $\mathcal{S}(f)=a\sigma$;\\
\quad\quad\quad \ $G\!=\!\{g_1,\cdots,g_{s}\}\!\subset\! R$ containing homogeneous elements $g_i$'s of  an $\s$-Gr\"{o}bner basis with $\s(g_i)<a\sigma$.
}

\KwOutput{$H_1,\cdots,H_{s},r\in R$ satisfying:
\begin{enumerate}[(i)]
\item $f=\left(\sum_{i=1}^{s}H_ig_i\right)+r$
\item $\LT_h(H_{i}g_i)\leq_h \LT_h(f)$;
\item there is no $\s$-top-reducer in $G$ for $r$ with respect to $a\sigma$.
\end{enumerate}
}
\BlankLine 
$T\leftarrow G$, \ \ \ $j\leftarrow 0$, \ \ \ $q_0\leftarrow f$, \quad $h_{1,0}\leftarrow0,\cdots,h_{s,0}\leftarrow0$\label{line_sigtopred_init}

\BlankLine
\SetAlgoLined
\SetKwBlock{Begin}{While $q_j\neq 0$ do}{}
\Begin{
    \SetAlgoLined
    \SetKwBlock{Begin}{If \normalfont there is no an $\s$-top-reducer in $G$ for $q_j$ w.r.t. $a\sigma$ AND there is no $g\in T\backslash G$ with $\LM_h(g)|\LM_h(q_j)$ {\bf then}}{}
    \Begin{\label{line_sigtopred_noredcondition}
      {\bf Return:} \ $r:=q_j$,\quad $H_i=h_{i,j}$ ~ for all $i$\label{line_sigtopred_noreducer}
    }
    \SetAlgoVlined
    \SetKwBlock{Begin}{else}{}
    \Begin{
      {\bf Choose} an $\s$-top-reducer $g\in G$ for $q_j$ w.r.t. $a\sigma$ \ OR \ an element $g\in T\backslash G$ with $\LM_h(g)\mid\LM_h(q_j)$; such that $E(q_j,mg)$ is minimum among all such choices, for some $m\in\mathcal{M}^{(h)}$ satisfying $\LM_h(q_j)=\LM_h(mg)$.\label{line_sigtopred_reducers}\\
     \BlankLine
      $c={\rm LC}_h(q_j)/{\rm LC}_h(mg)$\label{line_sigtopred_c}\\
      $q'\leftarrow q_j-c\,mg$\label{line_sigtopred_cancelation}\\
      \BlankLine
      \SetAlgoVlined
      \SetKwBlock{Begin}{If {\normalfont $g=g_k$ for some $1\leq k\leq s$} then}{}
      \Begin{\label{line_sigtopred_caseG}
        $q_{j+1}\leftarrow q'$\label{line_sigtopred_cancelationG};\\
        $h_{k,j+1}\leftarrow h_{k,j}+c\, m$;\\
        $h_{i,j+1}\leftarrow h_{i,j}$ for $i\neq k$
      }
      \SetKwBlock{Begin}{If {\normalfont $g$ was added to $T$ at some previous iteration of the algorithm, namely $g=q_k$ for some $k<j$}, then}{}
      \Begin{\label{line_sigtopred_caseTminG}
        $q_{j+1}\leftarrow \frac{1}{1-c}q'$\label{line_sigtopred_qj1}\\
        $h_{i,j+1}\leftarrow \frac{1}{1-c}(h_{i,j}-c\,h_{i,k})$ for all $i$\label{line_sigtopred_hj1}\\
      }
      \SetAlgoVlined
      \BlankLine
      \SetKwBlock{Begin}{If $E(q_j,m\,g)>0$ then}{}
      \Begin{
        $T\leftarrow T\cup\{q_j\}$
      }
    }
    $j=j+1$
}
{\bf Return}  $r:=q_j$,\quad $H_i=h_{i,j}$ ~  for all $i$.\label{line_sigtopred_rzero}
\end{algorithm}

\vspace{1ex}
\begin{prop}\label{prop_nochangesig}
When Algorithm \ref{alg_sigtopred} outputs the result, we have either
$\sigma\in\lsyz{\mathcal{F}} \ \text{ or } \ \sigma=\s(r)$.
\end{prop}
\begin{proof}
If $f=0$, then $r=q_0=f$ (see Line \ref{line_sigtopred_init} and Line \ref{line_sigtopred_rzero}). Since $a\sigma$ is a guessed signature of $f$, we get $\sigma\in\lsyz{\mathcal{F}}$.

\noindent
Now, assume that $f\neq 0$.
Since $q_0=f$, we have $S(q_0)=a\sigma$.
Let $\q^{(0)}$ be a module element of $R^{\sn}$ such that $\LM_{\rm sign}(\q^{(0)})=a\sigma$ and $\nu(\q^{(0)})=q_0$.

\noindent
When $j=0$ (the first iteration), we have $T\backslash G=\emptyset$, and hence, there are two possibilities about reducers for $q_0$: (1) no reducer from $T$ (the argument/condition in Line \ref{line_sigtopred_noredcondition} is true); (2) there is an $\s$-top-reducer $g'\in G$ for $q_0$ w.r.t. $a\sigma$. If Case (1) occurs, then $r=q_0=f$, $\s(r)=\sigma$ (by the second statement of Theorem \ref{thm_fzeroiff}), and the process terminates. If Case (2) occurs, then we have $g=g'$ and $m=m'$ for some $m'\in \mathcal{M}^{(h)}$ such that $\LM_h(q_0)=\LM_h(m'g')$. Let $\g^{(0)}\in R^{\sn}$ be such that $\LT_{\rm sign}(\g^{(0)})=\s(g)$ and $\nu(\g^{(0)})=g$. By Line \ref{line_sigtopred_cancelation} and Line \ref{line_sigtopred_cancelationG}, we have $q_{1}=q_0-cmg$, and its corresponding module representation is $\q^{(1)}:=\q^{(0)}-cm\g$. Since $g$ is $\s$-top-reducer for $q_0$ with respect to $a\sigma$, we get $\LM_{\rm sign}(\q^{(1)})=a\sigma$. We keep this last equation for the next step ($j=1$).

\noindent
When $j=1$, we have $T\backslash G\neq\emptyset$, and hence, we have three possibilities about reducers for $q_1$: 
\begin{enumerate}[(A)]
\vspace{-0.45ex}
\item no reducer from $T$ (the argument/condition in Line \ref{line_sigtopred_noredcondition} is true);
\vspace{-0.75ex}
\item the reductor is an $\s$-top-reducer $g'\in G$ for $q_1$ w.r.t. $a\sigma$; and
\vspace{-0.75ex}
\item the reductor is an operator $g\in T\backslash G$ ($g=q_0$).
\end{enumerate}
Case (A) is an analogue of Case (1) which result $r=q_1$ and $\s(r)=\sigma$. Case (B) is analogue of Case (2). Write $g=g'$ and $m=m'$ for some $m'\in \mathcal{M}^{(h)}$ such that $\LM_h(q_1)=\LM_h(m'g')$. Let $\g^{(1)}\in R^{\sn}$ be such that $\LT_{\rm sign}(\g^{(1)})=\s(g)$ and $\nu(\g^{(1)})=g$. By the algorithm, we have $q_{2}=q_1-cmg$, and its corresponding module representation is $\q^{(2)}:=\q^{(1)}-cm\g$. Since $g$ is $\s$-top-reducer for $q_1$ with respect to $a\sigma$, we get
$\LM_{\rm sign}(\q^{(2)})=a\sigma.$
For Case (C), write $m=m''$ for some $m''\in\mathcal{M}^{(h)}$ such that $\LM_h(q_1)=\LM_h(m''g)$. Since $\LM_h(q_1)=\LM_h(mg)$ and both $q_1$ and $g$ are homogeneous of the same degree, then we must have $m=1$. By Line \ref{line_sigtopred_cancelation} and Line \ref{line_sigtopred_qj1}, we have
\begin{equation}\label{eq_q2}
q_2=(\frac{1}{1-c})(q_1-cg).
\end{equation}
By the previous step, we can write $\q^{(1)}=a\Phi^{-1}(\sigma) + (\text{lower module terms})$. Since $g=q_0$, we can write $\q^{(0)}=a\Phi^{-1}(\sigma) + (\text{lower module terms})$. Therefore, the corresponding module representation of \eqref{eq_q2} is
\vspace{-0.5ex}
\begin{align*}
\q^{(2)}:&=\frac{1}{1-c}\left(\q^{(1)}-c\q^{(0)}\right)\\
&=\frac{1}{1-c}\left[(a\Phi^{-1}(\sigma) + (\text{lower module terms})) \ \ - \ \ c(a\Phi^{-1}(\sigma) + (\text{lower module terms}))\right]\\
&=\frac{1}{1-c}\left[(1-c)a\Phi^{-1}(\sigma) + (\text{lower module terms})\right]\\
&=a\Phi^{-1}(\sigma) + (\text{lower module terms}).
\end{align*}
We get $\LM_{\rm sign}(\q^{(2)})=a\sigma$. Thus, Case (B) and Case (C) result an operator $q_2$ and its corresponding module representation $\q^{(2)}$ with $\LM_{\rm sign}(\q^{(2)})=a\sigma$.

\noindent
In general, for $j>1$, we have an analogue result. When the process terminates due to Line \ref{line_sigtopred_noreducer}, the result is $r=q_j$ with $\s(r)=\sigma$. When the argument either in Line \ref{line_sigtopred_caseG} or in Line \ref{line_sigtopred_caseTminG} is true, we obtain an operator $q_{j+1}$ and its corresponding module representation $\q^{(j+1)}$ with $\LM_{\rm sign}(\q^{(j+1)})=a\sigma$.

\noindent
The process eventually terminates because $G$ is a finite set of homogeneous operators, and we always take a reducer $g$ with minimal \'{e}cart function value. For detail explanation, we can refer the paper of \cite{ADH2023}. When the iterations end up with $q_l=0$ for some $l$, its corresponding module representation is $\q^{(l)}$ with $\LM_{\rm sign}(\q^{(l)})=a\sigma$. This implies that $\sigma\in\lsyz{\mathcal{F}}$.
\end{proof}



