This shows (modulo some details) that our greedy matching strategy consumes $2d-\Theta(\sqrt{d})$ bits per 1 matched bit. Our back-of-the-envelope calculation suggests that, because we have $nd$ bits to consume across the $d$ strings, and we consume an average of $2d-\Theta(\sqrt{d})$ bits per matched bit, we expect to find a common subsequence of length at least $\frac{nd}{2d-\Theta(\sqrt{d})} = n(\frac{1}{2} + \Theta(\frac{1}{\sqrt{d}}))$, as desired.

However, we have to work harder to formally justify this.
Let $Z_1,Z_2,\dots$ be the random variables where $Z_i$ denotes the number of bits needed to consume to match the $i$th bit with our matching strategy.
By carefully choosing the order in which we reveal our bits, we have that $Z_1,Z_2,\dots$ are mutually independent.
Further, the $Z_i$ are identically distributed as $Z$, and thus have expectation $2d-\Theta(\sqrt{d})$.
The number of bits we matched by our strategy is the largest $L$ such that $Z_1+\cdots+Z_L\le nd$.
Importantly, because we work with Diagonal LCS, we do not need to worry that we use a different number of bits in different strings.
To show the expected number bits matched is close to our estimate, we show that, for $L_0=\frac{nd}{\E[Z]} ( 1-o(1))$, 
\begin{align}
    \Pr[Z_1+\cdots+Z_{L_0} \le nd] > 1-o(1).
    \label{eq:zsum}
\end{align}
We cannot use a standard concentration inequality because the $Z_i$ are unbounded. 
However, each $Z_i$ is the sum of at most $d$ geometric random variables.
Thus, setting $Z_i' \defeq \min(Z_i, O_d(\log n))$, we have, with high probability, $Z_i'=Z_i$ for all $i$.
We then use concentration inequalities to show $Z_1'+\cdots+Z_{L_0}'\le nd$ with high probability, and then \eqref{eq:zsum} holds.
Thus, the expected number of bits matched is at least $L_0\cdot (1-o(1)) \ge n(\frac{1}{2}+\Omega(\frac{1}{\sqrt{d}})$.
Hence, we can conclude our bound
\begin{align}
    \gamma_{2,d} \ge \frac{1}{2} + \Omega\left(\frac{1}{\sqrt{d}}\right).
\end{align}






\subsection{The Binary Upper Bound}

The upper bound follows from a counting argument.
Guruswami and Wang \cite[Lemma 2.3]{GuruswamiW14} (Lemma~\ref{lem:gw14}) bound the number of supersequences of any string of length $\ell>\frac{n}{k}$.
By applying this bound and carefully tracking the lower-order terms, we show that for $\Pr[\LCS(X_1,\dots,X_d)\ge \ell]$ is exponentially small for $\ell = \frac{n}{k}(1+\Theta(\sqrt{\frac{\log k}{d}}))$.
Our bound on the expectation follows.


\section{Preliminaries}
\label{sec:prelims}

Throughout $\log$ is base 2 unless otherwise specified, and $\ln$ is log base-$e$.
We use the following result.
\begin{lemma}\label{lem:ConditionalExpectation}
Let $Y,W_1,W_2,\dots$ be independent random variables supported on nonnegative integers where $W_1,W_2,\dots$ are identically distributed. Define \( W = W_1 + W_2 + \cdots + W_Y \). Then, 
\begin{equation}\label{eq:ConditionalExpectation}
\E[W] = \E[Y] \E[W_1].
\end{equation}
\end{lemma}


\begin{proof}
Using the law of total expectation, we have:
\[
\E[W] = \E[\E[W \mid Y]].
\]
By the linearity of expectation, given the value of \(Y\), we obtain:
\[
\E[W \mid Y] = \E[W_1] + \E[W_2] + \cdots + \E[W_Y] = Y \E[W_1].
\]
Substituting this into the equation above, we get:
\[
\E[W] = \E[Y] \E[W_1]. \qedhere
\]
\end{proof}


We also use Hoeffding's Inequality.
\begin{lemma}[Hoeffding]\label{lem:Hoeffding}
 Let \( X_1, X_2, \dots, X_n \) be independent random variables such that \( X_i \in [a_i, b_i] \) almost surely. Then, for any \( t > 0 \),
 \begin{align}\label{eq:HoeffdingIneq}
   \mathbb{P}\left( \sum_{i=1}^n X_i - \mathbb{E}\left[ \sum_{i=1}^n X_i \right] \geq t \right) \leq \exp\left( -\frac{2 t^2}{\sum_{i=1}^n (b_i - a_i)^2} \right).
 \end{align}
\end{lemma}

For $p \in (0,1)$, we define the $q$-ary entropy as
\[
H_q(p)=p\log_{q}(q-1)-p\log_{q}(p)-(1-p)\log_{q}(1-p)
\]
where \( h(p) \) is the binary entropy function.
We use the following well known estimate on binomial terms.
\begin{lemma}[see, for example, Proposition 3.3.1 of \cite{guruswami2019essential}]
We have    \label{lem:binom-apx}
\begin{align}
    \binom{m}{pm}(q-1)^{pm} \le q^{H_q(p)m}.
\end{align}
\end{lemma}

We use the following estimate for $k$-ary entropy.
\begin{lemma}[see, for example, Proposition 3.3.5 of \cite{guruswami2019essential}]
For small enough $\epsilon \in (0,\frac{1}{k})$: 
\[
H_k \left( 1 - \frac{1}{k} - \epsilon \right) \leq 1 - c_k\cdot  \epsilon^2.
\]
for constant $c_k\ge\frac{k^2}{4(k-1)\ln k}\ge \frac{k}{4 \ln k}$. 
\label{lem:h-apx}
\end{lemma}


As described in Section~\ref{sec:proofsketch}, define the expected diagonal LCS
\begin{align}
W_n  \defeq  \E \left[\max_{i_1+\cdots+i_d=n} \LCS(X^1[1\cdots i_1], \cdots, X^d[1\cdots i_d]) \right ] 
\label{eq:prefix}
\end{align}
where the randomness is over uniformly random infinite binary strings $X^1,\dots,X^d$.
The following lemma shows that the diagonal LCS equals the expected LCS up to lower order terms.
\begin{lemma}[\cite{kiwi2008}]
\label{lem:ks}
We have
\[
\gamma_{k,d}=\lim_{n \to \infty} \frac{W_{nd}}{n}
\]
\label{eq:kiwisoto}
\end{lemma}




\section{Full Proof of the $k$-ary LCS}
\label{sec:proof}
\subsection{Theorem~\ref{thm:main}, lower bound}

\begin{proof}[Proof of Theorem~\ref{thm:main}, lower bound]
By Lemma~\ref{lem:ks}, it suffices to show that there is an absolute constant $c_1>0$ such that, for sufficiently large $n$,
\begin{align}
    W_{nd} = \E \left[\max_{i_1+\cdots+i_d=nd} \LCS(X^1[1\cdots i_1], \cdots, X^d[1\cdots i_d]) \right ]  \ge n\left(\frac{1}{2} + \frac{c_1}{\sqrt{d}}\right)    
\end{align}

We now present our greedy matching strategy for finding a long ``diagonal'' common subsequence --- a common subsequence of $X^1[1\cdots i_1], \cdots, X^d[1\cdots i_d]$ for $i_1+\cdots+i_d=nd$.
Given $d$ random infinite strings $X^1,\dots,X^d$, we find a  the LCS bit by bit, revealing the random bits of $X^1,\dots,X^d$ as we need them.
Importantly, because the bits are independently random, we can reveal them in any desired order. Use the following process:
\begin{enumerate}  
    \item Initialize a string $s$ to the empty string, representing our common subsequence of $X^1,\dots,X^d$.
    \item Repeat the following
    \begin{enumerate}
        \item Reveal the next unrevealed bit $b_1,\dots,b_d$ in each of $X^1,\dots,X^d$.
        \item Let $b$ be the majority bit among these $d$ bits. 
        \item For each string $X^j$ that did not reveal the majority bit ($b_i\neq b$), reveal bits of $X^j$ until we reveal a bit equal to $b$. 
        \item If number of revealed bits is at most $nd$, append $b$ to $s$, else exit.
        \end{enumerate}
\end{enumerate}
See Figure~\ref{fig:Matching Strategy} for an illustration of this process.
The length of the subsequence we find is the number of times we successfully complete the loop.


Let $Y$ denote the random variable that denotes the number of minority bits among $d$ uniformly random bits.
Let $Z$ denote the random variable that first samples $Y$, and is set to $d + W_1+\cdots+W_Y$, where $W_1,\dots,W_Y$ are independent geometric random variables with probability 1/2.
Because the bits are independent, the number of bits revealed in each iteration of the loop is distributed as $Z$.
Thus, letting $Z_1,Z_2,\cdots,$ be i.i.d random variables distribute as $Z$, the length of our LCS is distributed as
\begin{align}
    L_{greedy} \defeq \max(L: Z_1+\cdots+Z_L\le nd)
    \label{eq:Lgreedy}
\end{align}
We wish to lower bound $\E[L_{greedy}]$.

We start by analyzing the expectations of $Y$ and $Z$. Explicit calculations yield that, for all $d$, 
\begin{align}
    \E[Y] \le \frac{d}{2} - c\sqrt{d} 
    \label{eq:y}
\end{align}
for some absolute constant $c>0$. To see this, note that for $d$ even,
\begin{align}
\mathbb{E}[Y] 
&= \frac{1}{2^{d}}\left(\sum_{i=0}^{d/2-1} \binom{d}{i} \cdot 2i + \binom{d}{d/2} \cdot (d/2)\right) \nonumber\\
&= \frac{1}{2^{d}}\left(\sum_{i=0}^{d/2-1} 2d\cdot \binom{d-1}{i-1}  + d\cdot \binom{d-1}{d/2-1}\right) \nonumber\\
&= \frac{d}{2^d}\left(2^{d-1} - \binom{d-1}{d/2}\right) \nonumber\\
&\le \frac{d}{2} - c\sqrt{d}
\end{align}
and for $d$ odd,
\begin{align}
\mathbb{E}[Y] 
&= \frac{1}{2^{d}}\left(\sum_{i=0}^{(d-1)/2} \binom{d}{i} \cdot 2i\right) \nonumber\\
&= \frac{1}{2^{d}}\left(\sum_{i=0}^{(d-1)/2} 2d\cdot\binom{d-1}{i-1}\right) \nonumber\\
&= \frac{d}{2^d}\left(2^{d-1} - \binom{d-1}{(d-1)/2}\right)  \nonumber\\
&\le \frac{d}{2} - c\sqrt{d}
\end{align}
where $c>0$ is some absolute constant.
Thus, \eqref{eq:y} holds.
By Lemma~\ref{lem:ConditionalExpectation} we have $\E[Z]\le d + 2\E[Y] = d-2c\sqrt{d}$.

Let \( L_0 = \frac{nd}{\mathbb{E}[Z]} \left(1 - \gamma\right) \) for $\gamma=\frac{1}{100\log n}$.
We show that the sum \( \sum_{i=1}^{L_0} Z_i \) is less than \( nd \) with very high probability, so that $L_{greedy}\ge L_0$ with very high probability.
This follows from concentration inequalities, but we cannot apply the inequalities directly because our random variables $Z_i$ are unbounded.
Define truncated variables \( Z_i' = \min(Z_i, T) \) for $T=100 d \log n$, so that each $Z_i'$ is in $[0,T]$.

We show that all $Z_i=Z_i'$ with high probability.
In step 2(c), for each $X^j$, we see the correct bit $b$ within $99\log n$ steps with probability at least $1-\frac{1}{n^{99}}$.
By the union bound, this happens for all $j=1,\dots,d$ with probability at least $1-\frac{d}{n^{99}}$, in which case $Z_i\le d+99d\log n < T$ and $Z_i=Z_i'$.
Thus, union bounding over $i=1,\dots,L_0$, we have 
\begin{align}
    \Pr[\text{$Z_i=Z_i'$ for all $i=1,\dots,L_0$}]
    \ge 1-nd\cdot \frac{d}{n^{99}}\ge 1-\frac{1}{n^{97}}.
    \label{eq:zi}
\end{align}


Since $Z_1',\dots, Z_{L_0}'$ are independent, Hoeffding's inequality (Lemma~\ref{lem:Hoeffding}) implies
\[
\mathbb{P}\left[\sum_{i=1}^{L_0} Z_i' > \mathbb{E}\left[\sum_{i=1}^{L_0} Z_i'\right] + t \right] \leq \exp\left(-\frac{2t^2}{\sum_{i=1}^{L_0} T^2}\right),
\]
where $t = nd - \mathbb{E}\left[\sum_{i=1}^{L_0} Z_i'\right] = nd-L_0\cdot \E[Z'] \ge \gamma nd$. 
Substituting $t$ gives,
\begin{align}
\mathbb{P}\left[Z_1' + \dots + Z_{L_0}' > nd\right] \leq \exp\left(-\frac{\gamma^2n^2d^2}{T^2\cdot L_0}\right) \le \exp\left(-\Omega_{d}\left(\frac{n}{\log^3n}\right)\right).
\label{eq:concentrate}
\end{align}
Combining \eqref{eq:zi} and \eqref{eq:concentrate}, we have, for sufficiently large $n$
\[
\mathbb{P}\left[Z_1 + \dots + Z_{L_0} > nd\right]\le \mathbb{P}\left[Z_1' + \dots + Z_{L_0}' > nd\right] + \Pr[Z_i\neq Z_i' \text{ for some $i$}] \le \frac{2}{n^{97}}.
\]
Finally, the expected LCS length after \( nd \) bits is:
\begin{align}
\E[L_{greedy}]
&\ge\mathbb{E}\left[\max(L:Z_1 + \dots + Z_{L} \leq nd)\right] \nonumber\\
&\ge
L_0\cdot \Pr[Z_1+\cdots+Z_{L_0}\le nd]\nonumber\\
&\geq \frac{nd}{\mathbb{E}[Z]}\left(1-\gamma\right)\cdot \left(1-\frac{2}{n^{97}}\right) \nonumber\\
&\ge n\left(\frac{1}{2} + \frac{c_1}{\sqrt{d}}\right)
\end{align}
for some absolute constant $c_1>0$. Hence,
\begin{align}
\gamma_{2,d} 
&= \lim_{n \to \infty} \frac{W_{nd}}{n} \nonumber\\
&= \lim_{n \to \infty}\frac{\E[L_{greedy}]}{n} \nonumber\\
&\ge \frac{1}{2} \left( 1 + \frac{c_1}{\sqrt{d}} \right).\qedhere\nonumber
\end{align}







\end{proof}

\subsection{Theorem~\ref{thm:main}, upper bound}

We use the following lemma from \cite{GuruswamiW14} that counts superstrings of a string of a given length.
\begin{lemma}[Lemma 2.3 of \cite{GuruswamiW14}]
For any string $w$ of length $\ell>\frac{n}{k}$, the number of strings of length $n$ with $w$ as a subsequence is at most\footnote{The result in \cite{GuruswamiW14} is stated for $\ell>(1-1/k)n$, and states that there are at most $\sum_{t=\ell}^n\binom{t-1}{\ell-1}k^{n-t}(k-1)^{t-\ell}$ subsequences. However, this bound comes from a counting argument and actually holds for all $\ell$. For $\ell > n/k$, the summands increase with $t$, so bounding each summand by the $t=n$ summand gives the bound stated here.}
\label{lem:gw14}
\[
n\cdot \binom{n-1}{\ell-1}(k-1)^{n-\ell}.
\]
\end{lemma}
\begin{proof}[Proof of Theorem~\ref{thm:main}, upper bound]
    With hindsight, let $c_0=16$, and let $\ell = \frac{n}{k}(1 + \varepsilon)$ where $\varepsilon = 4\cdot \sqrt{\frac{\ln k}{d}}$.
    Assume $c_0\log k < d$, so that $\varepsilon<1$.
    By Lemma~\ref{lem:gw14}, we have, for all strings $w$ of length $\ell$,
    \begin{align}
        \Pr[X^1,\ldots,X^d \text{ have $w$ as a subsequence}]
        \le \left(\frac{ n\cdot \binom{n}{n-\ell}  (k-1)^{n-\ell}} {k^{n}}\right)^d.
    \end{align}
    By a union bound over all strings of length $\ell$, for $c_k=\frac{k}{4\ln k}$ from Lemma~\ref{lem:h-apx}, we have
    \begin{align}
        \Pr[\LCS(X^1,\ldots,X^d)\ge \ell] 
        &\leq k^{\ell} \cdot \left(\frac{ n\cdot \binom{n}{n-\ell}  (k-1)^{n-\ell}} {k^{n}}\right)^d \nonumber\\
        &\le n^d\cdot k^\ell \cdot \left(\frac{k^{nH_k(1-1/k-\varepsilon/k)}}{k^n} \right)^d \nonumber\\
        &\le n^d\cdot k^\ell \cdot \left(\frac{k^{n(1-c_k(\varepsilon/k)^2)}}{k^n} \right)^d \nonumber\\
        &\le n^d\cdot k^{2n/k} \cdot \left(\frac{k^{n(1-c_k(\varepsilon/k)^2)}}{k^n} \right)^d \nonumber\\
        &= n^d k^{-2n/k} < k^{-n/k}.
    \end{align}
    The second inequality uses Lemma~\ref{lem:binom-apx} and the definition of $\ell$.
    The third inequality uses Lemma~\ref{lem:h-apx}.
    The fourth inequality follows from $\varepsilon<1$.
    The equality follows from plugging in $c_k$.
    Our bound on the expectation follows.
    \begin{align}
        \E[\LCS(X^1,\ldots,X^d)]
        &\le \ell\cdot \Pr[\LCS(X^1,\ldots,X^d)< \ell] + n\cdot \Pr[\LCS(X^1,\ldots,X^d)\ge \ell] \nonumber\\
        &\le \ell\cdot 1 + n\cdot k^{-n/k} \nonumber\\
        &\le \ell + o(1)
    \end{align}
    Taking the limit $n\to\infty$, we conclude $\gamma_{k,d}\le \frac{1+\varepsilon}{k}$, as desired.
\end{proof}

