\section{Binary lower bounds implies $k$-ary}
\label{app:k}

The $k$-ary lower bound in Theorem~\ref{thm:k} follows from the binary lower bound in Theorem~\ref{thm:main} because of the following lemma.
\begin{lemma} \label{lem:main}
    $\gamma_{k,d}\ge\frac{2}{k}\gamma_{2,d}$.
\end{lemma}
\begin{proof}
    Consider $d$ random strings $X^1,\dots,X^d$ over alphabet $[k]$.
    Let $Y^1,\dots,Y^d$ be the subsequences of $X^1,\dots,X^d$ consisting of symbols $\{1,2\}$.
    By standard concentration arguments, the lengths $|Y^1|,\dots,|Y^d|$ are all at least $n_0=\frac{2}{k}n-O_k(n^{2/3})$ with high probability $1-2^{\Omega_k(n^{1/3})}$.
    Conditioned on the lengths $|Y^1|,\dots,|Y^d|$ all being at least $n_0$, the expected LCS of $Y^1,\dots,Y^d$ is at least $\gamma_{2,d}\cdot n_0$.
    Thus, 
    \begin{align}
       \E[\LCS(X^1,\dots,X^d)] 
       &\ge \E[\LCS(Y^1,\dots,Y^d)] \\
       &\ge \E[\LCS(Y^1,\dots,Y^d)\,\mid\,|Y^1|,\dots,|Y^d|\ge n_0] \cdot \Pr[|Y^1|,\dots,|Y^d|\ge n_0]\\
       &\ge \gamma_{2,d}\cdot n_0 \cdot \left(1-2^{-\Omega(n^{1/3})}\right) \\
       &\ge \frac{2}{k}\gamma_{2,d} \cdot n \cdot (1-o(1))
    \end{align}
    Thus, $\gamma_{k,d}\ge \frac{2}{k}\gamma_{2,d}$
\end{proof}

\section{List-decoding against deletions}
 \label{app:deletion}
We connect the generalized Chvátal--Sankoff constant to list-decoding against deletions.
The connection uses Azuma's inequality.
\begin{lemma}[Azuma's inequality]
    Let \(Z_1, Z_2, \cdots, Z_n\) be a martingale with bounded differences, i.e., \(|Z_{i+1}-Z_i| \leq c\) for some constant $c$. Then, for any \(\varepsilon \geq 0\),\[
    \Pr\left( |Z_n - \mathbb{E}[Z_n]| \geq \epsilon \right) \leq 2 \exp \left( -\frac{\epsilon^2}{2 n c^2} \right).
    \]
\end{lemma}
A code is a subset of $[k]^n$.
A random code $C$ is obtained by sampling independent uniformly random strings from $[k]^n$.
For $p\in(0,1)$ and an integer $d\ge 2$, a code $C$ is $(p,d-1)$ list-decodable against deletions if any $d$ strings $X^1,\dots,X^d\in C$ satisfy $\LCS(X^1,\dots,X^d)< (1-p)n$.

The first result in Proposition~\ref{pr:code} says that random codes of positive rate ($|C|\ge 2^{\Omega(n)}$) are list-decodable against deletions with radius $p=1-\gamma_{k,d}-\varepsilon$.
The second result says that random codes even of constant size at not list-decodable against deletions with radius $1-\gamma_{k,d}+\varepsilon$.
Thus, $1-\gamma_{k,d}$ is the maximum fraction of deletions that a positive rate random code list-decodes against with list-size $d$.
\begin{proposition}
    For all $\varepsilon > 0$, there exists a constant $c>0$ such that a random code $C\subset [k]^n$ of size $|C|\ge 2^{cn}$ is $(1-\gamma_{k,d}-\varepsilon,d-1)$ list-decodable against deletions.
    Furthermore, a random code of size $d$, with high probability, not $(1-\gamma_{k,d}+\varepsilon,d-1)$ list-decodable against deletions.
    \label{pr:code}
\end{proposition}
\begin{proof}
    With hindsight, choose $c=\varepsilon^2/10d$.
    We construct the code \(C\) as a set of \( 2^{cn} \) independent random strings, each of length \( n \), drawn from the alphabet \( [k] \). 
    We consider the longest common subsequence (LCS) of \( d \) codewords \( X^1, X^2, \dots, X^d \) from \( C \).

    The length of the LCS, LCS\((X^1, X^2, \dots, X^d) \), can be treated as a \textit{martingale sequence} by revealing the symbols one at a time.
   Define \( Z_i \) as the expected value of the LCS length given the first \( i \) symbols of each sequence \( X^1, \dots, X^d \):
   \[
   Z_i = \mathbb{E}[LCS(X^1, \dots, X^d) \mid X^1[1, \dots, i], \dots, X^d[1, \dots, i]].
   \]
   Here, \( Z_0, Z_1, \dots, Z_n \) forms a martingale, where 
   \begin{align}
       Z_0 &= \mathbb{E}[LCS(X^1, \dots, X^d)] \nonumber\\
       Z_n &= LCS(X^1, X^2, \dots, X^d).
   \end{align}
   Further, this martingale has bounded difference $|Z_{i+1}-Z_i|\le 1$.
    By Azuma's inequality, for any \( \epsilon > 0 \), we have:
   \begin{align}
   \Pr\left( |LCS(X^1, X^2, \dots, X^d) - \gamma_{k,d} n| \geq \epsilon n \right)
   = \Pr[|Z_n-Z_0|\ge \varepsilon n] \leq 2 \exp\left( -\frac{\epsilon^2 n}{2} \right).
   \label{eq:azuma}
   \end{align}
   This result implies that, with high probability, the LCS length is close to its expected value \(\gamma_{k,d} n\). With large enough $n$, the probability that LCS exceeds \(\gamma_{k,d} n\) is exponentially small. Thus, for each individual set of \( d \) codewords,
   \[
   \Pr\left( LCS(X^1, X^2, \dots, X^d) > (\gamma_{k,d} + \epsilon) n \right) \leq 2 \exp\left( -\frac{\epsilon^2 n}{2} \right).
   \]
   By the union bound, the probability that any $d$-tuple of codewords in \(C\) violates this bound is at most \[
   |C|^d \cdot 2 \exp\left( -\frac{\epsilon^2 n}{2} \right) \le 2^{-\Omega(n)}.
   \]
   Thus, with high probability, $LCS(X^1, X^2, \dots, X^d) \leq ( \gamma_{k,d} + \epsilon) n$
   for all codewords \( X^1, X^2, \dots, X^d \in C \), and our code is $(1-\gamma_{k,d}-\varepsilon,d-1)$ list-decodable against deletions.

   To show the second result, note that, by \eqref{eq:azuma}, for $d$ independent random strings $X^1,\dots,X^d$
    \[
   \Pr\left( LCS(X^1, X^2, \dots, X^d) > (\gamma_{k,d} - \epsilon) n \right) \geq 1-2 \exp\left( -\frac{\epsilon^2 n}{2} \right).
   \]
   so a random code of size $d$ is \emph{not} $(1-\gamma_{k,d}+\varepsilon,d-1)$ list-decodable with high probability. 
\end{proof}




