    \field{sortinit}{H}
    \field{sortinithash}{H}
    \field{abstract}{%
    {In this paper, we study the Vlasov-Maxwell equations based on the
  Morrison-Marsden-Weinstein bracket. We develop Hamiltonian particle-in-cell
  methods for this system by employing finite element methods in space and
  splitting methods in time. In order to derive the semi-discrete system that
  possesses a discrete non-canonical Poisson structure, we present a criterion
  for choosing the appropriate finite element spaces. It is confirmed that some
  conforming elements, e.g., Nédélec's mixed elements, satisfy this
  requirement. When the Hamiltonian splitting method is used to discretize this
  semi-discrete system in time, the resulting algorithm is explicit and
  preserves the discrete Poisson structure. The structure-preserving nature of
  the algorithm ensures accuracy and fidelity of the numerical simulations over
  long time.}%
    }
    \verb{doi}
    \verb 10.1063/1.4962573
    \endverb
    \field{issn}{1070-664X}
