\begin{remark}
In practice, pre-processing is applied to the neural network inputs. While such functions could be learned by the first layers of the network, manually selecting them significantly improves both the training and prediction processes. Considering the SVD of the snapshot matrix $U$ defined in \Cref{eq: U snaphots matrix},
$$U = W \Sigma V^*,$$ with $W$ and $V$ unitary matrices, $V^*$ is the conjugate transpose of $V$ and $\Sigma$ a diagonal matrix of diagonal values $(\sigma_k)_k$ sorted in descending order, the encoder input is pre-processed with the function
\[
    (\widetilde{\bfU})_k \mapsto \sigma_k^{-1/2}  (\widetilde{\bfU})_k,
\]
where $(\widetilde{\bfU})_k$ is the $k$-th coefficient of the intermediate reduced variable $\widetilde{\bfU}$. The idea is to balance the influence of each singular PSD vector in the intermediate reduced basis, thereby allowing the AE to capture the most important modes without overly neglecting the other modes.
\end{remark}

\section{Numerical results}\label{sec: numerical results}

In this section, the PSD-AE-HNN reduction of the PIC method is tested on three classical plasma physics dynamics: the linear Landau damping, the nonlinear Landau damping, and the two-stream instability test cases. 

The parameterized initial distributions of the particles takes the following form
\[
    f_{\init}(x,v;\mu) = f_{\init, x}(x;\alpha) \, f_{\init, v}(v;\sigma),
\]
with parameters $\mu=(\alpha, \sigma)^T \in \Gamma \subset \R^2$. The initial position distribution is a perturbed uniform distribution
\begin{equation} \label{def:f_init_x}
    f_{\init, x}(x;\alpha) = \frac{k}{2\pi} \left(1 + \alpha \cos (k\,x)\right),
\end{equation}
defined over $\Omega_x = \left[0, \frac{2\pi}{k}\right)$, where $k>0$ is a fixed wave number. The parameter $\alpha>0$ is the perturbation amplitude. The initial velocity distribution $f_{\init, v}(v;\sigma)$, defined over $\Omega_v=[-6,6]$, is given by a Gaussian
\begin{equation} \label{def:f_init_v_landaudamping}
    f_{\init,v}(v;\sigma) = \frac{1}{\sigma \sqrt{2\pi}} \operatorname{exp} \left( - \frac{v^2}{2 \sigma^2} \right),
\end{equation}
for the Landau test cases, and by the sum of two Gaussian  
\begin{equation} \label{def:f_init_v_twostream}
    f_{\init,v}(v;\sigma) = \frac{1}{2 \sigma \sqrt{2\pi}} \left[ \operatorname{exp} \left( - \frac{(v - 3)^2}{2 \sigma^2} \right) + \operatorname{exp} \left( - \frac{(v + 3)^2}{2 \sigma^2} \right) \right],
\end{equation}
for the two stream instability test case, where $\sigma > 0$ stands for the standard deviation of the Gaussian distributions.
%As mentioned in \Cref{sec:temporal integration}, PIC particles are initialized with a quiet start method. 



The $P$ training parameters $\mu\in\Gamma^{\train}$ are selected on a $\sqrt{P} \times \sqrt{P}$ grid over $\Gamma$. The model is then evaluated on a fine $20\times20$ grid $\Gamma^{\test} \subset \Gamma$. For each parameter $\mu$, the reference FOM solution is denoted
\[
    X^{\reference}_\mu =\left\{\bfX^0_{\mu}, \dots ,\bfX^{n_T}_{\mu}\right\}, \quad V^{\reference}_\mu =\left\{\bfV^0_{\mu}, \dots ,\bfV^{n_T}_{\mu}\right\},
\]
while the solution obtained by the PSD-AE-HNN method is denoted
\[
    X^{\test}_\mu =\left\{\hat\bfX^0_{\mu}, \dots ,\hat\bfX^{n_T}_{\mu}\right\}, \quad V^{\test}_\mu =\left\{\hat\bfV^0_{\mu}, \dots ,\hat\bfV^{n_T}_{\mu}\right\}.
\]
We recall that it is obtained through the compression of the initial condition, its complete integration over $[0,T]$ using the HNN followed by its decompression.
%\[
%    \begin{pmatrix}
%        \hat\bfX^k_\mu \\ \hat\bfV^k_\mu
%    \end{pmatrix}
%    = \hat\bfU^k_\mu = \left[ \calD \circ \mathcal{P}_k(\cdot, \bar{\hami}_{\theta_h})  \circ \calE \right] (\bfU^0_{\mu}).
%\]
We measure the relative errors on a single parameter $\mu$ for all time steps 
\[
    \error_{X, \mu} = \frac{\left\| X^{\test}_\mu  - X^{\reference}_\mu \right\|_F}{\left\|X^{\reference}_\mu \right\|_F},
    \quad
    \error_{V, \mu} = \frac{\left\| V^{\test}_\mu  - V^{\reference}_\mu \right\|_F}{\left\|V^{\reference}_\mu \right\|_F},
\]
%where $\|\cdot\|_F$ is the Frobenius norm $\|Y\|_F = \sqrt{\sum_{ij} Y_{ij}^2}$, and
and the mean relative errors at a single time $t$ over all $\mu \in \Gamma^{\test}$
\[
    \error^{\opmean}_{X, t} = \opmean \left(\frac{\left\| \bfX^t_\mu  - \hat\bfX^t_\mu \right\|_F}{\left\| \bfX^t_\mu  \right\|_F}, \mu \in \Gamma^{\test} \right),
\quad
    \error^{\opmean}_{V, t} = \opmean \left(\frac{\left\| \bfV^t_\mu  - \hat\bfV^t_\mu \right\|_F}{\left\| \bfV^t_\mu  \right\|_F}, \mu \in \Gamma^{\test} \right).
\]
In addition, we also compute the associated maximal and minimal errors. %$\error^{\opmin}_{X, t}, \error^{\opmin}_{V, t}, \error^{\opmax}_{X, t}$ and $\error^{\opmax}_{V, t}$.

