    \begin{algorithm}[!htb]\small
        \caption{Fitness-guided V2X Scene Generation}
        \begin{algorithmic}[1] 
            \Require {
            The tested system $CP$, the transformation operator set $\mathbb{A}$, the set of seed scene $\mathbb{S}_{ori}$, the number of generated tests $gen_{num}$, the maximum number of entity manipulations N }
            \Ensure  Generated high-quality test data $\mathbb{TD}$
            \\
            $\mathbb{TD} \leftarrow \emptyset$\;
            \For{$s$ in $\mathbb{S}_{ori}$}
                \State $\mathbb{GT}\leftarrow LoadLabel(s)$
                \State $s^{\prime},\mathbb{GT}^{\prime} \leftarrow s,\mathbb{GT}$
                \For{$i$=1,2\ldots,N}
                \State $a=RandSelOperator(\mathbb{A})$
                \State $s^{\prime},\mathbb{GT}^{\prime}=Transform(s^{\prime},\mathbb{GT}^{\prime},a)$
                \EndFor
                \State $\mathbb{DT}^{\prime}=GetPred(CP,s^{\prime})$
                \State $Occ, Dis=CalOccandDis(\mathbb{GT}^{\prime}, s^{\prime})$
                \State $Fitness_{pri}=CalFitnessPri(\mathbb{DT}^{\prime},
                \mathbb{GT}^{\prime},Occ, Dis)$
                \State $Spc=CreateTransScene(s^{\prime},\mathbb{GT}^{'},Fitness_{pri})$
                \If{$len(\mathbb{TD})<gen_{num}$}
                \State $\mathbb{TD}.update(Spc)$
                \Else
                    \If{$Spc.Fitness_{pri}>\mathbb{TD}[-1].Fitness_{pri}$}
                    \State $\mathbb{TD}[-1]=Spc$
                    \State $\mathbb{TD}.SortByFitness()$
                    \EndIf
                \EndIf
            \EndFor
            \\
