Algebraic anti-unification as proposed in this paper is related to \textit{$E$-anti-unification} or \textit{anti-unification modulo equational theory} \cite{Burghardt05}. In fact, if the underlying algebra has an equational axiomatization $E$, then algebraic and $E$-anti-unification are two sides of the same coin. However, the framework presented in this paper works for \textit{all} algebras, not only for those with an equational axiomatization.

\section{Preliminaries}

We expect the reader to be fluent in basic general algebra as it is presented for example in \citeA[§II]{Burris00}.

A \textit{\textbf{language}} $L$ of algebras is a set of \textit{\textbf{function symbols}}\footnote{We omit constant symbols since constants are identified with 0-ary functions.} together with a \textit{\textbf{rank function}} $r:L\to\mathbb N$. Moreover, we assume a denumerable set $X$ of \textit{\textbf{variables}} distinct from $L$. Terms are formed as usual from variables in $X$ and function symbols in $L$ and we denote the set of all such terms by $T_{L,X}$. The set of variables occurring in a term $s$ are denoted by $X(s)$ and $s$ has \textit{\textbf{rank}} $k$ iff $X(s)=\{x_1,\ldots,x_k\}$. The rank of $s$ is denoted by $rs$.

An \textit{\textbf{$L$-algebra}} $\mathfrak A$ consists of a non-empty set $A$, the \textit{\textbf{universe}} of $\mathfrak A$, and for each function symbol $f\in L$, a function $f^\mathfrak A:A^{r(f)}\to A$, the \textit{\textbf{functions}} of $\mathfrak A$ (the \textit{\textbf{distinguished elements}} of $\mathfrak A$ are the 0-ary functions). We will not distinguish between distinguished elements and their 0-ary function symbols. An algebra is \textit{\textbf{injective}} iff each of its function is injective. Notice that every distinguished element $a$ of $\mathfrak A$ is a 0-ary function $a:A^0\to A$ which maps some single dummy element in $A^0$ to $a$ and thus \textit{is} injective.

Every term $s$ induces a \textit{\textbf{term function}} $s^\mathfrak A$ on $\mathfrak A$ in the usual way. In this paper, we shall not distinguish between terms inducing the same function on the underlying algebra, which is common practice in mathematics where one does usually not distinguish, for example, between the terms $2x^2$ and $(1+1)x^2$ in arithmetic.

\begin{fact}\label{f:injective} Every term function induced by injective functions is injective.
\end{fact}

The \textit{\textbf{term algebra}} $\mathfrak T_{L,X}$ over $L$ and $X$ is the algebra we obtain by interpreting each function symbol $f\in L$ by
\begin{align*} 
	f^{\mathfrak T_{L,X}}:T_{L,X}^{r(f)}\to T_{L,X}:s_1\ldots s_{r(f)}\mapsto f(s_1,\ldots,s_{r(f)}).
\end{align*} 

A \textit{\textbf{substitution}} is a mapping $\sigma:X\to T_{L,X}$, where $\sigma x:=x$ for all but finitely many variables, extended from $X$ to terms in $T_{L,X}$ inductively as usual, and we write $s\sigma$ for the application of $\sigma$ to the term $s$. For two terms $s,t\in T_{L,X}$, we define the \textit{\textbf{syntactic generalization ordering}} by
\begin{align*} 
	s\lesssim t \quad:\Leftrightarrow\quad s=t\sigma,\quad\text{for some substitution $\sigma$}.
\end{align*}

A \textit{\textbf{homomorphism}} is a mapping $H: \mathfrak{A\to B}$ such that for any function symbol $f\in L$ and elements $a_1,\ldots,a_{r(f)}\in A$,
\begin{align*} 
	H(f^ \mathfrak A(a_1\ldots a_{r(f)}))=f^ \mathfrak B(H(a)_1,\ldots,H(a_{r(f)})).
\end{align*} An \textit{\textbf{isomorphism}} is a bijective homomorphism. 
% The application $Hs$ of a homomorphism $H$ to an $L$-term $s$ is defined point-wise by
% \begin{align*} 
% 	(Hs)^ \mathfrak A \textbf{o}:=Hs^ \mathfrak A(\textbf{o})=s^ \mathfrak B(H(\textbf{o})),\quad\text{for all $\textbf{o}\in A^{r(s)}$},
% \end{align*} where $H(\textbf{o})$ means component-wise application of $H$ to $\textbf{o}$.

\section{Anti-unification}\label{§:AU}

This is the main section of the paper. Here we shall introduce algebraic anti-unification and derive some elementary observations.

In the rest of the paper, let $\mathfrak A$ and $\mathfrak B$ be $L$-algebras over some joint language of algebras $L$, and let $\mathfrak{(A,B)}$ be a pair of $L$-algebras. We will always write $\mathfrak A$ instead of $\mathfrak{AA}$.

\begin{definition}\label{d:downarrow} Given an $L$-term $s$, define
\begin{align*} 
	\downarrow_\mathfrak A s:= \left\{s^\mathfrak A(\textbf{o})\in A \;\middle|\; \textbf{o}\in A^{r(s)}\right\}.
\end{align*} In case $a\in\ \downarrow_\mathfrak A s$, we say that $s$ is a \textit{\textbf{generalization}} of $a$ and $a$ is an \textit{\textbf{instance}} of $s$.
\end{definition}

\begin{fact} Every distinguished element $a\in A$ is an instance of itself\footnote{More precisely, of the constant symbol denoting it.} since
\begin{align}\label{equ:downarrow_a} 
	a\in\ \downarrow_\mathfrak A a=\{a\}.
\end{align}
\end{fact}

\begin{definition} Define the \textit{\textbf{(semantic) generalization ordering}} for two $L$-terms $s$ and $t$ in $\mathfrak{(A,B)}$ by
\begin{align*} 
	s\sqsubseteq_{ \mathfrak{(A,B)}} t \quad:\Leftrightarrow\quad \downarrow_\mathfrak A s\subseteq\ \downarrow_\mathfrak A t \quad\text{and}\quad \downarrow_\mathfrak B s\subseteq\ \downarrow_\mathfrak B t,
\end{align*} and
\begin{align*} 
	s\equiv_{ \mathfrak{(A,B)}} t \quad:\Leftrightarrow\quad s\sqsubseteq_{ \mathfrak{(A,B)}} t \quad\text{and}\quad t\sqsubseteq_{ \mathfrak{(A,B)}} s.
\end{align*}
\end{definition}

\begin{example} $0x\equiv_{(\mathbb N,\cdot,0)} 0$.
\end{example}

\begin{fact} The generalization ordering $\sqsubseteq_{ \mathfrak{(A,B)}}$ is a pre-order between $L$-terms, for any pair of $L$-algebras $\mathfrak{(A,B)}$, that is, it is reflexive and transitive.
\end{fact}
% \begin{proof} 
% \todo[inline]{}
% \end{proof}

\begin{fact} For any distinguished element $a\in A$, we have by \prettyref{equ:downarrow_a}:
\begin{align*} 
	a\sqsubseteq_\mathfrak A s \quad\Leftrightarrow\quad a\in\ \downarrow_\mathfrak A s
\end{align*} and
\begin{align*} 
	s\sqsubseteq_\mathfrak A a \quad\Leftrightarrow\quad s\equiv_\mathfrak A a \quad\Leftrightarrow\quad \text{$s^\mathfrak A$ is a constant function with value $a$.}
\end{align*} For two distinguished elements $a,b\in A$, we have
\begin{align*} 
	a\sqsubseteq_\mathfrak A b \quad\Leftrightarrow\quad \downarrow_\mathfrak A a\subseteq\ \downarrow_\mathfrak A b \quad\Leftrightarrow\quad \{a\}\subseteq\{b\} \quad\Leftrightarrow\quad a=b \quad\Leftrightarrow\quad a\equiv_ \mathfrak A b.
\end{align*} 
\end{fact}

\begin{remark} Notice that our semantic generalization ordering $\sqsubseteq$ differs from the usual one in \textit{syntactic} anti-unification $\lesssim$ where a term $s$ is said to be \textit{\textbf{more general than}} a term $t$ iff there is a substitution $\sigma$ such that $t=s\sigma$.
\todo[inline]{provide examples}
\end{remark}

\begin{definition} For any element $a\in A$, we define
\begin{align*} 
	\uparrow_ \mathfrak A a:=\{s\in T_{L,X} \mid a\in\ \downarrow_ \mathfrak A s\},
\end{align*} extended to elements $a\in A$ and $b\in B$ by
\begin{align*} 
	a\uparrow_{ \mathfrak{(A,B)}} b:=(\uparrow_ \mathfrak A a)\cap (\uparrow_ \mathfrak B b).
\end{align*}
\end{definition}

We shall now introduce the \textbf{main notion of the paper}: 

\begin{definition} Define the set of \textit{\textbf{minimally general generalizations}} (or \textit{\textbf{mggs}}) of two elements $a\in A$ and $b\in B$ in $\mathfrak{(A,B)}$ by
\begin{align*} 
	a\Uparrow_{ \mathfrak{(A,B)}} b:=\min_{\sqsubseteq_{ \mathfrak{(A,B)}}}(a\uparrow_{ \mathfrak{(A,B)}} b).
\end{align*} In case $a\Uparrow_{ \mathfrak{(A,B)}} b=\{s\}$ contains a single generalization, $s$ is called the \textit{\textbf{least general generalization}} (or \textit{\textbf{lgg}}) of $a$ and $b$ in $\mathfrak{(A,B)}$.
\end{definition}

Here $\min_{\sqsubseteq_{ \mathfrak{(A,B)}}}$ is the function computing the \textit{set} of minimal generalizations with respect to $\sqsubseteq_{ \mathfrak{(A,B)}}$ (not a single minimal generalization), which means that in case there are \textit{no} minimal generalizations, the computed set is empty. Notice that in case $a\in A$ is a distinguished element, we always have\footnote{More precisely, the constant symbol for the element $a$ is in $a\Uparrow_ \mathfrak A a$.}
\begin{align*} 
	a\in a\Uparrow_\mathfrak A a.
\end{align*}

\begin{example}\label{e:BOOL} Let $\mathfrak{BOOL}:=(\{0,1\},\lor,\neg,\{0,1\})$ be the 2-element boolean algebra with disjunction and negation (and therefore with all boolean functions) where both truth values are distinguished elements. Notice that terms in $T_{\{\lor,\neg,0,1\}X}$ are propositional formulas with variables from $X$ in the usual sense. We have
\begin{align*} 
	\uparrow_ \mathfrak{BOOL} 0&=\{s\in T_{\{\lor,\neg,0,1\}X} \mid \text{$s$ is falsifiable}\},\\
	\uparrow_ \mathfrak{BOOL} 1&=\{s\in T_{\{\lor,\neg,0,1\}X} \mid \text{$s$ is satisfiable}\},\\
	0\uparrow_ \mathfrak{BOOL} 1&=\{s\in T_{\{\lor,\neg,0,1\}X} \mid \text{$s$ is satisfiable and falsifiable}\}.
\end{align*} We clearly have
\begin{align*} 
	0\Uparrow_ \mathfrak{BOOL} 1=0\uparrow_ \mathfrak{BOOL} 1.
\end{align*}
\end{example}

\section{Generalization type}

The following definition is an adaptation of the nomenclature in the excellent survey on anti-unification by \citeA[Definition 5]{Cerna23} (triviality is new):

\begin{definition} The \textit{\textbf{generalization type}} of a pair of $L$-algebras $\mathfrak{(A,B)}$ is called
\begin{itemize}
	\item \textit{\textbf{nullary}} iff $a\Uparrow_{ \mathfrak{(A,B)}} b=\emptyset$, for all $a\in A$ and $b\in B$;
	\item \textit{\textbf{unitary}} iff $|a\Uparrow_{ \mathfrak{(A,B)}} b|=1$, for all $a\in A$ and $b\in B$;
	\item \textit{\textbf{finitary}} iff
		\begin{itemize}
			\item $|a\Uparrow_{ \mathfrak{(A,B)}} b|<\infty$, for all $a\in A$ and $b\in B$;
			\item $|a\Uparrow_{ \mathfrak{(A,B)}} b|>1$, for some $a\in A$ and $b\in B$;
		\end{itemize}
	\item \textit{\textbf{infinitary}} iff $|a\Uparrow_{ \mathfrak{(A,B)}} b|=\infty$, for some $a\in A$ and $b\in B$;
	\item \textit{\textbf{trivial}} iff $a\Uparrow_{ \mathfrak{(A,B)}} b=T_{L,X}$, for all $a\in A$ and $b\in B$.
\end{itemize}
\end{definition}

