\begin{fact}\label{f:uparrow_a=x} $\uparrow_ \mathfrak A a=\{x\}$ implies $a\Uparrow_{ \mathfrak{(A,B)}} b=\{x\}$, for all $b\in B$. Hence, algebras containing elements having only the trivial generalization $x$ cannot be nullary. 
\end{fact}

\begin{fact} $a\uparrow_{ \mathfrak{(A,B)}} b=\{x\}$ implies $a\Uparrow_{ \mathfrak{(A,B)}} b=a\uparrow_{ \mathfrak{(A,B)}} b\neq\emptyset$.
\end{fact}

\begin{fact} In any pair of algebras $\mathfrak{(A,B)}$ with $|A|=|B|=1$, we have $a\Uparrow_{ \mathfrak{(A,B)}} b=a\uparrow_{ \mathfrak{(A,B)}} b\neq\emptyset$. Hence, algebras consisting of a single element cannot be nullary.
\end{fact}
\begin{proof} Every generalization $s\in a\uparrow_{ \mathfrak{(A,B)}} b$ has to satisfy $\downarrow_\mathfrak A s=\{a\}$ and $\downarrow_\mathfrak B s=\{b\}$, which means that there cannot be a generalization $t$ such that $\downarrow_{ \mathfrak{(A,B)}} t\subsetneq\ \downarrow_{ \mathfrak{(A,B)}} s$.
\end{proof}

\begin{fact} The algebra $(A)$ consisting only of its universe is unitary and trivial.
\end{fact}
\begin{proof} A direct consequence of $a\Uparrow_{(A)} b=\{x\}$, for all $a,b\in A$ (notice that $a\Uparrow_{(A)} a\neq\{a\}$ since $a$ is not a distinguished element of $(A)$ and thus cannot be used to form terms).
\end{proof}

\begin{fact} $s\in a\Uparrow_{ \mathfrak{(A,B)}} b$ for any term $s$ satisfying $\downarrow_ \mathfrak A s=\{a\}$ and $\downarrow_ \mathfrak B s=\{b\}$.
\end{fact}

\begin{example} In the monounary algebra $\mathfrak A=(\{a,b\},S)$ given by
\begin{center}
\begin{tikzpicture} 
	\node (a) {$a$};
	\node (b) [right=of a] {$b$};
	\draw[->] (a) to [edge label={$S$}] (b);
	\draw[->] (b) to [edge label'={$S$}][loop] (b);
\end{tikzpicture}
\end{center} we have
\begin{align*} 
	\uparrow_\mathfrak A a=\{x\}
\end{align*} and thus by \prettyref{f:uparrow_a=x} we have
\begin{align*} 
	a\Uparrow_ \mathfrak A b=\{x\}.
\end{align*} This shows that $\mathfrak A$ is unitary.
\end{example}

\begin{fact} The generalization type of $(\mathbb N,S)$, where $S$ is the successor function, is unitary by the forthcoming \prettyref{c:(N,S)_unitary}.
\end{fact}

Notice that in term algebras, syntactic and semantic generalization orderings (and thus anti-unification) coincide:

\begin{lemma}\label{l:s_lesssim_t} For any $L$-terms $s,t\in T_{L,X}$, we have
\begin{align*} 
	s\lesssim t \quad\Leftrightarrow\quad s\sqsubseteq_{ \mathfrak T_{L,X}} t.
\end{align*}
\end{lemma}
\begin{proof} We have the following equivalences:
\begin{align*} 
	s\lesssim t
		&\quad\Leftrightarrow\quad s=t(\textbf{o}),\quad\text{for some $\textbf{o}\in T_{L,X}^{r(t)}$}\\
		& \quad\Leftrightarrow\quad \downarrow_{ \mathfrak T_{L,X}} s\subseteq\ \downarrow_{ \mathfrak T_{L,X}} t\\
		& \quad\Leftrightarrow\quad s\sqsubseteq_{ \mathfrak T_{L,X}} t.
\end{align*}
\end{proof}

\begin{fact} Term algebras are unitary.
\end{fact}
\begin{proof} A direct consequence of \prettyref{l:s_lesssim_t} and the well-known fact that term algebras are unitary by \citeS{Plotkin70} and \citeS{Reynolds70} classical results, and their original algorithms (plus \citeS{Huet76} simple algorithm) can be used to compute the least general generalization of two terms.
\end{proof}

\begin{theorem} In every injective algebra $\mathfrak A$, we have $a\Uparrow_ \mathfrak A b\neq\emptyset$, for all $a,b\in A$. Consequently, injective algebras cannot be nullary.
\end{theorem}
\begin{proof} We have $a\Uparrow_ \mathfrak A b=\emptyset$ iff for each $s\in a\uparrow_ \mathfrak A b$ there is some $t\in a\uparrow_ \mathfrak A b$ such that $t\sqsubset s$, which is equivalent to $\downarrow_ \mathfrak A t\subset\ \downarrow_ \mathfrak A s$. Since $t^ \mathfrak A$ is injective by assumption (\prettyref{f:injective}), we must have $t^ \mathfrak A(\textbf{o})\neq t^ \mathfrak A\textbf{u}$ for every $\mathbf{o,u}\in A^{r(t)}$, which means that
\begin{align*} 
	|\downarrow_ \mathfrak A t\ |=\left|\left\{t^ \mathfrak A(\textbf{o}) \;\middle|\; \textbf{o}\in A^{r(t)}\right\}\right|=|A^{r(t)}|
\end{align*} and, analogously,
\begin{align*} 
	|\downarrow_ \mathfrak A s\ |=|A^{r(s)}|.
\end{align*} Since $\downarrow_ \mathfrak A t\subsetneq\ \downarrow_ \mathfrak A s$, we have
\begin{align*} 
	|\downarrow_ \mathfrak A t\ |<|\downarrow_ \mathfrak A s\ |,
\end{align*} thus
\begin{align*} 
	|A^{r(t)}|<|A^{r(s)}|,
\end{align*} and hence
\begin{align*}
	r(t)<r(s).
\end{align*} Since the rank of every function is finite, we have $rs<\infty$ and thus there can be only finitely many $t$'s with $r(t)<r(s)$. Hence, there must be some $t'\in a\uparrow b$ for which there can be no $t''\in a\uparrow b$ with $t''\sqsubset t'$ --- we thus conclude $t'\in a\Uparrow_ \mathfrak A b$ and $a\Uparrow_ \mathfrak A b\neq\emptyset$.
\end{proof}

