\section{Characteristic generalizations}

Anti-unifying an element with itself yields the set of minimal general generalizations of that element which, in a sense, ``characterize'' that element since generalizations encode properties of elements (for example, $2x$ is a genearlization of a natural number $a$ iff $a$ is even). This motivates the following definition:

\begin{definition} Define the set of \textit{\textbf{characteristic generalizations}} of $a\in A$ in $\mathfrak A$ by
\begin{align*} 
	\Uparrow_ \mathfrak A a:=\min_{\sqsubseteq_ \mathfrak A}\uparrow_ \mathfrak A a=a\Uparrow_ \mathfrak A a.
\end{align*}
\end{definition}

\begin{example} Recall the situation in \prettyref{e:BOOL}. We have
\begin{align*} 
	\Uparrow_ \mathfrak{BOOL} 0&=\left\{s\in T_{\{\lor,\neg,0,1\}X} \;\middle|\; \text{$s$ is unsatisfiable}\right\},\\
	\Uparrow_ \mathfrak{BOOL} 1&=\left\{s\in T_{\{\lor,\neg,0,1\}X} \;\middle|\; \text{$s$ is valid}\right\},\\
	0\Uparrow_ \mathfrak{BOOL} 1&=0\uparrow_ \mathfrak{BOOL} 1.
\end{align*}
\end{example}

\begin{definition} We call a set $G$ of generalizations a \textit{\textbf{characteristic set of generalizations}} of $a$ in $\mathfrak A$ iff
\begin{enumerate}
	\item $G\subseteq\ \Uparrow_ \mathfrak A a\in A$;
	\item $G\not\subseteq\ \Uparrow_ \mathfrak A b$ for all $b\neq a$.
\end{enumerate} In case $G=\{s\}$ is a singleton, we call $s$ a \textit{\textbf{characteristic generalization}} of $a$ in $\mathfrak A$.
\end{definition}

\begin{example} $X\cup X^c$ is a characteristic generalization of $U$ in $(2^U,\cup)$.
\end{example}

\begin{example} $x+(-x)$ is a characteristic generalization of $0$ in $(\mathbb Z,+)$.
\end{example}

