\section{Homomorphisms}\label{§:H}

In this section, we show that algebraic anti-unification is compatible with structure-preserving mappings.

\begin{lemma}[Homomorphism Lemma]\label{l:HL} For any homomorphism $H: \mathfrak{A\to B}$, any $L$-term $s$, and any elements $a,b\in A$,
\begin{align} 
	H(\downarrow_ \mathfrak A s)&\subseteq\ \downarrow_ \mathfrak B s,\\
	\label{equ:Ha_uparrow_H(b)} a\uparrow_ \mathfrak A b&\subseteq H(a)\uparrow_ \mathfrak B H(b).
\end{align} In case $H$ is an isomorphism, we have
\begin{align} 
	\label{equ:H_downarrow_A_s=downarrow_B_s} H(\downarrow_ \mathfrak A s)&=\ \downarrow_ \mathfrak B s,\\
	a\uparrow_ \mathfrak A b&=H(a)\uparrow_ \mathfrak B H(b).
\end{align}
\end{lemma}
\begin{proof} Since $H$ is a homomorphism by assumption, we have
\begin{align*} 
	H(\downarrow_ \mathfrak A s)=\left\{H(s^ \mathfrak A(\textbf{o})) \;\middle|\; \textbf{o}\in A^{r(s)} \right\}= \left\{s^ \mathfrak B(H(\textbf{o})) \;\middle|\; \textbf{o}\in A^{r(s)}\right\}\subseteq \left\{s^ \mathfrak B(\textbf{o}) \;\middle|\; \textbf{o}\in B^{r(s)}\right\}=\ \downarrow_ \mathfrak B s.
\end{align*} In case $H$ is an isomorphism, we have ``$=$'' instead of ``$\subseteq$'' in the above computation.

We shall now prove \prettyref{equ:Ha_uparrow_H(b)} by showing that every term $s\in a\uparrow_ \mathfrak A b$ is in $H(a)\uparrow_ \mathfrak A H(b)$. Since $s\in a\uparrow_ \mathfrak A b$ holds by assumption, we have
\begin{align*} 
	a=s^ \mathfrak A(\textbf{o}) \quad\text{and}\quad b=s^ \mathfrak A(\textbf{u}),
\end{align*} for some $\mathbf{o,u}\in A^{r(s)}$. Since $H$ is a homomorphism, we thus have
\begin{align*} 
	H(a)=H(s^ \mathfrak A(\textbf{o}))=s^ \mathfrak B(H(\textbf{o})) \quad\text{and}\quad H(b)=H(s^ \mathfrak A(\textbf{u}))=s^ \mathfrak B(H(\textbf{u})),
\end{align*} which shows \prettyref{equ:Ha_uparrow_H(b)}.

It remains to show that in case $H$ is an isomorphism, we have
\begin{align*} 
	H(a)\uparrow_ \mathfrak B H(b)\subseteq a\uparrow_ \mathfrak A b.
\end{align*} For this, let $$s\in H(a)\uparrow_ \mathfrak B H(b)$$ be a generalization of $H(a)$ and $H(b)$ in $\mathfrak B$ which by definition means that there are some $\mathbf{o,u}\in B^{r(s)}$ such that
\begin{align*} 
	H(a)&=s^ \mathfrak B(\textbf{o}),\\
	H(b)&=s^ \mathfrak B(\textbf{u}).
\end{align*} Since $H$ is an isomorphism, its inverse $H^{-1}$ is an isomorphism as well, which yields
\begin{align*} 
	a&=H^{-1}(s^ \mathfrak B(\textbf{o}))=s^ \mathfrak A(H^{-1}(\textbf{o})),\\
	b&=H^{-1}(s^ \mathfrak B(\textbf{u}))=s^ \mathfrak A(H^{-1}(\textbf{u})).
\end{align*} This shows
\begin{align*} 
	s\in a\uparrow_ \mathfrak A b.
\end{align*}
\end{proof}

\begin{theorem}[Isomorphism Theorem]\label{t:HT} For any isomorphism $H: \mathfrak{A\to B}$ and elements $a,b\in A$,
\begin{align}
	a\Uparrow_ \mathfrak A b=H(a)\Uparrow_ \mathfrak B H(b).
\end{align}
\todo[inline]{Does at least $a\Uparrow_ \mathfrak A b\subseteq H(a)\Uparrow_ \mathfrak B b$ hold for [injective] homomorphisms as well?}
\end{theorem}
\begin{proof} $(\subseteq)$ We show that each
\begin{align}\label{equ:s_in_a_Uparrow_A_b}
	s\in a\Uparrow_ \mathfrak A b
\end{align} is contained in $H(a)\Uparrow_ \mathfrak B H(b)$ for the isomorphism $H$. By \prettyref{l:HL}, we have $a\uparrow_ \mathfrak A b\subseteq H(a)\uparrow_ \mathfrak B H(b)$. It thus remains to show that $s$ is $\sqsubseteq_ \mathfrak B$-minimal. 

Suppose there is some $t\in H(a)\uparrow_ \mathfrak B H(b)$ such that $t\sqsubset_ \mathfrak B s$, that is,
\begin{align}\label{equ:t_subsetneq_s} 
	\downarrow_ \mathfrak B t\subsetneq\ \downarrow_ \mathfrak B s.
\end{align} Since $t\in H(a)\uparrow_ \mathfrak B H(b)$, we have
\begin{align*} 
	H(a)&=t^ \mathfrak B(\textbf{o}),\\
	H(b)&=t^ \mathfrak B(\textbf{u}),
\end{align*} for some $\textbf{o}, \textbf{u}\in B^{r(t)}$. Now since $H$ is an isomorphism, its inverse $H^{-1}$ is an isomorphism as well, and we thus have
\begin{align*} 
	a&=H^{-1}(t^ \mathfrak B(\textbf{o}))=t^ \mathfrak A(H^{-1}(\textbf{o}))\\
	b&=H^{-1}(t^ \mathfrak B(\textbf{u}))=t^ \mathfrak A(H^{-1}(\textbf{u})),
\end{align*} which shows
\begin{align*} 
	t\in a\uparrow_ \mathfrak A b.
\end{align*} Now we have by \prettyref{equ:H_downarrow_A_s=downarrow_B_s} and \prettyref{equ:t_subsetneq_s},
\begin{align*} 
	\downarrow_ \mathfrak A t=H^{-1}(\downarrow_ \mathfrak B t)\;\subsetneq\; H^{-1}(\downarrow_ \mathfrak A s)=\ \downarrow_ \mathfrak A s,
\end{align*} which is equivalent to
\begin{align*} 
	t\sqsubset_ \mathfrak A s,
\end{align*} a contradiction to \prettyref{equ:s_in_a_Uparrow_A_b} and thus to the $\sqsubseteq_ \mathfrak A$-minimality of $s$.

$(\supseteq)$ Analogous.
\end{proof}

\section{Monounary algebras}\label{§:Monounary}

In the rest of this section, let $\mathfrak A=(A,S)$ be a monounary algebra with $S:A\to A$ the only unary function (we can imagine $S$ to be a generalized ``successor'' function). 

\begin{example} We show that the generalization type of the monounary algebra
\begin{center}
\begin{tikzpicture} 
	\node (a) {$a$};
	\draw[->] (a) to [edge label'={$S$}][loop] (a);
\end{tikzpicture}
\end{center} is infinitary and trivial. We have
\begin{align*} 
	\uparrow_\mathfrak A a= \left\{S^m(x) \;\middle|\; m\geq 0\right\}.
\end{align*} Since
\begin{align*} 
	\downarrow_\mathfrak A S^m(x)=\ \downarrow_\mathfrak A S^n(x)=\{a\},\quad\text{for all $m,n\geq 0$},
\end{align*} we have
\begin{align*} 
	S^m(x)\equiv_\mathfrak A S^n(x),\quad\text{for all $m,n\geq 0$},
\end{align*} and thus
\begin{align*} 
	a\Uparrow_\mathfrak A a= \left\{S^m(x) \;\middle|\; m\geq 0\right\}=T_{\{S\}\{x\}}.
\end{align*} This shows that the generalization type of $\mathfrak A$ is infinitary and trivial.
\end{example}

\begin{example} We show that the generalization type of the monounary algebra
\begin{center}
\begin{tikzpicture} 
	\node (a) {$a$};
	\node (b) [right=of a] {$b$};
	\draw[<->] (a) to [edge label={$S$}] (b);
\end{tikzpicture}
\end{center} is infinitary and trivial. Since
\begin{align*} 
	\uparrow_\mathfrak B a= \left\{S^m(x) \;\middle|\; m\geq 0\right\}=\ \uparrow_\mathfrak B b
\end{align*} and
\begin{align*} 
	\downarrow_\mathfrak B S^m(x)=\ \downarrow_\mathfrak B S^n(x)=\{a,b\},\quad\text{for all $m,n\geq 0$},
\end{align*} implies
\begin{align*} 
	S^m(x)\equiv_\mathfrak B S^n(x),\quad\text{for all $m,n\geq 0$},
\end{align*} and thus
\begin{align*} 
	a\Uparrow_\mathfrak B a=b\Uparrow_\mathfrak B b=a\Uparrow_\mathfrak B b= \left\{S^m(x) \;\middle|\; m\geq 0\right\}=T_{\{S\}\{x\}}.
\end{align*}
\end{example}

We define
\begin{align*} 
	m(a)&:=
		\begin{cases}
			\max\left\{m\geq 0 \;\middle|\; S^m(x)\in\ \uparrow_\mathfrak A a\right\} & \text{if the maximum exists,}\\
			\infty & \text{otherwise,}
		\end{cases}\\
\end{align*} extended to pairs by
\begin{align*} 
	m(a,b)&:=\min(m(a),m(b))\in\mathbb N\cup\{\infty\}.
\end{align*}

% Moreover, for any $a,b\in A$ such that $m(a,b)$ exists, define
% \begin{align*} 
% 	o(a,b):=\text{select one element $o\in A$ such that $a=f^{m(a,b)}(o(a,b))$}.
% \end{align*}

\begin{theorem} Let $\mathfrak A=(A,S)$ be a monounary algebra. For any $a,b\in A$, we have
\begin{align*} 
	a\Uparrow_ \mathfrak A b=
		\begin{cases}
			\left\{S^{m(a,b)}(x)\right\} & \text{if $m(a,b)<\infty$}\\
			\emptyset & \text{otherwise}.
		\end{cases} 
\end{align*}
\end{theorem}
\begin{proof} Suppose $m(a,b)<\infty$, which means that either $m(a)<\infty$ or $m(b)<\infty$, that is, there is some maximal $m$ such that $S^m(x)\in\ \uparrow_ \mathfrak A a$ or $S^m(x)\in\ \uparrow_ \mathfrak A b$. We then have
\begin{align*} 
	S^{m+\ell}(x)\not\in (\uparrow_ \mathfrak A a)\cap (\uparrow_ \mathfrak A b)=\ a\uparrow b,\quad\text{for all $\ell\geq 1$,}
\end{align*} which implies $a\Uparrow_ \mathfrak A b=\{S^m(x)\}$ --- notice that $m=m(a,b)$ by definition. 

Now suppose $m(a,b)=\infty$, which means that $m(a)=m(b)=\infty$. In that case, we clearly have $\max_\leq(a\uparrow_ \mathfrak A b)=\emptyset$.
\end{proof}

\begin{corollary}\label{c:(N,S)_unitary} Let $(\mathbb N,S)$ be the infinite monounary algebra where $S$ denotes the successor function. For any $a,b\in\mathbb N$, we have $a\Uparrow_{(\mathbb N,S)} b=\left\{S^{\min(a,b)}(x)\right\}$. This means that the generalization type of $(\mathbb N,S)$ is unitary.
\end{corollary}

\section{Finite unary algebras aka semiautomata}\label{§:FUA}

In this section, we study algebraic anti-unification in finite unary algebras, which can be seen as semiautomata, and show that we can use well-known methods from the theory of finite automata to compute sets of (minimally general) generalizations.

In the rest of this section, let
\begin{align*} 
	\mathfrak A=(A,\Sigma:=\{f_1,\ldots,f_n\}),
\end{align*} for some $n\geq 1$, be a finite unary algebra with finite universe $A$. We shall now recall that every such algebra is essentially a semiautomaton.

Recall that a (\textit{\textbf{finite deterministic}}) \textit{\textbf{semiautomaton}} \cite<see e.g.>[§2.1]{Holcombe82} is a construct $$\mathfrak S=(S,\Sigma,\delta),$$ where $S$ is a finite set of \textit{\textbf{states}}, $\Sigma$ is a finite \textit{\textbf{input alphabet}}, and $\delta:S\times \Sigma\to S$ is a \textit{\textbf{transition function}}. Every semiautomaton can be seen as a finite unary algebra in the following well-known way: every symbol $\sigma\in\Sigma$ induces a unary function $\sigma^ \mathfrak S:S\to S$ via $\sigma^ \mathfrak S:=\delta(x,\sigma)$. We can now omit $\delta$ and define $$\mathfrak S':=(S,\Sigma^ \mathfrak S:=\{\sigma^ \mathfrak S\mid \sigma\in\Sigma\}).$$ It is immediate from the construction that $\mathfrak S$ and $\mathfrak S'$ represent essentially the same semiautomaton and that every semiautomaton can be represented in that way --- the difference is that $\mathfrak S'$ is a finite unary algebra!

Recall that a (\textit{\textbf{finite deterministic}}) \textit{\textbf{automaton}} \cite<see e.g.>[§1.1]{Sipser13} is a construct $$\mathscr A:=(Q,\Sigma,\delta,q_0,F),$$ where $(Q,\Sigma,\delta)$ is a semiautomaton, $q_0\in Q$ is the \textit{\textbf{initial state}}, and $F\subseteq Q$ is a set of \textit{\textbf{final states}}. The \textit{\textbf{behavior}} of $\mathscr A$ is given by
\begin{align*} 
	|| \mathscr A||:=\{w\in \Sigma^\ast \mid \delta^\ast(q_0,w)\in F\},
\end{align*} where $\delta^\ast:Q\times\Sigma^\ast\to Q$ is defined recursively as follows, for $q\in Q,a\in\Sigma,w\in\Sigma^\ast$:\todo{$\delta^\ast(q,\varepsilon):=q$?}
\begin{align*} 
	\delta^\ast(q,\varepsilon)&:=q,\\
	\delta^\ast(q,aw)&:=\delta^\ast(\delta(q,a),w).
\end{align*} Notice that since automata are built from semiautomata by adding an initial state and a set of final states, and since every semiautomaton $\mathfrak S=(S,\Sigma,\delta)$ can be represented in the form of a finite unary algebra $\mathfrak S'=(S,\Sigma^ \mathfrak S)$ as above, we can reformulate every automaton $\mathscr A=(Q,\Sigma,\delta,q_0,F)$ as $\mathscr A'=(Q,\Sigma^ \mathscr A,q_0,F)$, where $\Sigma^ \mathscr A:=\{\sigma^ \mathscr A\mid \sigma\in\Sigma\}$ and $\sigma^ \mathscr A:=\delta(\,.\,,\sigma):Q\to Q$. In other words, given a finite unary algebra (semiautomaton) $$\mathfrak A=(A,\Sigma),$$ we can construct a finite automaton
\begin{align*} 
	\mathfrak A_{a\to F}=(A,\Sigma,a,F)
\end{align*} by designating a state $a\in A$ as the initial state, and by designating a set of states $F\subseteq A$ as final states.

We want to compute the set of generalizations $\uparrow_\mathfrak A a$. Notice that we can identify, for example, each term in $T_{\{f,g\}}(\{x\})$ with a word over the alphabet $\Sigma=\{f,g\}$: for instance, the term $fgfx$ can be identified with the word $fgf\in\Sigma^\ast$ since the variable $x$ contains no information. We denote the function induced by a word $w\in\Sigma^\ast$ in $\mathfrak A$ by $w^ \mathfrak A$ --- for example, $(fg)^ \mathfrak A$ is the function on $A$ which first applies $g$ and then $f$. We shall now show that in any finite unary algebra (semiautomaton) $\mathfrak A=(A,\Sigma)$, the set of generalizations $\uparrow_ \mathfrak A a$ can be computed by some finite automaton as illustrated by the following example: 

\begin{example}\label{e:A} Consider the finite unary algebra (semiautomaton)
\begin{align*} 
	\mathfrak A=(\{a,b\},\Sigma:=\{f,g\})
\end{align*} given by
\begin{center}
\begin{tikzpicture}[node distance=2cm and 2cm] 
	\node (a) {$a$};
	\node (b) [right=of a] {$b$.};
	\draw[->] (a) to [edge label={$f$}] [bend left] (b);
	\draw[->] (b) to [edge label={$f$}] [bend left] (a);
	\draw[->] (a) to [edge label'={$g$}] [loop] (a);
	\draw[->] (b) to [edge label'={$g$}] [loop] (b);
\end{tikzpicture}
\end{center} We can identify the set of all generalizations of $a$ in $\mathfrak A$ with
\begin{align*} 
	\uparrow_\mathfrak A a=&\left\{w\in\Sigma^\ast \;\middle|\; \delta^\ast(a,w)=a\right\}\cup \left\{u\in\Sigma^\ast \;\middle|\; \delta^\ast(b,u)=a\right\}.
\end{align*} Now define the automaton $\mathfrak A_{a\to \{a\}}$ by adding to the semiautomaton $\mathfrak A$ the initial state $a$ and the set of final states $\{a\}$ (we use here the standard pictorial notation for automata)
\begin{center}
\begin{tikzpicture}[->,>=stealth',semithick,shorten >= 1pt,node distance=2cm,auto]
	\node[state,initial,accepting] (a) {$a$};
	\node[state] (b) [right of=a] {$b$};
	\path[->]   
	    (a) edge [loop above] node {$g$} (a)
	    (a) edge [bend left] node {$f$} (b)
	    (b) edge [bend left] node {$f$} (a)
	    (b) edge [loop above] node {$g$} (b)
	;
\end{tikzpicture}
\end{center} and the automaton $\mathfrak A_{b\to \{a\}}$ by
\begin{center}
\begin{tikzpicture}[->,>=stealth',semithick,shorten >= 1pt,node distance=2cm,auto,initial where=right]
	\node[state,accepting] (a) {$a$};
	\node[state,initial] (b) [right of=a] {$b$};
	\path[->]   
	    (a) edge [loop above] node {$g$} (a)
	    (a) edge [bend left] node {$f$} (b)
	    (b) edge [bend left] node {$f$} (a)
	    (b) edge [loop above] node {$g$} (b)
	;
\end{tikzpicture}
\end{center} We then clearly have
\begin{align*} 
	\uparrow_\mathfrak A a=||\mathfrak A_{a\to \{a\}}||\cup ||\mathfrak A_{b\to \{a\}}||.
\end{align*}
\end{example}

It is straightforward to generalize the construction in \prettyref{e:A}: 

\begin{definition} Given a finite unary algebra (semiautomaton) $\mathfrak A=(A,\Sigma)$, the automaton $\mathfrak A_{b\to \{a\}}$ is the automaton induced by the functions in $\Sigma$ with start state $b$ and single final state $a$ given by
\begin{align*} 
	\mathfrak A_{b\to \{a\}}:=(A,\Sigma,b,\{a\}).
\end{align*} 
\end{definition}

\begin{fact} Given any finite\footnote{Finiteness is required since regular languages are not closed under \textit{infinite} union.} unary algebra (semiautomaton) $\mathfrak A=(A,\Sigma)$ and $a\in A$, we have
\begin{align}\label{equ:uparrow_a}
	\uparrow_\mathfrak A a=\bigcup_{b\in A} ||\mathfrak A_{b\to \{a\}}||.
\end{align}
\end{fact}

We are now ready to prove the main result of this section:

\begin{theorem} Let $\mathfrak A=(A,\Sigma^ \mathfrak A)$ and $\mathfrak B=(B,\Sigma^ \mathfrak B)$ be finite unary algebras (semiautomata) over the same set of function symbols (input alphabet) $\Sigma$. We have the following:
\begin{enumerate}
	\item For any element (state) $a\in A$, $\uparrow_ \mathfrak A a$ is a regular language.
	\item For any elements (states) $a\in A$ and $b\in B$, $a\uparrow_{ \mathfrak{(A,B)}} b$ is a regular language.
	\item For any elements (states) $a\in A$ and $b\in B$, $a\Uparrow_{ \mathfrak{(A,B)}} b$ is computable.
\end{enumerate}
\end{theorem}
\begin{proof} Since $A$ is finite and since regular languages are known to be closed under finitely many unions, we conclude by \prettyref{equ:uparrow_a} that $\uparrow_ \mathfrak A a$ is a regular language.

Since regular languages are known to be closed under finitely many intersections and since we already know that $\uparrow_ \mathfrak A a$ and $\uparrow_ \mathfrak B b$ are regular languages, we conclude that
\begin{align*} 
	a\uparrow_{ \mathfrak{(A,B)}} b=(\uparrow_\mathfrak A a)\cap (\uparrow_\mathfrak B b)
\end{align*} is a regular language.

Given some word $w\in a\uparrow_{ \mathfrak{(A,B)}} b$ (recall that we identify the term $wx\in T_{\Sigma,\{x\}}$ with the word $w\in\Sigma^\ast$ since $x$ bears no information), we have $w\in a\Uparrow_{ \mathfrak{(A,B)}} b$ iff the term $wx\in T_{\Sigma,\{x\}}$ is $\sqsubseteq_\mathfrak A$-minimal and $\sqsubseteq_\mathfrak B$-minimal, which amounts to deciding whether there is some term $ux\in T_{\Sigma,\{x\}}$ such that $u\in a\uparrow_{ \mathfrak{(A,B)}} b$ and
\begin{align*} 
	\left\{u^ \mathfrak A(a)\in A \;\middle|\; a\in A\right\}\subsetneq \left\{w^ \mathfrak A(a)\in A \;\middle|\; a\in A\right\} \quad\text{or}\quad \left\{u^ \mathfrak B(b)\in B \;\middle|\; b\in B\right\}\subsetneq \left\{w^ \mathfrak B(b)\in B \;\middle|\; b\in B\right\}.
\end{align*} In a finite algebra, this is clearly a computable relation. Hence, $a\Uparrow_ \mathfrak A b$ is computable in finite unary algebras (semiautomata).
\end{proof}

