\subsection{HDG Notation}\label{ss:Notation_hdg} 
Let $\Th$ be a quasi-uniform mesh \cite{MR1930132} consisting of disjoint elements that partition $\overline{\Omega}$, with mesh size parameter $h$, the maximum inner diameter among all elements in $\Th$. Let $\Faces$ denote the set of all edges, with $\Facesinterior$ and $\Facesboundary$ representing the subsets of the interior and boundary edges, respectively. For an element $K \in \Th$, we denote by $\partial K$ the set of edges that form its boundary, and then $\Skeleton$ denotes the union of all the boundaries of the elements in the mesh $\Th$, and is commonly called the mesh skeleton.

Let $\Kprod{\cdot}{\cdot}$ and $\pKprod{\cdot}{\cdot}$ be the $L^2$--inner products over $K$ and $\partial K$, respectively.    
In addition, the piecewise $L^2$--inner products are defined as
\[
\Thprod{\cdot}{\cdot}:=\sum_{K\in \Th} \Kprod{\cdot}{\cdot}, \quad
\pThprod{\cdot}{\cdot} :=\sum_{K\in \Th}\pKprod{\cdot}{\cdot}.
\]
Analogous definitions apply to vector-valued functions. The norms induced by the inner products above are denoted by $\Thnorm{\cdot}$ and $\pThnorm{\cdot}$. We also introduced a notation for the weighted norms induced by the inner products above
\[
\|\cdot\|_{\Th,c}^{2} = \Thprod{c \cdot}{\cdot}, \quad \|\cdot\|_{\partial \Th, a}^2 =\pThprod{a \cdot}{\cdot}, 
\]
for $c,a\geq 0.$
\begin{comment}
Define the jumps of the scalar and vector function $\varphi$ and $\zb$, in the normal and tangential directions across the interior edge $\partial K^{-}\cap \partial K^{+}=:F \in \Facesinterior$, for $K^{-}, K^{+}\in \Th$, by
\begin{alignat*}{4}
   \jump{\varphi \, \normal}&:=\varphi^{+}  \normal^{+}+\varphi^{-}  \normal^{-},  & \quad   \jump{\varphi \, \normal^\perp}&:=\varphi^{+} (\normal^\perp )^+ +\varphi^{-} (\normal^\perp)^{-},\\   
   \jump{\zb \cdot \normal}&:=\zb^{+} \cdot \normal^{+}+\zb^{-} \cdot \normal^{-}, & \quad   \jump{\zb \cdot \normal^\perp}&:=\zb^{+}\cdot (\normal^\perp )^+ +\zb^{-}\cdot (\normal^\perp)^{-},
\end{alignat*}
where $\normal^{\pm}$ are the outward unit normals to $K^{\pm}$, and  $\varphi^{\pm}=\varphi|_{K^{\pm}}$ and $\zb^{\pm}=\zb|_{K^{\pm}}$. On boundary edges $F\in \Facesboundary$, we simply define
\begin{alignat*}{4}
 \jump{\varphi \, \normal}&:=\varphi \, \normal,  & \quad   \jump{\varphi \, \normal^\perp}&:=\varphi \, \normal^\perp,&\quad
   \jump{\zb \cdot \normal}&:=\zb\cdot \normal, & \quad   \jump{\zb \cdot \normal^\perp}&:=\zb \cdot \normal^\perp.
\end{alignat*}
We say that the $\varphi$ is single-valued if $\jump{\varphi \, \normal}=0$ and
$\jump{\varphi \, \normal^\perp}=0$ on $\Facesinterior$. Similarly, $\zb$ is single-valued if $\jump{\zb \cdot \normal}=0$ and
$\jump{\zb \cdot \normal^\perp}=0$ on $\Facesinterior$.
