\subsection{Initial condition for the $(\velocity-\displacement)$ formulation.} \label{ss:initialcondition}
In symplectic Hamiltonian finite element methods, the initialization plays a crucial role, as the accuracy of the semi-discrete method depends critically on it. For instance, HDG methods applied to the scalar wave equation, both in its second-order form \cite{CockburnFuHungriaSanchezSayas2018} and as a first-order system \cite{SanchezCiucaNguyenPeraireCockburn2017}, employ an initialization based on the approximation of a steady-state problem. This strategy has been shown to be essential in achieving optimal convergence. These initialization procedures typically involve computing compatible initial approximations of both the numerical trace and the volumetric variables. Treating them as independent quantities can lead to suboptimal accuracy, as demonstrated in \cite{CockburnFuHungriaSanchezSayas2018}.
In our setting, we seek initial approximations of the auxiliary variable $\displacement_h(0) \in \vect{V}_h$, the geopotential height $\phi_h(0) \in W_h$, and its numerical trace $\phihat_h(0) \in M_h$ that satisfy the steady-state equations \eqref{eq:HDG-velocity-w:c} and \eqref{eq:HDG-velocity-w:d}, given the initial data $\phi_0$. To this end, we consider the HDG approximation of the following steady-state problem: Given $\fb \in \vect{L}^2(\Omega)$, find a vector-valued function $\displacement$ such that
\begin{subequations}\label{eq:hodge-laplacian}
\begin{alignat}{4}
\label{eq:hodge-laplacian:a}
\curl\, \rot\, \displacement - \grad(\divergence \displacement) &= \fb, \quad & \text{in } \Omega, \\
\label{eq:hodge-laplacian:b}
\displacement \cdot \normal &= 0, & \quad \text{on } \Gamma, \\
\label{eq:hodge-laplacian:c}
\rot\, \displacement &= 0, & \quad \text{on } \Gamma.
\end{alignat}
\end{subequations}
This problem corresponds to the well-known two-dimensional vector-Laplacian equation, studied in  \cite{AwanouGuzmanStern2020, ArnoldFalkGopalakrishnan2012}, with magnetic boundary conditions. The connection between the solution of this problem and the initialization of the auxiliary variable becomes evident when noting that, if $\rot\, \displacement = 0$ and $\fb = \grad \phi_0$, then
\[
- \grad(\divergence \displacement) = \grad \phi_0,
\]
which implies that the auxiliary variable $\displacement$ serves as a potential function whose divergence recovers the initial geopotential gradient.
%\todo{Change $\perp$ definition to $\velocity^{\perp} = [u_2, -u_1]^{\top}$}
We now define an HDG approximation of the two-dimensional vector Laplacian equation \eqref{eq:hodge-laplacian}. To this end, we introduce the scalar variables $\phi = -\divergence \displacement$ and $\sigma = \rot\, \displacement$. We seek approximations $(\displacement_h, \phi_h, \sigma_h) \in \vect{V}_h \times W_h \times W_h$ to $(\displacement, \phi, \sigma)$ in the mesh $\Th$, along with the trace unknowns $(\phihat_h, \widecheck{\displacement}_h) \in M_h \times \Nhperp$ that approximate $\phi$ and the tangential component of $\displacement$ on the mesh skeleton $\Faces$, such that
\begin{subequations}\label{eq:HDG-hodge-laplacian}
\begin{alignat}{4}
\label{eq:HDG-hodge-laplacian:a}
\Thprod{\sigma_h}{\chi}-\Thprod{\displacement_h}{\curl \chi} + \pThprod{\widecheck{\displacement}_h\cdot \normal^{\perp}}{\chi}& =0, & \quad \forall \chi \in {W}_{h}, \\ 
\label{eq:HDG-hodge-laplacian:b}
\Thprod{\phi_h}{\varphi}-\Thprod{\displacement_h}{\grad\varphi}+\pThprod{\widehat{\displacement}_h\cdot \normal}{\varphi
} & =0, & \quad \forall  \varphi \in {W}_{h},
\\ 
\label{eq:HDG-hodge-laplacian:c}
\Thprod{\sigma_h}{\rot \, \zb}+
\pThprod{\sigmacheck_h}{\zb \cdot \normal^{\perp}} - 
\Thprod{\phi_h}{\divergence \zb} +
\pThprod{\phihat_h}{ \zb \cdot \normal } 
& =\Thprod{\fb}{ \zb}, &  \quad \forall \boldsymbol{ z} \in \velocity_h, 
\end{alignat}
where the numerical fluxes are given by
\begin{alignat}{4} 
\label{eq:HDG-hodge-laplacian-d} 
\sigmacheck_h=\sigma_h+\alpha^{-1}(\displacement_h\cdot\normal^{\perp}-\widecheck{\displacement}_h \cdot\normal^{\perp}) & \quad \text{ on } \partial \Th, \\
\label{eq:HDG-hodge-laplacian-e}
\widehat{\displacement}_h\cdot \normal = \displacement_h\cdot\normal+\tau (\phi_h -\phihat_h)& \quad \text{ on } \partial \Th,  
\end{alignat}
for stabilization parameters $\alpha>0$ and $\tau >0$. Imposing the weak continuity of $\sigmacheck_h$ and $\widehat{\displacement}_h\cdot \normal$, completes the system,
\begin{alignat}{4}     
\label{eq:HDG-hodge-laplacian-f}
\pThprod{\sigmacheck_h}{\mub \cdot \normal^\perp}&=0,&  &\quad \forall \mub \in \Nhperp, \\ 
\label{eq:HDG-hodge-laplacian-g}
\pThprod{\widehat{\displacement}_h \cdot \normal}{\mu} &=0,& & \quad \forall {\mu}\in {M}_{h}. 
\end{alignat}
%and the homogeneous boundary condition
%\begin{alignat}{4}  
%\label{eq:HDG-hodge-laplacian:h}
%\Gprod{\sigmacheck_h}{\mu} &=0,  & \quad \forall {\mu}\in {M}_{h}.
%\end{alignat}
\end{subequations}
Next, we will prove the existence and uniqueness of the HDG approximation \eqref{eq:HDG-hodge-laplacian}.
\begin{theorem}
Assume that $\alpha, \tau>0$. Then, the HDG system \eqref{eq:HDG-hodge-laplacian} is well-posed.
\end{theorem}
\begin{proof}
Assume that $\fb=0$. Testing with $\chi=\sigma_h$, $\varphi=\phi_h$ in \eqref{eq:HDG-hodge-laplacian:a} and \eqref{eq:HDG-hodge-laplacian:b} and replacing the definition \eqref{eq:HDG-hodge-laplacian-e} of $\widehat{\displacement}\cdot \normal$, and integrating by parts, we obtain
% \begin{alignat*}{4}\label{hl01}
% \Thprod{\sigma_h}{\sigma_h}-\Thprod{\displacement_h}{\curl \, \sigma_h} + \pThprod{\widecheck{\displacement}_h \cdot \normal^\perp}{\sigma_h} & =0, 
% \\ 
% \Thprod{\phi_h}{\phi_h}- \Thprod{\displacement_h}{\grad\phi_h}+ 
% \pThprod{\displacement_h\cdot\normal+\tau(\phi_h-\phihat_h)}{\phi_h} & =0.
% \end{alignat*}
% Integrating by parts in the above equations, we obtain
\begin{alignat*}{4}
\Thprod{\sigma_h}{\sigma_h}-\Thprod{\rot\,\displacement_h}{\sigma_h}-\pThprod{\displacement_h \cdot \normal^{\perp}}{\sigma_h} + \pThprod{\widecheck{\displacement}_h\cdot\normal^{\perp}}{\sigma_h}=0, & \\
\Thprod{\phi_h}{\phi_h}+\Thprod{\divergence \displacement_h}{\phi_h}-\pThprod{\displacement_h\cdot \normal}{\phi_h} +\pThprod{\displacement_h\cdot \normal+\tau(\phi_h-\phihat_h)}{\phi_h} =0.&
\end{alignat*}
It follows that  
\begin{alignat*}{4}
\Thprod{\rot \,\displacement_h}{\sigma_h} &=& \Thprod{\sigma_h}{\sigma_h} - \pThprod{(\displacement_h-\widecheck{\displacement}_h)\cdot\normal^{\perp}}{\sigma_h},  \\
\Thprod{\divergence \displacement_h}{\phi_h} &=&- \Thprod{\phi_h}{\phi_h}- \pThprod{\tau(\phi_h-\phihat_h)}{\phi_h}.
\end{alignat*}
Now, taking $\zb=\displacement_h$ in \eqref{eq:HDG-hodge-laplacian:c} and using the last two equations, we obtain 
\begin{alignat*}{4}
\Thprod{\sigma_h}{\sigma_h}  - \pThprod{(\displacement_h-\widecheck{\displacement}_h)\cdot\normal^{\perp}}{\sigma_h}+
\pThprod{\sigmacheck_h}{\displacement_h \cdot\normal^{\perp} } + 
\Thprod{\phi_h}{\phi_h} & \\ +
\pThprod{\tau(\phi_h-\phihat_h)}{\phi_h} + 
\pThprod{ \phihat_h}{\displacement_h \cdot \normal } & =0.
\end{alignat*}
The last expression can be rewritten as
\begin{alignat*}{4}
\Thprod{\sigma_h}{\sigma_h} + 
\Thprod{\phi_h}{\phi_h} 
+\pThprod{(\displacement_h -\widecheck{\displacement}_h)\cdot \normal^\perp}{\alpha^{-1}(\displacement_h -\widecheck{\displacement}_h) \cdot \normal^\perp} &
\\ +\pThprod{\tau (\phi_h -\phihat_h)}{(\phi_h -\phihat_h)} +  
\pThprod{\sigmacheck_h}{\widecheck{\displacement}_h \cdot \normal^\perp}+
\pThprod{\widehat{\displacement}_h \cdot \normal}{\phihat_h}
 &=0.
\end{alignat*}
Using the continuity conditions \eqref{eq:HDG-hodge-laplacian-f} and \eqref{eq:HDG-hodge-laplacian-g}, we observe that the last two terms of the left-hand side are zero. Thus, we obtain
 \begin{alignat*}{4}
\Thprod{\sigma_h}{\sigma_h} + 
\Thprod{\phi_h}{\phi_h} 
+\pThprod{\alpha^{-1}(\displacement_h -\widecheck{\displacement}_h)\cdot \normal^\perp}{(\displacement_h -\widecheck{\displacement}_h) \cdot \normal^\perp}& \\
+\pThprod{\tau (\phi_h -\phihat_h)}{(\phi_h -\phihat_h)} &=0.
\end{alignat*}
Since we have the sum of four non-negative terms equal to zero, we can deduce that each term is zero. Therefore, it follows that $ \sigma_h=0, \ \phi_h=0, \  \displacement_h \cdot \normal^\perp=\widecheck{\displacement}_h \cdot \normal^\perp$ and $\phihat_h=0$ on $\partial \Th$. Replacing these zero values in the continuity equations gives that
 \begin{alignat*}{4}
\pThprod{\displacement_h \cdot \normal}{\mu} = 0,%& \quad
%\pThprod{\sigma_h}{\mub \cdot \normal^\perp} =0,
\end{alignat*}
for all $\mu \in M_h$.% and $\mub \in \Nhperp$. This implies that $\displacement_h\cdot \normal = 0$ on $\Gamma$. 
Thus,  replacing $\sigma_h=0$ and $\displacement_h \cdot \normal^\perp=\widecheck{\displacement}_h \cdot \normal^\perp$ in \eqref{eq:HDG-hodge-laplacian:a}, we obtain
\[
\Thprod{\rot\,\displacement_h}{\chi} = 0.
\]
Analogously, replacing $\phi_h = 0 $ and $\phihat_h =0$ in \eqref{eq:HDG-hodge-laplacian:b}, we obtain that
\[
\Thprod{\divergence \displacement_h}{\varphi} = 0.
\]
Since $\rot \, \boldsymbol{\mathcal{P}}_k(K)\subseteq \mathcal{P}_k(K)$ and $\divergence \boldsymbol{\mathcal{P}}_k(K) \subseteq \mathcal{P}_k(K)$ then we conclude that $\rot \, \displacement_h=0$ and $\divergence \displacement_h=0$.
Using the decomposition, for $\displacement_h\in \ring{H}(\divergence)\bigcap H(\rot)$, \cite{girauld}
\[
\displacement_h = \grad{\psi} + \curl\, q,
\]
where $\psi\in H^1(\Omega) \bigcap L_0^2(\Omega)$ and $q\in H^1(\Omega)$ are solutions of the problems
\begin{equation*}
\begin{minipage}{0.45\textwidth}
\begin{alignat*}{2}
    -\Delta \psi &= \divergence \displacement_h = 0 \quad &&\text{in } \Omega, \\
    \frac{\partial \psi}{\partial \normal} &= 0 \quad &&\text{on } \Gamma,
\end{alignat*}
\end{minipage}
\hfill
\text{and}
\hfill
\begin{minipage}{0.45\textwidth}
\begin{alignat*}{2}
    -\Delta q &= \rot \displacement_h = 0 \quad &&\text{in } \Omega, \\
    q &= 0 \quad &&\text{on } \Gamma.
\end{alignat*}
\end{minipage}
\end{equation*}
Then, it follows that $\displacement_h = \grad{0} + \rot\, 0 = 0$.
Therefore, we have shown that the solution operator is injective, and given that we are working in finite-dimensional spaces, we deduce that the operator is bijective, and consequently, the problem is well-posed.
\end{proof}
