\section{Fully discrete symplectic HDG schemes}\label{sec:section5}
This section presents a matrix formulation of the HDG method along with an alternative proof of its Hamiltonian structure. We then introduce fully discrete schemes for the $(\velocity-\displacement)$ formulation \eqref{eq:LSWEs2} by coupling the HDG method with high-order symplectic time integrators. Two classes are considered: sDIRK methods, which exactly conserve energy for quadratic Hamiltonians, and sEPRK methods, suitable for separable Hamiltonians and known for their non-drifting energy behavior \cite{sanzserna,McLachlan94}. 
%%%%%%%%%%%%%%%%%%%%%%%%subsection %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Finite dimensional Hamiltonian system}\label{ss:finite-dimensional-Hamiltonian}
We follow the approach described in \cite{CockburnDuSanchez2023} and present the matrix representation of the semi-discrete HDG scheme \eqref{eq:HDG-velocity-w}. To this end, let $\left\{\varphi_{i}\right\}$, $\left\{\zb_{k}\right\}$, and $\left\{\eta_{m}\right\}$ denote orthonormal bases for the finite element spaces $W_h$, $\vect{V}_h$, and $M_h$, respectively, with indices ranging over the dimensions of the corresponding spaces. We define the following matrices
\begin{alignat*}{4} 
\mathrm{A}_{kl}&:=\Thprod{\zb_{l}^{\perp}}{\zb_{k}},&  \quad
\mathrm{B}_{ki}&:=\Thprod{\varphi_i}{\divergence\zb_{k}},& \quad 
\mathrm{C}_{km}&:=\pThprod{\eta_m}{\zb_{k} \cdot \normal}, 
\\
\mathrm{S}_{ij}&:=\pThprod{\tau \varrho_j}{\varrho_{i}},& \quad
\mathrm{E}_{im}&:=\pThprod{\tau \eta_m}{\varrho_{i}}, &\quad 
\mathrm{G}_{mn}&:=\pThprod{\tau \eta_n}{\eta_{m}}.
\end{alignat*}
Subsequently, the  unknowns $(\velocity_h,\displacement_h, \phi_h, \phihat_h)$ of system \eqref{eq:HDG-velocity-w} are represented in terms of the coefficient vectors $(\mathsf{u}, \mathsf{w}, \mathsf{p}, \widehat{\mathsf{p}})$ as follows
\begin{alignat*}{4}
\velocity_{h}(x, t)&=\sum_{k} \mathsf{u}_{k}(t) \zb_{k}(x), 
& \quad \displacement_{h}(x, t)&=\sum_{k} \mathsf{w}_{k}(t) \zb_{i}(x), \\ 
\phi_{h}(x, t)&=\sum_{i} \mathsf{p}_{i}(t) \varrho_{i}(x),
 & \quad  \phihat_{h}(x, t)&=\sum_{m} \widehat{\mathsf{p}}_{m}(t) \eta_{m}(x) .
\end{alignat*}
Thus, we rewrite the HDG scheme \eqref{eq:HDG-velocity-w} as the following system of ordinary differential equations: find  the coefficient vectors $(\mathsf{u}, \mathsf{w}, \mathsf{p}, \widehat{\mathsf{p}})$ such that
\begin{subequations}\label{eq:ODEHDG-velocity-w}
\begin{alignat}{4}
\label{eq:ODEHDG-velocity-w:a}
\partialt{\mathsf{w}}&= \Phi\mathsf{u},\\ 
\label{eq:ODEHDG-velocity-w:b}
\partialt{\mathsf{u}}&= \mathrm{B} \mathsf{p}- \mathrm{C} \widehat{\mathsf{p}} + \mathrm{A} \mathsf{u}  \\
\label{eq:ODEHDG-velocity-w:c}
0 & =\mathsf{p} + \mathrm{B}^\top \mathsf{w} + \mathrm{S}\mathsf{p} -  \mathrm{E} \widehat{\mathsf{p}} \\
\label{eq:ODEHDG-velocity-w:d}
0 & = \mathrm{C}^{\top} \mathsf{w} + \mathrm{E}^{\top} \mathsf{p} - \mathrm{G} \widehat{\mathsf{p}}
\end{alignat}
\end{subequations}
The Hamiltonian functional \eqref{eq:Hamiltonian_h} is written in terms of the coefficients $\mathsf{u}$ and $\mathsf{v}$ as follows
\begin{alignat}{4}\label{eq:ODEHamiltonian_h}
\mathsf{H}[\mathsf{u}, \mathsf{w}] = 
\frac{1}{2} \mathsf{p}^\top\mathsf{p} + 
\frac{1}{2}\Phi \mathsf{u}^\top\mathsf{u} + 
\frac{1}{2} \begin{bmatrix} \mathsf{p}^\top, \widehat{\mathsf{p}}^\top \end{bmatrix}\begin{bmatrix} \mathrm{S} & -\mathrm{E} \\ -\mathrm{E}^\top & \mathrm{G} \end{bmatrix} \begin{bmatrix}  \mathsf{p} \\ \widehat{\mathsf{p}}\end{bmatrix}
\end{alignat}
We now prove that \eqref{eq:ODEHDG-velocity-w} is a Poisson system, or generalized Hamiltonian system, according to \cite{CockburnDuSanchez2023}.
\begin{theorem}\label{thm:ODEHDG-Hamiltonian}
The system of ODEs \eqref{eq:ODEHDG-velocity-w} is a Poisson system, \textit{i.e.}, is equivalent to $\partialt{\yb} = \mathrm{J} \nabla \mathsf{H}$, for $\yb = [\mathsf{u}, \mathsf{w}]$, with Hamiltonian function $\mathsf{H} = \mathsf{H}[\mathsf{u}, \mathsf{w}]$ defined in \eqref{eq:ODEHamiltonian_h} and structure matrix
\[
\mathrm{J} = 
\begin{bmatrix}
    f\Phi^{-1}\mathrm{A} & -\mathrm{I} \\
    \mathrm{I} & 0
\end{bmatrix}.
\]
\end{theorem}
\begin{proof}
We compute the derivatives of the Hamiltonian function. First, we observe that
\(
\partial \mathsf{H}/\partial \mathsf{u} = \Phi \mathsf{u}.
\)
To compute the partial derivative with respect to $\displacement$ we rearrange the term in the Hamiltonian as
\[
\frac{\partial \mathsf{H}}{\partial \mathsf{w}} = \frac{\partial}{\partial \mathsf{w}}
\left(
\frac{1}{2} \begin{bmatrix} \mathsf{p}^\top, \widehat{\mathsf{p}}^\top \end{bmatrix}\begin{bmatrix} \mathrm{I} + \mathrm{S} & -\mathrm{E} \\ -\mathrm{E}^\top & \mathrm{G} \end{bmatrix} \begin{bmatrix}  \mathsf{p} \\ \widehat{\mathsf{p}}\end{bmatrix}
\right)
=
\left(
\begin{bmatrix} \mathsf{p}^\top, \widehat{\mathsf{p}}^\top \end{bmatrix}\begin{bmatrix} \mathrm{I} + \mathrm{S} & -\mathrm{E} \\ -\mathrm{E}^\top & \mathrm{G} \end{bmatrix} \begin{bmatrix}  \partial \mathsf{p}/\partial \mathsf{w} \\ \partial \widehat{\mathsf{p}}/ \partial \mathsf{w}\end{bmatrix}
\right)^\top.
\]
Using \eqref{eq:ODEHDG-velocity-w:c}-\eqref{eq:ODEHDG-velocity-w:d} we arrive to the system
\[
\begin{bmatrix}
\mathrm{I} + \mathrm{S} & -\mathrm{E} \\
-\mathrm{E}^\top & \mathrm{G}
\end{bmatrix}
\begin{bmatrix}
\mathsf{p} \\
\widehat{\mathsf{p}}
\end{bmatrix}
=
\begin{bmatrix}
-\mathrm{B}^\top \\
\mathrm{C}^\top
\end{bmatrix}
\mathsf{w}.
\]
Differentiating with respect to $\mathsf{w}$ the system above, we can conclude  that
\[
\frac{\partial \mathsf{H}}{\partial \mathsf{w}} = 
\left(
\begin{bmatrix} \mathsf{p}^\top, \widehat{\mathsf{p}}^\top \end{bmatrix}
\begin{bmatrix}
-\mathrm{B}^\top \\
\mathrm{C}^\top
\end{bmatrix}
\right)^\top
= -\mathrm{B} \mathsf{p} + \mathrm{C} \widehat{\mathsf{p}}.
\]
Then, the theorem statement follows from the definition of the anti-symmetric structure operator $\mathrm{J}$ and the partial derivatives of $\mathsf{H}$ which turn equivalent to the dynamical system \eqref{eq:ODEHDG-velocity-w:a}-\eqref{eq:ODEHDG-velocity-w:b}. This completes the proof.
\end{proof}
