            Straight Forwards (SF) & ($a$, $a$) \\
            \hline
            Straight Backwards (SB) & ($-a$, $-a$) \\
            \hline
            Circular Forwards (CF) & ($a$, $ b$) \\
             \hline
            Circular Backwards (CB) & ($-a$, $ -b$) \\
             \hline
