\begin{theorem}
    \label{thrm:N deadlock}
    Consider a \textup{CB-XX} controller $u\in \U$ such that control A induces a circular motion of radius $R>1.707r$. Fix an even number of robots $n\geq 4$. Then the probability of nonaggregation of $\pi_{u,x_0}$ over the uniform random 
    choice of the initial MR state $x_0$ from a large enough workspace is strictly positive. 
\end{theorem}

