  \centering
  \includegraphics[width=1.0\textwidth]{media/arena_2019-10-16_Arena-0191_nikolas_linke_credit.jpg}
  \caption{The ARENA2 visualization dome at the GEOMAR Helmholtz Center for Ocean Research Kiel}
  \label{fig:ARENA2_photo}
