\section{Background}
Here we introduce the necessary background for understanding LrcSSMs: Firstly, the bioinspired nonlinear liquid networks LTCs, STCs, and LRCs, known for their dynamic expressivity. Secondly, the parallelization techniques enabling efficient training of traditionally sequential NSSMs.

\subsection{Bio-inspired Liquid Neural Networks}

Electrical Equivalent Circuits (EECs) are simplified models defining the dynamic behavior of the membrane potential (MP) of a postsynaptic neuron, as a function of the MP of its presynaptic neurons and external input signals~\citep{kandel2000principles,wicks1996dynamic}. In ML, EECs with chemical synapses are termed liquid time constant networks (LTCs)~\citep{lechner2020neural, hasani2021liquid}. For a neuron $i$ with $m$ presynaptic neurons of MPs $x$ and $n$ inputs of value $u$, the forget conductance \textcolor{teal}{$f_{i}(x,u)$} and update conductance \textcolor{blue}{$z_{i}(x,u)$} are defined as:
%
\begin{align}
    \textcolor{teal}{f_{i}(x,u)} &= \sum_{j=1}^{m+n} g_{ji}^{max}\sigma(a_{ji}y_j+b_{ji}) + g_{i}^{leak}\label{eq:fi} \\%[2mm]
    \textcolor{blue}{z_{i}(x,u)} &= \sum_{j=1}^{m+n} k_{ji}^{max}\sigma(a_{ji}y_j+b_{ji}) + g_{i}^{leak}, \label{eq:zi}
\end{align}
%
where $y\,{=}\,[x,u]$ concatenates the MP (state) of all neurons and the inputs. In Equation~\eqref{eq:fi}, $g_{ji}^{max}$ represents the maximum synaptic channel conductance, $a_{ji}$ and $b_{ji}$ parameterize the sigmoidal activation governing channel openness, and $g_{i}^{leak}$ is the leaking conductance.
%
In Equation~\eqref{eq:zi}, $k_{ji}^{max}\,{=}\,g_{ji}^{max}e_{ji}^{rev}{/}e_{i}^{leak}$, where $e_{ji}^{rev}$ is the synaptic reversal potential (equilibrium membrane potential) and $e_{i}^{leak}$ is the leaking potential. Since $g_{ji}^{max}\geq 0$, the sign of $k_{ji}^{max}$ depends on $e_{ji}^{rev}{/}e_{i}^{leak}$.

LTC-Equation~\eqref{eq:ltc} states that the rate of change of $x_i$ of neuron $i$, is the sum of its forget current $-f_i\,x_i$ and its update current $z_i\,e_{i}^{leak}$. LTCs ignore saturation aspects, which were introduced in saturated LTCs (STCs) in~\cite{farsang2024learning}. As $\textcolor{teal}{f_{i}(x,u)}$ is positive, it is saturated with a sigmoid, and as $\textcolor{blue}{z_{i}(x,u)}$ is either positive or negative, it is saturated with a tanh. Saturation is capturd in STC-Equation~\eqref{eq:stc}.

Finally, both LTCs and STCs assume that the membrane capacitance is constant, and for simplicity equal to 1 in Equations~\eqref{eq:ltc}-\eqref{eq:stc}, as the capacitance can be learned jointly with the other parameters. However, this assumption does not hold in biological neurons. In reality, the capacitance has a nonlinear dependence on the MP of presynaptic neurons and the external input as they both may cause the neuron to deform~\citep{capacitanceDepOnFrequency,capacitanceDepOnDaytime,capacitanceDepOnState}. This behavior can be modeled by the following elastance:
%
\begin{equation}
    \sigma(\textcolor{orange}{\epsilon_i(x,u)}) =\sigma(\sum_{j=1}^{m+n}w_{ji}y_j+v_{j}), \label{eq:ei}
\end{equation}
%
where $y = [x, u]$, as before. LRCs incorporate this biological behavior of neurons, by introducing the elastance (which is the reciprocal of the capacitance) as a multiplicative term in LRC-Equation~\eqref{eq:lrc}.
%
\begin{align}
    \text{LTC:\quad} \dot{x}_i &=\hspace*{5mm}-\textcolor{teal}{f_i(x,u)}\,x_i \hspace*{1.5mm}+ \hspace*{3mm}\textcolor{blue}{z_i(x,u)}\,e_{i}^{leak}\label{eq:ltc} \\[2mm] 
    \text{STC:\quad}\dot{x}_i &=\hspace*{1.5mm}-\sigma(\textcolor{teal}{f_i(x,u)})\,x_i + \tau(\textcolor{blue}{z_i(x,u)})\,e_{i}^{leak}\label{eq:stc} \\[2mm]
    %\dot{x}_i^{LRC} &=\sigma(\textcolor{orange}{\epsilon_i(x,u)})\,\dot{x}_i^{STC}\label{eq:lrc} \\
    \text{LRC:\quad}\dot{x}_i &=(-\sigma(\textcolor{teal}{f_i(x,u)})\,x_i+ \tau(\textcolor{blue}{z_i(x,u)})\,e_{i}^{leak})\,\sigma(\textcolor{orange}{\epsilon_i(x,u)})\label{eq:lrc}
\end{align}
%
The time constant of LRCs is $\frac{1}{RC} = \sigma(\textcolor{teal}{f_i(x,u)})\,\sigma(\textcolor{orange}{\epsilon_i(x,u)})$, which factors into a liquid resistance $R=1/\sigma(\textcolor{teal}{f_i(x,u)})$ and a liquid capacitance $C=1/\sigma(\textcolor{orange}{\epsilon_i(x,u)})$. While the resistive liquidity is the core of both LTCs and STCs, the capacitive liquidity acts as an additional control of the time constant.

The states $\mathbf{x}$ of LRCs at time $t$ can be computed using the explicit Euler integration scheme as:
\begin{equation}
    \text{LRC:\quad}\mathbf{x}_t = \mathbf{x}_{t-1}+ \Delta t\,\mathbf{\dot{x}}_{t-1}
\end{equation}

\subsection{Parallelization Techniques}

%A core insight is that in the setting of evaluating RNNs, Newton’s method can be cast as a parallel scan.
The DEER method~\cite{limparallelizing} formulates next-state computation in NSSMs as a fixed-point problem and solves it using a parallel version of the Newton’s method. At each iteration step, DEER linearizes the NSSM. This approximation is widely effective across many domains, and often yields accurate estimates and fast convergence. The main limitation of DEER is the use of a square Jacobian, which does not scale up to long sequences when included in the parallel scan. The second limitation is its numerical instability, which arises from the nature of Newton’s method. In particular, the undamped version lacks global convergence guarantees and often diverges in practice~\cite{wright2006numerical, gonzalez2024towards}.

As an improvement, \cite{gonzalez2024towards} introduces Quasi-DEER, which scales DEER by using the diagonal of the Jacobian, only. This is shown to achieve convergence comparable to Newton's method while using less memory and running faster. Nevertheless, Quasi-DEER still suffers from limited stability.

% Quasi-DEER
%
% ELK: They apply quasi-Newton approximations and show they converge comparably to Newton, use less memory, and are faster. 
%
To stabilize its convergence, Quasi-DEER leverages a connection between the Levenberg-Marquardt algorithm and Kalman smoothing in their ELK (Evaluating Levenberg-Marquardt with Kalman) algorithm~\cite{gonzalez2024towards}. This stabilization of the Newton iteration by constraining the step size within a trust region, prevents large and numerically unstable updates. 
%To improve efficiency, they approximate the Jacobians using their diagonal form. 
As a result, updates are computed using a parallel Kalman smoother, with a running time that is logarithmic in the length of the sequence. Algorithm~\ref{alg:elk} below, presents this method~\cite{gonzalez2024towards}.

\begin{algorithm}
\caption{ELK}
\begin{algorithmic}[1]
\Procedure{ELK}{$f, s_0, \text{init\_guess}, \text{tol}, \text{method}, \text{quasi}$}
    \State $\text{diff} \gets \infty$
    \State $\text{states} \gets \text{init\_guess}$
    \While{$\text{diff} > \text{tol}$}
        \State $\text{shifted\_states} \gets [s_0, \text{states}[:-1]]$
        \State $f_s \gets f(\text{shifted\_states})$
        \State $J_s \gets \textsc{GetJacobians}(f, \text{shifted\_states})$
        \State $J_s \gets \textsc{Diag}(J_s)$
        \State $b_s \gets f_s - J_s \cdot \text{shifted\_states}$
        \State $\text{new\_states} \gets 
               \textsc{ParallelKalmanFilter}(J_s, b_s, \text{states}, s_0)$
        \State $\text{diff} \gets 
               \lVert\,\text{states} - \text{new\_states}\rVert_\infty$
        \State $\text{states} \gets \text{new\_states}$
    \EndWhile
    \State \Return $\textit{states}$
\EndProcedure
\end{algorithmic}
\label{alg:elk}
\end{algorithm}

