\section{Scaling Up Non-linear LRCs}

% \textbf{Motivation behind simplifying the $A$ and $B$ matrices:}
A scalable DEER or ELK approximation, 
%(i.e., using diagonal Jacobians instead of the full dense form) 
first computes the dense Jacobian of the NSSM, as shown in Line~7 of Algorithm~\ref{alg:elk}, and then extracts its diagonal as shown in Line~8. This results in a quasi approximation of the original DEER technique, called Quasi-DEER and Quasi-ELK~\cite{gonzalez2024towards}.
%
\paragraph{Our Parallelization.} Instead of following this approach, we directly modify the underlying nonlinear LRC of Equation~\eqref{eq:lrc}, such that its Jacobian is diagonal by the formulation itself. The main idea of this modification is that the state-connectivity submatrices $a^x$, $w^x$, $g^{max,x}$, and $k^{max,x}$ of the state-and-input-connectivity matrices $a$, $w$, $g^{max}$, and $k^{max}$, are constant parameter matrices that are theselves diagonlizable. Consequently, all cross terms are zeroed out in the LRC through diagonalization. Accordingly, we learn the complex diagonal matrices directly, instead. 

As a result, our own algorithm is no longer a quasi-approximation, as we do not explicitly remove nondiagonal entries. Instead we learn their contribution to the dynamics, within the complex eigenvalues of the diagonal. Consequently, Line~8, $J_s\,{\leftarrow}\,\text{Diag}(J_s)$ of Algorithm~\ref{alg:elk}, is not needed anymore, and the update computations become more efficient.  In this way, we retain the best of both approaches: A much more precise, more stable, and more scalable, parallelization technique.
%
\subsection{Proposed Model}
In order to achieve a diagonal Jacobian for the LRCs by default, we first modify the Equations~\eqref{eq:fi}-\eqref{eq:ei}, by splitting their summation terms into a state-dependent and an input-dependent group, respectively. For the former, we only keep the self-loop synaptic parameters, and zero out all the cross-state synaptic parameters in the associated matrices. For the latter we keep the influence of all external inputs $u$ through their cross-input synaptic parameters, as this part is  zeroed out anyway in the Jacobian. To highlight the separation of the terms, we include an extra superscript $x$ for the learnable parameters in the state-dependent part, and the superscript of $u$ for the parameters in the input-dependent part. This separation results in Equations~\eqref{eq:fi*}-\eqref{eq:ei*}.

As a consequence, instead of keeping cross-synaptic activations, where each individual synapse between neuron $j$ and $i$ has its own $g_{ji}^{max}$, $b_{ji}$ and $k_{ji}^{max}$ as it was in Equation~\eqref{eq:fi} and~\eqref{eq:zi}, we now only keep the self-loop neural activations, where the synaptic parameters from the same neuron are equal. Note that instead of the \textit{ij} indices, we have only the $j$ index in Equations~\eqref{eq:fi*} and~\eqref{eq:zi*}. 

We denote the modified equations of the LRCs with an asterisk. This gives us the following equations for the $\textcolor{teal}{f_{i}^*(x_i,u)}$, $\textcolor{blue}{z_{i}^*(x_i,u)}$, and $\textcolor{orange}{\epsilon_i^*(x_i,u)}$ terms:

\begin{alignat}{2}
    \textcolor{teal}{f_{i}^*(x_i,u)} &= \underbrace{g_{i}^{max,x}\sigma(a_{i}^{x}x_i+b_{i}^{x})}_\text{$x_i$ state-dependent} &&+ \underbrace{g_{i}^{max, u}\sigma(\sum_{j=1}^{n}a_{ji}^{u}u_j+b_{j}^{u})}_\text{$u$ input-dependent} + g_{i}^{leak}\label{eq:fi*} \\%[2mm]
    \textcolor{blue}{z_{i}^*(x_i,u)} &= \underbrace{k_{i}^{max,x}\sigma(a_{i}^{x}x_i+b_{i}^{x})}_\text{$x_i$ state-dependent} &&+  \underbrace{k_{i}^{max,u}\sigma(\sum_{j=1}^{n}a_{ji}^{u}u_j+b_{j}^{u})}_\text{$u$ input-dependent} + g_{i}^{leak} \label{eq:zi*} \\
    \textcolor{orange}{\epsilon_i^*(x_i,u)} &=\underbrace{w_{i}^{x}x_i +v_i^{x}}_\text{$x_i$ state-dependent} &&+ \underbrace{\sum_{j=1}^{n}w_{ji}^{u}u_j+v_{j}^{u}}_\text{$u$ input-dependent}\label{eq:ei*}
\end{alignat}

\begin{align}
    \text{LrcSSM: \quad}\dot{x}_i &=-\sigma(\textcolor{teal}{f_i^*(x_i,u)})\sigma(\textcolor{orange}{\epsilon_i^*(x_i,u)})\,x_i+ \tau(\textcolor{blue}{z_i^*(x_i,u)})\sigma(\textcolor{orange}{\epsilon_i^*(x_i,u)})\,e_{i}^{leak}\label{eq:lrc_reduced}
\end{align}

For the final form our proposed LRC model, Equation~\eqref{eq:lrc_reduced} can be formulated into the form of SSMs, by taking the vectorial form of the states $\mathbf{x}$ of size $m$ and input vector $\mathbf{u}$ of size $n$:
\begin{equation}
    \text{LrcSSM: \quad} \dot{\mathbf{x}} = \mathbf{A}(\mathbf{x},\mathbf{u}) \mathbf{x} + \mathbf{b}(\mathbf{x},\mathbf{u}),
    \label{eq:LrcSSM}
\end{equation}
where\\
\begin{equation}
\mathbf{A}(\mathbf{x},\mathbf{u})= \text{diag}\begin{bmatrix}
-\sigma(\textcolor{teal}{f_1^*(x_1,u)})\sigma(\textcolor{orange}{\epsilon_1^*(x_1,u)})\\
%0 & -\sigma(\textcolor{teal}{f_2^*(x_2,u)})\sigma(\textcolor{orange}{\epsilon_2^*(x_2,u)}) & 0 &... & 0\\
...\\
-\sigma(\textcolor{teal}{f_i^*(x_i,u)})\sigma(\textcolor{orange}{\epsilon_i^*(x_i,u)})\\
...\\
-\sigma(\textcolor{teal}{f_m^*(x_m,u)})\sigma(\textcolor{orange}{\epsilon_m^*(x_m,u)})\\
\end{bmatrix},
\label{eq:LrcSSM_A}
\end{equation}\\
and \\
\begin{equation}
    \mathbf{b}(\mathbf{x},\mathbf{u})=\begin{bmatrix}
    \tau(\textcolor{blue}{z_1^*(x_1,u)})\sigma(\textcolor{orange}{\epsilon_1^*(x_1,u)})\,e_{1}^{leak} \\
    ...\\
    \tau(\textcolor{blue}{z_i^*(x_i,u)})\sigma(\textcolor{orange}{\epsilon_i^*(x_i,u)})\,e_{i}^{leak} \\
    ... \\
    \tau(\textcolor{blue}{z_m^*(x_m,u)})\sigma(\textcolor{orange}{\epsilon_m^*(x_m,u)})\,e_{m}^{leak} \\
\end{bmatrix}.
\label{eq:LrcSSM_b}
\end{equation}

