\begin{lemma}[Mass Conservation and Flow Generation]
\label{lem:mass_flow}
Let \( p_t(x) \) be a probability density on \( \mathbb{R}^d \) for \( t \in [0,1) \), and \( u_t(x) \) a vector field satisfying: for all \( (t,x) \in [0,1) \times \mathbb{R}^d \), there exists a neighborhood \( \mathcal{U} \subset \mathbb{R}^d \) where \( u_t \) is Lipschitz in \( x \). \( \int_0^1 \int_{\mathbb{R}^d} \|u_t(x)\| p_t(x) dx dt < \infty.\)
\begin{enumerate}
    \item The pair \( (u_t, p_t) \) satisfies the continuity equation:
    \[
    \frac{\partial}{\partial t} p_t(x) + \nabla_x \cdot \big(u_t(x) \, p_t(x)\big) = 0.
    \]
    \item The vector field \( u_t \) generates \( p_t \) through the flow map \( \psi_t \), defined by:
    \[
    u_t \text{ generates } p_t \text{ if } X_t = \psi_t(X_0) \sim p_t \text{ for all } t \in [0,1).
    \]
\end{enumerate}
Furthermore, the flow map satisfies the integral representation:
\[
\psi_t(x) = x + \int_0^t u_s(\psi_s(x)) ds,
\]

\end{lemma}







\begin{proposition}[$L^2$ Distance for Learning Conditional Expectations]
Let $X \in \mathbb{S}_X$, $Y \in \mathbb{S}_Y$ be random variables over state spaces $\mathbb{S}_X,\mathbb{S}_Y$, and let $g: \mathbb{R}^p \times \mathbb{S}_X \to \mathbb{R}^n$ be a function $(\theta, x) \to g^\theta(x)$, where $\theta \in \mathbb{R}^p$ denotes learnable parameters. 
    Let $\|u - v\|^2$ denote the squared $L^2$ distance. Then:
    \begin{equation}
        \nabla_\theta \mathbb{E}_{X,Y} \| Y - g^\theta(X) \|^2 = \nabla_\theta \mathbb{E}_X \| \mathbb{E}[Y|X] - g^\theta(X) \|^2.
    \end{equation}
In particular, for all $x \in \mathbb{S}_X$ with $p_X(x) > 0$, the global minimum of $g^\theta(x)$ with respect to $\theta$ satisfies:
    \begin{equation}
        g^\theta(x) = \mathbb{E} [ Y \mid X = x ].
    \end{equation}
\label{proA.2}
\end{proposition}

\begin{proof}
    Assume $g^\theta$ is differentiable in $\theta$, and that differentiation and integration can be interchanged.

    \begin{align*}
        \nabla_\theta \mathbb{E}_{X,Y} \| Y - g^\theta(X) \|^2 
        &= \mathbb{E}_{X,Y} \left[ \nabla_\theta \| Y - g^\theta(X) \|^2 \right] 
        \quad \text{(interchange $\nabla_\theta$ and $\mathbb{E}$)} \\
        &= \mathbb{E}_X \mathbb{E}_{Y|X} \left[ 2\left(g^\theta(X) - Y\right)^\top \nabla_\theta g^\theta(X) \right] 
        \quad \text{(chain rule on $\| \cdot \|^2$)} \\
        &= \mathbb{E}_X \left[ 2\left(g^\theta(X) - \mathbb{E}[Y|X]\right)^\top \nabla_\theta g^\theta(X) \right] 
        \quad \text{(linearity of $\mathbb{E}_{Y|X}$)} \\
        &= \nabla_\theta \mathbb{E}_X \| \mathbb{E}[Y|X] - g^\theta(X) \|^2 
        \quad \text{(reverse chain rule)}.
    \end{align*}


\end{proof}











\begin{lemma}
Under the assumption that $p_t(x) > 0$ for all $(t,x)$, if $u_t(x|z)$ is conditionally integrable and generates the conditional probability path $p_t(\cdot|z)$, then the marginal velocity field $u_t(x) $ generates the marginal probability path $p_t(x) $ for all $t \in [0,1)$.
\label{lemmaa.3}
\end{lemma}


\begin{proof}
We verify the two conditions of the Mass Conservation Lemma through the following continuous derivation:

\begin{align*}
\frac{\partial}{\partial t}p_t(x) 
&= \int \frac{\partial}{\partial t}p_{t|Z}(x|z)p_Z(z)dz 
\quad  \\
&= -\int \nabla_x \cdot \big[u_t(x|z)p_{t|Z}(x|z)\big]p_Z(z)dz 
\quad \\
&= -\nabla_x \cdot \int u_t(x|z)p_{t|Z}(x|z)p_Z(z)dz 
\quad  \\
&= -\nabla_x \cdot \left[u_t(x)p_t(x)\right] 
\quad
\end{align*}

To verify integrability, apply vector Jensen's inequality to the conditional integrability condition:
\[
\int_0^1 \int \|u_t(x)\|p_t(x)dxdt \leq \int_0^1 \int \int \|u_t(x|z)\|p_{t|Z}(x|z)p_Z(z)dzdxdt < \infty.
\]
The Lipschitz continuity of $u_t(x)$ follows from the $C^1$-smoothness of $u_t(x|z)$ and $p_{t|Z}(x|z)$, which is preserved under convex combinations. 

By satisfying both the continuity equation and the integrability condition, the marginal velocity $u_t(x)$ generates $p_t(x)$ via the flow map $\psi_t(x) = x + \int_0^t u_s(\psi_s(x))ds$.
\end{proof}



\begin{proposition}[Velocity Field of Marginal Probability Paths]
Suppose the following conditions hold:$\psi_t(\cdot|x_0,x_1,h)$ is smooth in $t$ and forms a diffeomorphism over $(x_0, x_1)$, $\pi_{0,1|H}(x_0,x_1|h)$ is the joint distribution of $(X_0, X_1)$ given $H=h$, $p_{t|H}(x|h) > 0$ for all $(t, x, h)$

Then the velocity field of the conditional path is given by:
\[
u_t(x|h) = \mathbb{E}\left[ \dot{\psi}_t(X_0, X_1|h) \ \big| \ X_t = x, H=h \right], \quad t \in [0,1).
\]
\end{proposition}

\begin{proof}
Assume the flow map $\psi_t$ is differentiable in $t$ and that differentiation and integration can be interchanged.

\begin{align*}
u_t(x|h) &= \int u_t(x|x_0,x_1,h) p_{0,1|t,H}(x_0,x_1|x,h) dx_0dx_1 \\
&= \int \dot{\psi}_t(x_0,x_1|h) \frac{p_{t|0,1,H}(x|x_0,x_1,h)\pi_{0,1|H}(x_0,x_1|h)}{p_{t|H}(x|h)} dx_0dx_1 
\quad \\
&= \mathbb{E}_{X_0,X_1|X_t=x,H=h} \left[ \dot{\psi}_t(X_0,X_1|h) \right]
\quad  \\
&= \mathbb{E}\left[ \dot{\psi}_t(X_0,X_1|h) \ \big| \ X_t=x,H=h \right].
\end{align*}


\end{proof}



\begin{proposition}[Marginalization via Conditional Affine Flows]
Under mild regularity conditions, $q$ have bounded support, and $p$ be $C^1(\mathbb{R}^d)$ with strictly positive density and finite second moments. Given a conditional independent coupling $\pi_{0,1|H}(x_0,x_1|h) = p(x_0|h)q(x_1|h)$, define the marginal probability path via affine interpolation:
\begin{equation}
p_t(x|h) = \int p_{t|0,1,H}(x|x_0,x_1,h)\pi_{0,1|H}(x_0,x_1|h)dx_0dx_1,
\end{equation}
where $X_t = \alpha_t X_1 + \beta_t X_0$ with $\alpha_t,\beta_t \in C^1([0,1])$. Then the marginal velocity field $u_t(x)$ generates a probability path $p_t(x)$ interpolating $p$ and $q$.
\end{proposition}

\begin{proof}
By Lemma~\ref{lemmaa.3}, it suffices to verify: 

1. Conditional integrability: $\int_0^1 \mathbb{E}[\|u_t(X_t|h)\|]dt < \infty.$ 

2. Boundary conditions: $p_0 = p$ and $p_1 = q$

For the affine flow $X_t = \alpha_tX_1 + \beta_tX_0$, the velocity field is:
\begin{align*}
u_t(X_t|h) &= \dot{\alpha}_tX_1 + \dot{\beta}_tX_0 \\
\mathbb{E}[\|u_t(X_t|h)\|] &\leq |\dot{\alpha}_t|\mathbb{E}[\|X_1\|] + |\dot{\beta}_t|\mathbb{E}[\|X_0\|]
\end{align*}
Since $q$ has bounded support, $\mathbb{E}[\|X_1\|] < C_q < \infty$. For $p$ with finite second moments:
\begin{equation*}
\mathbb{E}[\|X_0\|] \leq \sqrt{\mathbb{E}[\|X_0\|^2]} < \infty
\end{equation*}
The time integrals satisfy:
\begin{equation*}
\int_0^1(|\dot{\alpha}_t|C_q + |\dot{\beta}_t|C_p)dt \leq C(\|\dot{\alpha}\|_{L^1} + \|\dot{\beta}\|_{L^1}) < \infty
\end{equation*}
At endpoints:
\begin{align*}
t=0:& \quad X_0 = 0\cdot X_1 + 1\cdot X_0 \sim p(\cdot|h) \\
t=1:& \quad X_1 = 1\cdot X_1 + 0\cdot X_0 \sim q(\cdot|h)
\end{align*}
Marginalizing over $h$ preserves the boundary conditions. 
\end{proof}

\begin{proposition}[Noise Smoothing]
    Let \( X \in \mathbb{R}^{C \times F} \) be a time series with distribution \( P_{\text{ori}} \). Define the perturbed series \( R \) as
    \begin{equation}
            R = X + \sigma \epsilon,
    \end{equation}
    where \( \epsilon \sim \mathcal{N}(0, I) \) is additive Gaussian noise and \( \sigma > 0 \). Then, the perturbed series \( R \) follows the distribution \( P_{\text{per}} \):
    \begin{equation}
        P_{\text{per}}(r) = \int P_X(r - \sigma \epsilon) P_\epsilon(\epsilon) \, d\epsilon,
    \end{equation}
    which belongs to \( C^1(\mathbb{R}^d) \). Furthermore, \( P_{\text{per}} \) has a strictly positive density and possesses finite second moments.
\end{proposition}

\begin{proof}
Assume \( X \) and \( \epsilon \) are independent, and \( P_X \) is a probability density function. By independence of \( X \) and \( \epsilon \), the density of \( R = X + \sigma \epsilon \) is given by the convolution:
\[
P_{\text{per}}(r) = \int P_X(r - \sigma \epsilon) P_\epsilon(\epsilon) \, d\epsilon.
\]


The Gaussian density \( P_\epsilon(\epsilon) = (2\pi)^{-d/2} e^{-\|\epsilon\|^2/2} \) is infinitely differentiable (\( C^\infty \)). Convolution with \( P_X \) preserves smoothness. Specifically:
\[
\nabla_r P_{\text{per}}(r) = \int \nabla_r P_X(r - \sigma \epsilon) P_\epsilon(\epsilon) \, d\epsilon.
\]
Since \( P_\epsilon \in C^\infty \) and decays exponentially, differentiation under the integral sign is justified by dominated convergence. Thus, \( P_{\text{per}} \in C^1(\mathbb{R}^d) \). For any \( r \in \mathbb{R}^d \), since \( P_\epsilon(\epsilon) > 0 \) everywhere and \( \sigma > 0 \), there exists \( \epsilon \) such that \( P_X(r - \sigma \epsilon) > 0 \). Hence:
\[
P_{\text{per}}(r) = \int P_X(r - \sigma \epsilon) P_\epsilon(\epsilon) d\epsilon > 0.
\]
\[
\mathbb{E}[\|X + \sigma \epsilon\|^2] = \mathbb{E}[\|X\|^2] + 2\sigma \mathbb{E}[X^\top \epsilon] + \sigma^2 \mathbb{E}[\|\epsilon\|^2].
\]
By independence, \( \mathbb{E}[X^\top \epsilon] = \mathbb{E}[X]^\top \mathbb{E}[\epsilon] = 0 \). Since \( \epsilon \sim \mathcal{N}(0, I) \), \( \mathbb{E}[\|\epsilon\|^2] = d < \infty \).\( X \) is a time series with \( \mathbb{E}[\|X\|^2] < \infty \), all terms are finite, implying \( \mathbb{E}[\|R\|^2] < \infty \).
\end{proof}




\begin{proposition}
\label{prop:gradient_equivalence}
Let \( t \in [0,1] \), \( H \sim p_H \), \( (X_0,X_1) \sim \pi_{0,1|H} \), and \( X_t \) be generated by a bridge process conditioned on \( (X_0,X_1,H) \). Define:
\( \mathcal{L}_{GM}(\theta) = \mathbb{E}_{t,H,X_t} \| u_t(X_t|H) - u_t^\theta(X_t|H) \|^2 \)
, \( \mathcal{L}_{CGM}(\theta) = \mathbb{E}_{t,H,X_0,X_1} \| g_t(X_0,X_1) - u_t^\theta(X_t|H) \|^2 \)

where \( u_t(x|h) = \mathbb{E}[g_t(X_0,X_1)|X_t=x,H=h] \). Then:

    \[
    \nabla_\theta \mathcal{L}_{GM}(\theta) = \nabla_\theta \mathcal{L}_{CGM}(\theta)
    \]
    \item The minimizer of \( \mathcal{L}_{CGM}(\theta) \) satisfies:
    \[
    u_t^\theta(x|h) = u_t(x|h), \quad \forall x,h,t \ \text{with} \ p_t(x|h) > 0
    \]

\end{proposition}

\begin{proof}
Assume \( u_t^\theta \) is differentiable in \( \theta \), and differentiation commutes with integration. Fix \( t \in [0,1] \) and \( H = h \), define:
\[
X \triangleq X_t|H=h \sim p_t(\cdot|h), \quad Y \triangleq g_t(X_0,X_1)|H=h \ \text{with} \ (X_0,X_1) \sim \pi_{0,1|h}.
\]
By Proposition~\ref{proA.2} applied to \( (X,Y) \), we have:
\begin{align*}
\nabla_\theta \mathbb{E}_{X_0,X_1}\|g_t - u_t^\theta(X_t|h)\|^2 
&= \nabla_\theta \mathbb{E}_{X,Y}\|Y - u_t^\theta(X|h)\|^2 \\
&= \nabla_\theta \mathbb{E}_X \| \mathbb{E}[Y|X] - u_t^\theta(X|h) \|^2 \quad \\
&= \nabla_\theta \mathbb{E}_{X_t}\|u_t(X_t|h) - u_t^\theta(X_t|h)\|^2 \quad 
\end{align*}
Integrate over \( t \sim U[0,1] \) and \( H \sim p_H \):
\begin{align*}
\nabla_\theta \mathcal{L}_{CGM}(\theta) 
&= \mathbb{E}_{t,H}\left[ \nabla_\theta \mathbb{E}_{X_0,X_1}\|g_t - u_t^\theta\|^2 \right] \\
&= \mathbb{E}_{t,H}\left[ \nabla_\theta \mathbb{E}_{X_t}\|u_t - u_t^\theta\|^2 \right] \quad \\
&= \nabla_\theta \mathbb{E}_{t,H,X_t}\|u_t - u_t^\theta\|^2 \\
&= \nabla_\theta \mathcal{L}_{GM}(\theta).
\end{align*}
For optimality, Proposition 1 implies that for each \( t,h \), the minimizer satisfies:
\[
u_t^\theta(x|h) = \mathbb{E}[Y|X=x] = u_t(x|h) \quad \text{a.s. over } p_t(x|h) > 0.
\]
\end{proof}


\subsection{Sampling Algorithm}

\begin{algorithm}[t!]
\label{111}
\caption{$X_1$-Prediction Sampling.}\label{alg:training}
\begin{algorithmic}[1] %[1] enables line numbers
\State \textbf{Input:}   History sample \( h \), smoothing level \( \sigma \), $X_1$-Prediction network \( u^\theta_t \), source mode: noise or auxiliary output, prediction objective $g_t(x_0,x_1)=x_1$, time grid \( t = [t_0, t_1, \dots, t_N] \), where \( t_0 = 0 \) and \( t_N = 1 \).

\State $h \sim p_H$
\State $x_0 \sim p(x_0|h)$
\If {\text{source mode} == \text{auxiliary output}
}
    \State $\varepsilon \sim \mathcal{N}(0, I)$  
    \State $x_0 \gets x_0 + \sigma \varepsilon$  
\EndIf
\For{\( i \gets 0 \) to \( N-1 \)}
    \State \( t_i \gets t[i] \), \( t_{i+1} \gets t[i+1] \)
    \State \( \Delta t_i \gets t_{i+1} - t_i \)
    \State \( u_{t_i} \gets \frac{\dot{\beta}_{t_i}}{\beta_{t_i}} \cdot x_{t_i} + \Big(\dot{\alpha}_{t_i} - \frac{\alpha_{t_i} \dot{\beta}_{t_i}}{\beta_{t_i}}\Big) \cdot u^\theta_{t}(x_{t_i}|h) \)
    \State \( x_{\text{mid}} \gets x_{t_i} + \frac{\Delta t_i}{2} \cdot u_{t_i} \)
    \State \( u_{\text{mid}} \gets \frac{\dot{\beta}_{t_i + \Delta t_i/2}}{\beta_{t_i + \Delta t_i/2}} \cdot x_{\text{mid}} + \Big(\dot{\alpha}_{t_i + \Delta t_i/2} - \frac{\alpha_{t_i + \Delta t_i/2} \dot{\beta}_{t_i + \Delta t_i/2}}{\beta_{t_i + \Delta t_i/2}}\Big) \cdot u^\theta_{t}(x_{\text{mid}}|h) \)
    \State \( x_{t_{i+1}} \gets x_{t_i} + \Delta t_i \cdot u_{\text{mid}} \)
\EndFor
\State \textbf{Output:} \( x_1 \)
\end{algorithmic}
\end{algorithm}

We present the sampling method for CGFM in Algorithm 2 .



\subsection{The Parameterizations of Affine Path \(\alpha_t\) and \(\beta_t\)}  
\label{affine}
The parameterizations of \(\alpha_t\) and \(\beta_t\) for the schedulers used in this work are defined as follows:  
\[
\begin{aligned}
\text{CondOT:} & \quad \alpha_t = t, \quad \beta_t = 1 - t, \\
\text{Poly-n:} & \quad \alpha_t = t^n, \quad \beta_t = 1 - t^n, \\
\text{LinearVP:} & \quad \alpha_t = t, \quad \beta_t = \sqrt{1 - t^2}, \\
\text{Cosine:} & \quad \alpha_t = \sin\left(\frac{\pi t}{2}\right), \quad \beta_t = \cos\left(\frac{\pi t}{2}\right).
\end{aligned}
\]  
Here, \(t \in [0, 1]\) represents the normalized time step, and \(n\) in the Poly-n scheduler is a positive hyperparameter controlling the polynomial degree. Each parameterization is designed to encode distinct behaviors in the dynamics of the scheduling process.

