        % \end{corollary}

        To effectively utilize Proposition \ref{prop:gradient-projection-lower-bound}, we also have to show that its assumption is satisfied. That is, at least one of the weight vectors, $\bvarseq{w}(T)$, produced by Algorithm \ref{algo:projected-stochastic-gradient-descent-for-minimizing-convex-surrogate-loss} has small $\norm{\E{\func{g}<\bvar{w}>[\bvar{x},\lvar{y}]}}<2>$. We show this can be achieved within a bounded number of iterations as the proposition below.
        \begin{proposition}\label{prop:upper-bound-on-the-norm-of-statistic-relu-gradient}
            Let $\distr$ be a distribution on $\reals[d]\times\booldomain$ with standard normal $\bvar{x}$-marginal, $\func{g}<\bvar{w}>[\bvar{x}, y] = y\cdot\bvar{x}<\bvar{w}[\bot]>\cdot\indicator[\bvar{x}\in\hypothesis[\bvar{w}]]$, and $\loss<\distr>{\bvar{w}} = \E<(\bvar{x},\lvar{y})\sim\distr>{y\cdot\max(0, \innerprod{\bvar{x}}{\bvar{w}})}$. With $\beta = \sqrt{1/Td}$, after $T$ iterations, the output $\sbr*{\bvarseq{w}(T)}$ in Algorithm \ref{algo:projected-stochastic-gradient-descent-for-minimizing-convex-surrogate-loss} will satisfy $\E*<\distr*(1),\ldots, \distr*(T)\sim\distr>{1/T\sum_{i=1}^T\norm{\E<(\bvar{x},\lvar{y})\sim\distr>{\func{g}<\bvar{w}(i)>[\bvar{x},\lvar{y}]}}<2>[2]}\leq\sqrt{d/T}$. In addition, if $T \geq \sbr*{4d + \ln\sbr*{1/\delta}}/\epsilon^4$, we have $\min_{i = 1,\ldots,T}\norm{\E<(\bvar{x},\lvar{y})\sim\distr>{\func{g}<\bvar{w}(i)>[\bvar{x},\lvar{y}]}}<2>\leq \epsilon$ with probability at least $1 - \delta$.
        \end{proposition}

        We defer the formal proof to Appendix \ref{sec:convergence-analysis-of-projected-sgd}. Our technique resembles the work of \citet{diakonikolas2020learning}, which showed that, if the objective function is \textbf{bounded} and has \textbf{Lipschitz continuous} gradient, then the norm of its gradient converges in boundedly many iterations of (Projected) SGD. 

