    \centering
    \includegraphics[width=\linewidth]{104_prompt1_ver2-crop.pdf}
    \caption{Example output of the proposed method. The top row is a waveform representation of the user's audio input. The middle and bottom rows indicate probabilities for $p_{now}$ and $p_{future}$, respectively, with blue indicating the user and yellow indicating the system.}
    \label{fig:example1}
\end{figure*}

\begin{figure*}[t]
