  \raggedleft
  \input{figures/FIO-2G.tikz}
  \caption{FIO benchmarks with \SI{2}{\gibi\byte} of NVMM cache}
  \label{fig:FIO-2G}
\end{figure}

\begin{figure}
  \tikzsetnextfilename{fio100}
  \raggedleft
