\begin{example}\label{ex:dec1}
	The network $\mc G$ in Figure \ref{fig:indec} is $(h^{-}, h^{+})$-indecomposable for $h^{+}=(3,2,0,2)=-h^{-} $. To see this, first notice that, for any partition where $|\mc V^+|=|\mc V^-|=2$, node $3$ satifies either \eqref{eq:ind1} or \eqref{eq:ind2} as a direct consequence of the facts that its out-degree is $w_3=3$ and $h_3^-=h_3^+=0$. 
Suppose instead that $|\mc V^-	|=1$. A direct check shows that the node in $\mc V^-$ satisfies \eqref{eq:ind2}. The case when $|\mc V^+|=1$ is identical. %\tcr{VA RIAGGIUNTA UNA PARTE}


	The network $\mc G$ in Figure \ref{fig:indec} is not $(h^{-}, h^{+})$-indecomposable for $h^{+}=\1$ and  $h^{-} = -h^{+}$. Indeed, if we take the partition $\mc V^+=\{1,4\}$ and $\mc V^-=\{2,3\}$, we have that $w_1^{\mc V^+}+h_1^+=3\geq 2= w_1^{\mc V^-}$, $w_4^{\mc V^+}+h_4^+=3\geq 1 = w_4^{\mc V^-}$, $w_2^{\mc V^+}-h_2^-=2\geq 1= w_2^{\mc V^+}$ and $w_3^{\mc V^-}-h_3^-=2\geq 2=w_3^{\mc V^+}$. Then, $\nexists i$ in $\mc V^+$ or $\mc V^-$ such that either \eqref{eq:ind1} or \eqref{eq:ind2} is violated.
\end{example}

%The indecomposability property introduced in Definition \ref{def:indecomp} can be given the following interpretation in terms of robustness of SNC games. Consider a strategic game with player set $\mc V$, action space $\mc A=\{\pm1\}$ for every player, and utility functions  
%\be\label{utility-netcoord} u_i(x)=x_i\sum_{j\in\mc V} W_{ij}x_j+h_ix_i\,,\ee 
%for every player $i$ in $\mc V$, 
Consider a SNC game with binary actions on a network $\mc G=(\mc V,\mc E,W)$ with external field $h$ such that 
\be\label{h-bounds} h^-_i\le h_i\le h_i^+\,,\qquad\forall i\in\mc V\,.\ee
Given a binary partition as in \eqref{binarypartition+-}, consider the strategy profile $x$ in $\mc X$ with  $$x_{\mc V^+}=\1\,,\qquad x_{\mc V^-}=-\1\,.$$ 
Then, conditions \eqref{eq:ind1} and \eqref{eq:ind2} imply that there exists a player $i$ in either  $\mc V^+$ or $\mc V^-$  that is not playing best response in strategy profile $x$. This implies that the SNC game on $\mc G$ with eternal field $h$  admits no coexistent Nash equilibria, i.e., no Nash equilibria other than, possibly, consensus strategy profiles. Notice that the absence of coexistent Nash equilibria implied by the $(h^-,h^+)$-indecomposability of the graph is robust with respect to changes of the vector $h$ in the hyper-rectangle $\{h\in\R^{\mc V}:\,\eqref{h-bounds}\}$.


We will make use of a result in \cite{arditti2024robust} that ensures, for network coordination games on $(h^-,h^+)$-indecomposable unsigned networks, the existence of a BR-path from every strategy profile $x$ to a consensus strategy profile that is independent from the specific choice of the vector $h$ satisfying \eqref{h-bounds}. Precisely, \cite[Theorem 4(i)]{arditti2024robust} implies the following.

\begin{lemma}\label{lemma-robust}  Consider an unsigned network $\mc G= (\mc V, \mc E, W) $ and two vectors  $h^-$, $h^+$ in $\R^\mc V$ for which $\mc G$ is $(h^-,h^+)$-indecomposable. Then, for every strategy profile $x^{(0)}$ in $\mc X$, there exists an $l$-tuple of strategy profiles $(x^{(1)},\ldots,x^{(l)})$,  with $1\le l\leq n$, such that $x^{(l)}\in\{\pm\1\}$ is a consensus  profile, and $(x^{(0)},x^{(1)},\ldots,x^{(l)})$ is a BR-path for every SNC game with binary actions on $\mc G$ with external field $h$ satisfying \eqref{h-bounds}. 

\end{lemma}

We can now get the following result.



\begin{proposition}\label{prop:stability}
Consider a SNC game with binary actions on a network $\mc G=(\mc V,\mc E,W)$ with external field $h$ and a binary partition \eqref{binary-partition} such that $\mc G_{\mc R}$ is unsigned. Let $h^-$ and $h^+$ in $\R^{\mc R}$ be the vectors with entries 
\be\label{h+-}h^+_i=h_i+w_i^{{\mc S}}\,, \qquad h^-_i=h_i-w_i^{{\mc S}}\,,\qquad\forall i\in\mc R\,.\ee
Assume that $\mc G_{\mc R}$ is $(h^-,h^+)$-indecomposable and 
\be\label{wRi}w^{{\mc R}}_i -|h_i|> w^{{\mc S}}_i\,,\qquad\forall i\in\mc R\,.\ee
Then:  
\begin{enumerate}
\item[(i)] if, for every $a$ in $\{\pm1\}$, the set 
$\mc N_{{\mc S}}^{(a\1)}$  is globally BR-reachable for the $\mc S$-restricted SNC game with action profile of players in $\mc R$ frozen to $a\1$, 
then, the subset  of Nash equilibria \be\label{tildeN}\tilde{\mc N}=\{x^*\in\mc N:\,x^*_{\mc R}\in\{\pm\1\}\}\,,\ee  is non-empty and globally BR-reachable. 
	\end{enumerate}
	Moreover: 
	\begin{enumerate}
	\item[(ii)] if, for every $a$ in $\{\pm1\}$, there exists a non-empty subset $\bar{\mc N}_{{\mc S}}^{(a\1)}\subseteq \mc N_{{\mc S}}^{(a\1)}$ that is globally BR-stable for the $\mc S$-restricted SNC game with action profile of players in $\mc R$ frozen to $a\1$, then there exists a non-empty globally BR-stable subset $\ov{\mc N}\subseteq\tilde{\mc N}$. 
\end{enumerate}
\end{proposition}

\begin{IEEEproof} 
Fix an arbitrary strategy profile $x$ in $\mc X$ and let $z=x_{\mc S}$. 
On the one hand, since the subnetwork $\mc G_{\mc R}$ is unsigned and $(h^-,h^+)$-indecomposable, Lemma \ref{lemma-robust} implies that the set of consensus strategy profiles $\{\pm\1\}\subseteq\mc X_{\mc R}$ is globally BR-reachable for the $\mc R$-restricted network coordination game with action profile of players in $\mc S$ frozen to $z$, so that there exists a length-$l$ BR-path $((y^{(0)},z),(y^{(1)},z),\ldots,(y^{(l)},z))$ with $y^{(0)}=x_{\mc R}$ and $y^{(l)}=a\1$, for some $a$ in $\{\pm1\}$. 
	On the other hand, since the set $\mc N_{{\mc S}}^{(a\1)}$  is globally BR-reachable for the $\mc S$-restricted SNC game with action profile of players in $\mc R$ frozen to $y=a\1$, there exists a length-$m$ BR-path 
	$((a\1,z^{(0)}),(a\1,z^{(1)}),\ldots,(a\1,z^{(m)}))$ with $z^{(0)}=z$ and $z^{(m)}=z^*\in\mc N_{{\mc S}}^{(a\1)}$. 

	Observe that the strategy profile $x^*$ in $\mc X$ with $x^*_{\mc R}=a\1$ and  $x^*_{\mc S}=z^*$ is a Nash equilibrium for the original SNC game with binary actions on $\mc G$ with external field $h$, as every player $i$ in $\mc R$ is playing best response thanks to \eqref{wRi}, while every player $j$ in $\mc S$ is playing best response since $z^*\in\mc N_{{\mc S}}^{(a\1)}$. We have thus found a length-$(l+m)$ BR-path 
	$((y,z),(y^{(1)},z),\ldots,(a\1,z),(a\1,z^{(1)}),\ldots,(a\1,z^*))$ from $x$ to $x^*$ in $\mc N$ with $x^*_{\mc R}=a\1$. 
	The arbitrariness of initial strategy profile $x$ in $\mc X$ implies that the set $\tilde{\mc N}$ defined in \eqref{tildeN}, i.e., the subset of Nash equilibria in which players in $\mc R$ are at consensus is globally BR-reachable, thus proving point (i) of the claim. 

	To prove point (ii) of the claim, let $a$ in $\{\pm1\}$ be as above. Since there exists a non-empty subset $\bar{\mc N}_{{\mc S}}^{(a\1)}\subseteq \mc N_{{\mc S}}^{(a\1)}$ that is globally BR-stable for the $\mc S$-restricted SNC game with strategy profile of players in $\mc R$ frozen to $a\1$, then the BR-path above can be constructed leading to $x^*$ such that $x^*_{\mc S}\in\bar{\mc N}_{{\mc S}}^{(a\1)}$. Now, notice that assumption \eqref{wRi} implies that,  in the strategy profile $x^*$ defined above, every player $i$ in ${\mc R}$ is playing a strict best response $\mc B_i(x^*_{-i})=\{a\}$. This, combined with the BR-invariance of $\ov{\mc N}_{\mc S}^{(a\1)}$ for the $\mc S$-restricted SNC game with strategy profile of players in $\mc R$ frozen to $a\1$, implies that 
	$$\ov{\mc N}=\{x^*\in\mc X:\,x^*_{\mc R}\in\{\pm\1\}\,,\, x^*_{\mc S}\in\bar{\mc N}_{{\mc S}}^{(x^*_{\mc R})}\}\,,$$
	is a non-empty, globally BR-stable subset of Nash equilibria, thus proving point (ii) of the claim. 
	\end{IEEEproof}

\begin{remark} In the special case of a network coordination game, i.e., when the network $\mc G$ is unsigned, Proposition \ref{prop:stability} provides sufficient conditions for consensus strategy profiles $\pm\1$ to be Nash equilibria and form a globally BR-reachable set. In this setting, the assumptions reduce to the following two conditions: (a) that $\mc G_{\mc R}$ is $(h^-,h^+)$-indecomposable; and (b) that $w_i>|h_i|$ for every $i$ in $\mc V$. Condition (a) ensures that no coexistent Nash equilibrium exists, while condition (b) ensures that both consensus strategy profiles $\pm\1$ are strict Nash equilibria. We notice that in this case conditions (a) and (b) are not just sufficient but also necessary for the set $\{\pm\1\}$ of consensus strategy profiles to be globally BR-stable. 
\end{remark}

We now present the following result extending Proposition \ref{prop:stability} to cases when $\mc G_{\mc R}$ is structurally balanced rather than unsigned. 

\begin{theorem}\label{theo:main-stability}
	Consider a SNC game with binary actions on a network $\mc G=(\mc V,\mc E,W)$ with external field $h$. 
	 Consider a binary partition as in \eqref{binary-partition}, such that $\mc G_\mc R$ is structurally balanced 
	 and let $\tau$ in $\mc X_{\mc R}$ be such that $\mc G_{\mc R}^{[\tau]}$ is unsigned. 
	Let $h^-$ and $h^+$ in $\R^{\mc R}$ be the vectors with entries 
\be\label{h+-tau}h^+_i=\tau_ih_i+w_i^{{\mc S}}\,, \qquad h^-_i=\tau_ih_i-w_i^{{\mc S}}\,,\qquad\forall i\in\mc R\,.\ee
Assume that $\mc G_{\mc R}^{[\tau]}$ is $(h^-,h^+)$-indecomposable and that \eqref{wRi} holds true. 
%\be\label{wRi}w^{{\mc R}}_i -|h_i|> w^{{\mc S}}_i\,,\qquad\forall i\in\mc R\,.\ee
Then:  
\begin{enumerate}
\item[(i)] if, for $y=\pm\tau$ in $\mc X_{\mc R}$, the set 
$\mc N_{{\mc S}}^{(y)}$  is globally BR-reachable for the $\mc S$-restricted SNC game with the strategy profile in $\mc R$ frozen to $y$, 
then, the subset of Nash equilibria \be\label{Ntau}\ov {\mc N}=\{x^*\in\mc N:x^*_{\mc R}\in\{\pm\tau\}\}\,,\ee  is globally BR-reachable. 
	\end{enumerate}
	Moreover: 
	\begin{enumerate}
	\item[(ii)] if, for $y=\pm\tau$ in $\mc X_{\mc R}$, there exists a non-empty subset $\bar{\mc N}_{{\mc S}}^{(y)}\subseteq \mc N_{{\mc S}}^{(y)}$ that is globally BR-stable for the $\mc S$-restricted SNC game where actions of players in $\mc R$ are frozen to $y$, then 
	there exists a globally BR-stable subset of Nash equilibria contained in $\ov{\mc N}$. 
\end{enumerate}
\end{theorem}
\begin{IEEEproof}
Let $\sigma$ in $\mc X$ be such that $\sigma_{\mc R}=\tau$ and $\sigma_{\mc S}=\1$. %In the forthcoming derivations, we will indicate $\sigma=(\tau,\1)$.
Consider the  associated gauge transformation $[\sigma]$ and the $[\sigma]$-transformed network  $\mc G^{[\sigma]}$. Observe that the assumptions ensure that $(\mc G^{[\sigma]})_{\mc R}=\mc G_{\mc R}^{[\tau]}$ is unsigned, that $\mc G_{\mc R}$ is $(h^-,h^+)$-indecomposable and that \eqref{wRi} holds true. We can thus apply Proposition \eqref{prop:stability} to the $[\sigma]$-transformed SNC game, whose points (i) and (ii) imply, respectively, points (i) and (ii) of the claim. 
\end{IEEEproof}\medskip



Similarly to Section \ref{sec:existence}, we may derive the following two corollaries from Theorem \ref{theo:main-stability}.

\begin{corollary}\label{coro:reach} 
Consider a SNC game on a network $\mc G=(\mc V,\mc E,W)$ with external field $h$. 
Consider a binary partition as in \eqref{binary-partition} such that $\mc G_{\mc R}$ and $\mc G_{\mc S}$ are both structurally balanced, and let $\tau$ in $\mc X_{\mc R}$ be such that $\mc G_{\mc R}^{[\tau]}$ is unsigned. Let $h^-$ and $h^+$ in $\R^{\mc R}$ be the vectors with entries as in \eqref{h+-}.
If $\mc G_{\mc R}$ is $(h^-,h^+)$-indecomposable and \eqref{wRi} holds true, then the subset of Nash equilibria \eqref{Ntau} is globally BR-reachable.
\end{corollary}
\begin{IEEEproof} If the subnetwork $\mc G_{\mc S}$ is structurally balanced, then, for every $\tau$ in $\mc X_{\mc R}$, Proposition \ref{prop:structurally-balanced-equilibria} implies that the set  $\mc N_{{\mc S}}^{(y)}$  is globally BR-reachable for the $\mc S$-restricted SNC game with the strategy profile in $\mc R$ frozen to $y=\pm\tau$. 
The claim then follows from Theorem \ref{theo:main-stability}(i). 
\end{IEEEproof}
