%\alpha(0) < \alpha(1) + 1 \text{ and } \beta(0) = 1\right\}\\
% \cup \left\{\DPtree_G[\alpha, \beta] \mid
%\alpha(0) > \alpha(1) + 1 \text{ and } \beta(1) = 1\right\} \\
% \cup \left\{\DPtree_G[\alpha, \beta] + 1 \mid
%\beta(1) = 1\right\}.
